window.__D("text/torat-chaim/c012",{"p":[[2300680181,"רוממות המקיף הכללי שהוא מחשבה הכללית שסוקר הכל בסקירה אחת לראש וסוף כאחד כו' האיך יכול להיות שבשעה זו עצמו שמגביהי לשבת כנ\"ל הוא משפיל את עצמו לראות ולהשגיח בהשגחה פרטית למטה מטה על כל הברואים ממש וכן מ\"ש משמים שהוא מחשבה הכללית בחי' סוכ\"ע הכללי הנ\"ל הביט ה' וראה בהשגחה פרטית על כל בני האדם כמ\"ש עיניך פקוחות על כל דרכי בני אדם כו' ממכון שבתו ברוממות דמחשבה העצמית משגיח על כל וכן מ\"ש שיוצר יחד בכללות כולם לבם ומבין ומשגיח בפרטיות אל כל מעשיהם שכל זה הוא דבר והפוכו ממש שאם מרומם ומובדל הוא שראש וסוף שוין שם איך יצמצם את עצמו בכל פרט ופרט בכל נברא דאם נסקרים הכל בסקירה אחת הרי אין תופסים מקום כלל וכלל וא\"כ איך הוא משגיח בכל פרטי פרטיהם הרי כל אחד ואחד תופס מקום בפ\"ע שזהו ב' הפכים ממש. אך הענין הוא דשניהם אמת והא בהא תליא דוקא דהיא הנותנת משום דמגביהי לשבת ע\"כ משפילי לראות בהשגחה פרטיות וכן משמים הביט כו' כנ\"ל להיות שאם היה בחי' מחשבה הכללית הנ\"ל תופס מקום אצלו ית' והיה נתפס בה עכ\"פ אז לא היה יכול להיות שיוכל להיות השגחה פרטית שיתפס מחשבה בכל פרט ופרט שזהו כדבר והפוכו (כמו באדם התחתון כשמרגיש את עצמו בכלל אי אפשר שירגיש בפרט אע\"פ שהפרט יצא מן הכלל ואם באה מחשבה בפרט באבר אחד לא יהיה אז הרגשה בכללית שא\"א להיות מחשבה כללית ופרטית כאחת ממש) אבל באמת הרי אמר דלמתב\"כ אפי' מח' הכללית שאינו נתפס בה כלל משום דכלא חשיבי ממש לגבי עצמות אא\"ס שנבדל בערך גם מבחי' אותיות כנ\"ל א\"כ יכול להיות דבר והפוכו דוקא שבשעה ורגע שסוקר הכל כאחד במח' הכללית הנ\"ל אז הוא משפיל את עצמו להשגיח בכל פרט ופרט ואינו נתפס כלל בהשגחה פרטית זו ולא נחשב למאומה כמו שלא נתפס במחשבה הכללית משום דכלל עם הפרט שניהם שוין לפני העצמות מאחר שהוא מובדל ומושלל גם מכל בחי' מקור למקור להשתלשלות בכלל ובפרט כנ\"ל א\"כ ידיעה כללית וידיעה פרטית כאחד באים אצלו בשוה ממש וד\"ל. וז\"ש המגביהי ביו\"ד דחכ' בראש ומשפילי ביו\"ד דחכ' בסוף בפרטית הכל כאחד להיותו למעלה מבחי' ראש וסוף כלל ופרט כו' וכן מ\"ש משמים הביט וראה את כל בני האדם בהשגחה פרטית כו' וד\"ל ועכ\"ז הרי אמר איהו תפיס בכל עלמין רק דלמדתב\"כ כו' וזהו דבר והפוכו אם תפיס בכל עלמין למה למדתב\"כ א\"כ נתפס ואינו נתפס ב' הפכים כאחד וכן ענין הוא מקומו של עולם ואין העולם מקומו כלל לפי שגם זה אמת דאיהו ממש תפיס בכ\"ע גם במח' הפרטית בפרטי השגחת הברואים על כל חלקי דצח\"מ דעשי' עד שנחשב בחי' פרטיות מחשבה והבטה זו לבחי' יש ודבר מה שתופס מקום ונתפס בה כל פרט כו' וכ\"ש במח' הכללית שנתפס בה בתחלה ואח\"כ נתחלקה בפרטיות ועכ\"ז הרי גם המחשבה הכללית כלא חשיבא שאינה רק סקירה אחת ולמתב\"כ כנ\"ל וגם זה אמת ואין זה דבר והפוכו כלל וכלל מטעם הנ\"ל להיות הוא ית'"],[2300680195,"מובדל ומרומם לבדו מכל ההשתלשלות כו' ע\"כ יכול להיות דבר והפוכו שיהיה נתפס בכל עלמין בכלל וגם בפרט דוקא ולמדתב\"כ וז\"ש כי לא מחשבותי מחשבותיכם כו' פי' כי לא כמחשבת אדם שנתפס בה בכלל ובפרט ולא יוכל לפשוט א\"ע לכך אי אפשר להיות בכלל ובפרט כאחד ולהיות נתפס ואינו נתפס כלל כו' אבל מחשבותי אינו כמחשבותיכם שאינו נתפס כלל במחשבה הכללית והפרטית ושניהם שוין וע\"כ יכול להיות נתפס ואינו נתפס כאחד ממש ולא כמו שאדם פושט ולובש וחוזר ופושט שבשעה שלובש הלבוש נתפס בו אלא לא נתפס כלל גם בהיותו מלובש במחשבה גם במחשבה הפרטית בהשגחה האלקית על כל כו' כמו המבין אל כל מעשיהם או לזון ולפרנס לכל בשר כו' דודאי גם זה אמת שנתפס בכל פרט ולא יחשב מחשבה זו הפרטית כדבר מחשבה זרה באדם ח\"ו כי ממך הכל כתיב ואין לך דבר חוץ ממנו וא\"כ גם מחשבה שמשגיח בפרטי פרטיות בכל חי ומח' העצמית כאחד שע\"כ אמר כי לא מחשבותי כו' דלא כמחשבת אדם שהוא חושב דבר חוץ ממנו ונחשב כזר אצלו ולא כן מחשבותי כו' שמיוחדים בעצמותו כי ממנו הכל בכלל ובפרט ועכ\"ז אינו נתפס במח' הכללית ופרטית ושניהם אמת כנ\"ל וד\"ל:\n(ז) <b>והנה</b> ע\"ד כ\"ז יובן ג\"כ ענין ובחי' יוסף צ\"ע למעלה מעלה בעצמות אין סוף ב\"ה כמו שהיה יוסף למטה שהיה טרוד גדול מאד בטרדות עצומות בעומק ההשגחה פרטית בבית ושדה וכן בעניני הנהגות המלוכה על כל יושבי הארץ ועכ\"ז לא היה לו מזה שום בלבול כלל לעוצם הדביקות שלו למעלה כנ\"ל לפי שהיה יוסף בחי' מרכבה לעצמות אא\"ס ב\"ה דלמתב\"כ אפילו מחשבה הכללית שאינו תופס מקום כלל והיה נשמת יוסף כלולה מבחי' מחשבה כללית שצופה ומביט בסקירה אחת כו' שזהו בחי' סוכ\"ע הכללי ועכ\"ז היה יכול להשגיח למטה בפרטי פרטיות ואין זה ב' הפכים כלל מטעם הנ\"ל וד\"ל. וכך הוא למעלה בעצמות א\"ס שמלובש במח' הכללית ומשגיח על כל פרט ונק' מלך הגוים כמ\"ש מלך אלהים על גוים כו' כמו שהי' יוסף משביר בר ומושל על כל כו' דהיינו בהשגחה עמוקה בפרטות דוקא על כל מלכי האדמה כו' וכמזלות ודצח\"מ ועכ\"ז הרי הוא בבחי' א\"ס כמו שהוא ואינו נתפס כלל כמאמר איהו תפיס בכל עלמין ולמדת\"ב אפי' מחשבה הכללית כו' וכמו שהיה יוסף מלך על כל הגוים בטרדא רבה והיה מרכבה ממש לבחי' צ\"ע שהוא עצמות א\"ס כשיורד ומתלבש להשפיע במחשבה כללית ופרטית כנ\"ל וד\"ל. וזהו שהיה יוסף מלך על כל מצרים בטרדה רבה ביותר ובהשגחה פרטית והיה מרכבה למעלה ולא היה זה אצלו ב' הפכים כלל לפי שלא היה תופס מקום אצלו כלל (להיותו מרכבה לבחי' סובב הכללי דאצי' ועשי' שוין שם מאחר שמקיף לד' עולמות בשוה מראש לסוף כא' ומה גם למעלה ממח' הכללית דלמתב\"כ) ע\"כ לא היה צריך להפשיט א\"ע מטרדות העולם לבא בבחי' ביטול העצמי לאין כי גם בהיותו מלובש בטרדות העולם אינו נתפס בהם כלל כנ\"ל בפי' כי לא מחשבותי כו' משא\"כ בחי' השבטים שהי' בבריאה שלאחר מסך המבדיל בין אצי' לבריאה היו צריכים לבא"],[2300680209,"בבחי' ביטול היש בהפשטות הגשמיות תחלה ואז היו יכולים לעלות באצי' כמ\"ש ששם עלו כו' וע\"כ היו רועי צאן שלא יבלבלו לדביקות שלהם טרדות העולם להיותם באצי' שמוסתר בבריאה כו' אבל יוסף היה שרשו במקור הכללי שלמעלה מאצי' ובריאה כנ\"ל ובזה יתרון מעלתו גם על האבות שהיו מרכבה באצי' ממש ועכ\"ז היו רועי צאן ולא רצו בטרדות העולם (אע\"פ שאין המסך מבדיל להם כלל וכמ\"ש במ\"א שזהו מ\"ש אלה הגבורים כו' בלא לב ולב שניהם שוין כמו אם זכרתיך על יצועי בבחי' הקטנות זהו כמו באשמורות בק\"ש במס\"נ ממש בשוה שאין קטנות וגדלות המוחין שייך רק בביטול היש לאין לעלות מבריאה לאצי' כו' אבל באצי' עצמו שוין קטנות וגדלות בלא לב זהו כמו בלב כו' מטעם הנ\"ל דאין העולם תופס מקום כלל אחר שאין הצמצום מסתיר כלל עד שיהיה צריך להפשיט א\"ע כו') להיות מבואר למעלה בשרש יוסף שהיה מבחי' מלך הח' כו' שלמעלה מבחי' התוהו והתיקון שבכחו יכול לתקן צירופים זרים דתוהו להביאם למעלה מעלה מבחי' שרש דתוהו ולעשות בהם שרש ומקור לבחי' התיקון דהיינו איך שיהיה אופן וסדר הצירופים בחבור וקשר דכל ההפכים שיבא כאחד על מקומו כו' שזהו ענין פתרון החלומות שכאשר פתר בפה אופן הצירופים כן היה התיקון בחלומות דתוהו שנמצא ממנו מקור לבחינת התיקון דאצי' שיהיה אופן התיקון דמ\"ה לב\"ן כו' כנ\"ל ובזה היה יתרון מעלתו הרבה גם מן האבות ונק' פותר ותופר כי האבות היו רק בבחי' התיקון דאצי' בג' קווין דאצי' שמהם יצאו השבטים בבריאה ג\"כ בבחי' התיקון בציור אדם ברמ\"ח אברים שזהו לאחר שנעשה ונגמר בחי' התיקון שהוא למדוד האורות בכלים מכלים שונים כמו שידוע בסדר בציור מעמד ומצב השבטים בציור קומת אדם כמו שבטים האחרונים גד ואשר גד גדוד כו' והוא יגד עקב אשר טובל בשמן רגלו שהן ב' רגלים דימין ושמאל וזבולון ויששכר תרין ירכין דכתי' בזבולון וירכתו על צידון כו' ובבנימין אמר ובין כתיפיו שכן וכה\"ג להיותם בבחי' אדם בדוגמא לאדם העליון דאצי' שהן האבות שהוא לאחר שכבר נמדדו האורות בכלים בבחי' י\"ב ג\"א באצי' ובבריאה אבל בחי' יוסף היה מקור הראשון שלמעלה מתוהו ותיקון דמשם נמצא שרש ומקור לסדר מדידה זו דאורות וכלים דתיקון דאצי' כנ\"ל וד\"ל. ומזה הטעם יובן יותר מה שלא היה מבלבל אותו טרדות צירופים זרים דעולם הזה שהן בחינת החלומות דתוהו מאחר שהיה יודע בשרש ומקור התיקון שלהם למעלה שנק' תופר ופותר כו' כנ\"ל א\"כ איך יבלבלו אותו מכמו שהוא במקורו בבחי' מלך הח' (שהוא שם מ\"ה החדש דא\"ק כו') אחר שהוא למעלה מהם המתקן אותם כו' וד\"ל. ובכל זה יובן מה שכל עליות דיוסף היה דוקא ע\"י פתרון החלומות כי זהו שרשו במקור התיקון דבחי' התוהו שמשם נמשך וירד בצירופים זרים ומבולבלים דחלומות שנק' קדרות ולבוש שק כנ\"ל. אך השבטים שנאו אותו ביותר על דבר החלומות שלו וקראוהו בעל החלומות כו' כי שרש השבטים בעולם הבריאה בי\"ב ג\"א דו\"ק דבריאה שלמטה הרבה מבחי' יוסף שהיה למעלה מבחי' התוהו שלזה נק' פותר חלומות"],[2300680222,"והם קראוהו בעל החלומות שהיו סבורים שהוא בבחי' ירידה ונפילה דניצוצות דתוהו שנתלבשו בחלומות והם היו מבחינת התיקון דבריאה עכ\"פ ע\"כ שנאו אותו מאד והיה אצלם בפחיתת הערך לקרותו בעל החלומות שלמטה בנפילה שנק' לבוש שק שע\"ז אמר החלומות שוא ידברו שהן שוא דק\"נ וכזב ושקר שרשו וטעו מאד בזה כי באמת היה בעל החלומות שלמעלה בבחי' המקור לתיקון לחלומות דאורות דתוהו עצמו שהוא מלך הח' הנ\"ל שמתקן לז\"מ דתוהו להיותו למעלה מהם הרבה כידוע וד\"ל:\n(ח) <b>וזהו</b> הטעם שלא הכירו השבטים ליוסף שהוא עברי כשהיה מלך על כל מצרים והיו סבורים שהוא מצרי גמור וזה פלא גדול על נשמות גבוהות כמו השבטים שהיו מרכבה לו\"ק דבריאה (ואמרו כך אין בלבנו אלא אחד שזהו יחו\"ת דמל' בבי\"ע כידוע) איך לא השיגו בנשמתו שהוא עברי עכ\"פ ולא מצרי. אך הענין הוא מטעם הנ\"ל שמצד עוצם התרחקותם כ\"כ ממעלת ומדריגת יוסף (שהיה למעלה גם מז\"מ דתוהו והם היו למטה מתיקון דאצי' כנ\"ל) ע\"כ לא השיגוהו כלל וכלל כי נבדל היה ומרומם מערכם בתכלית ואדרבה היו סבורים שהוא מצרי להיותו מלך על גוים בטרדה רבה שסובל כמה הפכים שאי אפשר שיהיה עברי הרי בהיות החלומות שהן צירופים הזרים דעוה\"ז בלא בחי' התיקון עדיין הרי נק' לבוש שק ממש להסתיר אור האלקי לגמרי ואיך יהיה דבוק למעלה באלקים חיים שמפני זה היו הם רועי צאן כנ\"ל וע\"כ היו סבורים שהוא מצרי ממש שהוא מק\"נ ממש שנפל שם מבחי' התוהו כידוע אבל הם טעו בזה מאד מצד התרחקם ממעלת ומדריגת יוסף כי לא היה נשמתו בצירופים זרים דחלומות עצמן שלמטה אלא היה נשמתו הרבה למעלה גם מז\"מ דתוהו עצמן דהיינו למעלה משרש החלומות בבחי' התוהו עצמו שהוא מלך הח' הדר שמתקן אותם ונק' פותר חלומות ע\"כ לא הכירוהו השבטים והיו סבורים שהוא מצרי ומלך על מצרים כפרעה שהוא מל' דק\"נ כמ\"ש כי כמוך כפרעה וד\"ל. ובכ\"ז יובן ענין החלומות דיוסף עצמו שראה מה שעתיד להיות מלך ואחיו ואביו ישתחוו לו כמ\"ש השמש והירח כו' ואביו שמר את הדבר (כמ\"ש לעיל בפ' וישב בענין מאלמים כו') כי הנה מה שהיה פותר חלומות במצרים זה היה בסוד גלות יוסף בק\"נ כמ\"ש ויוסף הורד מצרימה כו' וגם בק\"נ בעה\"ד טו\"ר היה פותר חלומות דתוהו שבתערובות טו\"ר וכאשר פתר כן היה להבדיל האמת מן השקר והטוב מן הרע להעמיד לכל אחד ואחד על מקומו כמו לשר המשקים טוב פתר שהיה מסטרא דטוב ע\"כ ראה גפן וג' שריגים שהן ג' אבות כמ\"ש בזוהר ולשר האופים שהיה בסט' דרע פתר לרע כו' וכן בחלום פרעה מל' דק\"נ היה טו\"ר בחלומות ז' פרות טובות וז' פרות רעות והרעות בלעו לטובות ופתר לטוב ולרע ז' פרות טובות שיהיה ז' שנים טובות וז' פרות רעות ז' שנים רעות כו' וכ\"ז בתערובות טו\"ר שנפלו למטה מאד אבל בחלומות שחלם בעצמו בהיותו למעלה במקורו ושרשו בשם מ\"ה החדש כו' שלפני התוהו והתיקון שם יכול להיות"],[2300680234,"כל ההפכים יחדיו ישכנו בלי צריך לפתרון לברר בבחי' בירור והבדלה כלל כי כולו אמת גם בדמיון החלום (וכמו בחלום אדבר במראה הנבואה שכולו אמת) (כמו משל הנ\"ל בכחות עצם הנפש שמתחלקים בימים ושנים שבכל ימי חייו בטו\"ר התנשאות וירידה או רצון ושכל טו\"ר וכלולי' כולם בעצם הנפש בהולדו או במותו כו' וד\"ל). וזהו מה שהראו לו בחלומו דיוסף שרש בחי' התיקון שהוא מלך הח' מה שאביו ואמו ואחיו גם שהן בבחי' התיקון דאצי' בי\"ב ג\"א כו' כידוע שהן משתחוים ליוסף לקבל ממנו שרש ההמשכה להיות בהם כח התיקון כי גם שישראל ויעקב דאצי' וגם השבטים דבריאה כבר הם בבחי' התיקון אבל יוסף שהוא מלך הח' הדר הוא שרש ומקור שממנו יומשך כח בחי' התיקון לתקן לז\"מ דתוהו כידוע וד\"ל. וזהו שראה יוסף השמש וירח (שהן בחי' זו\"נ מ\"ה וב\"ן דאצי') וי\"א כוכבים שנק' כוכבי אור דאצי' טרם באו לבי\"ע משתחוים לו שהוא למקור החכ' דתיקון כמו שהוא בעצמות א\"ס כנ\"ל וד\"ל. (וחלום הא' דמאלמים אלומים היה באופן העלאת הבירורים דרפ\"ח ע\"י שם ב\"ן דשבטים מבי\"ע בשית אלפי שני עד העוה\"ב ולכך לא ראה אביו יעקב שכבר הוא בבחי' התיקון דשם מ\"ה דאצי' שגם זה הבירור בהעלאת מ\"ן צ\"ל בבחי' השתחוואה לאלומות יוסף שהיה פותר חלומות דבחי' ב\"ן דק\"נ בהיותו בשרש התיקון ע\"כ היה מברר ומעלה לאלומות שלהם וז\"ש ותשתחוינה לאלומתי כו' אבל חלום הב' בשמש וירח כו' זה היה בבחי' ההמשכה דשם מ\"ה דתיקון דאצי' לברר לב\"ן דנוגה וגם זה הי' משתחוים לו לקבל ממנו כח ועוז לברר וזהו בכל דור ודור שצ\"ע בחי' יוסף נותן כח ועוז לתיקון דתו\"מ כו' וד\"ל). ובזה יובן מה שארז\"ל ע\"פ וישתחו ישראל על ראש המטה שחלק כבוד למלכות כו' (וגם כששמע שיוסף בנו בא אצלו נתחזק וישב על המטה שהיתה שלימה כו' לקבל מיוסף כו') פי' שחלק כבוד למלך הח' מלך הדר כו' שהוא בבחי' יוסף ממש שהי' גבוה מיעקב הרבה להיותו שרש ומקור לבחי' התיקון דשם מ\"ה דישראל ויעקב דאצי' כנ\"ל. וזהו וישתחו ישראל העליון בביטול והתכללות כו' (על ראש המטה שהיה שכינה מראשותיו ונכלל גם בחי' המל' בהשתחוואה זו). וראי' לזה ממ\"ש אלה תולדות יעקב יוסף. ולכאורה עיקר תולדות יעקב היה השבטים אלא זהו מצד השרש של הכח ועוז לתולדות יעקב בע' נפש שלו בי\"ב שבטים בדור אחר דור עד ימוה\"מ והעוה\"ב הכל ע\"י יוסף שהוא שרש ומקור הראשון לבחי' התיקון שלזה נק' בן פורת שמפליא להרבות ולהפרות בריבוי התחלקות דתיקון מפני שהיה פותר ותופר בתיקון דתוהו דהכל א' דפורת ותופר ופותר (ופרת ותפר ופתר בלא וא\"ו הוא בחי' נהר פרת הוא דמעיקרא כו'):\n(ט) <b>ובכ\"ז</b> יובן ג\"כ מ\"ש ויאסור יוסף מרכבתו כו' וירא אליו ויפול על צואריו ויבך על צואריו עוד. ויש בזה ב' פירושים א' שמ\"ש וירא אליו היינו שיעקב נתראה ונתגלה ליוסף והפי' הב' דיוסף הוא שנתראה ונתגלה אל יעקב וכך משמע פשט הענין דקאי אדסמיך ליה ויאסור"],[2300680246,"יוסף כו' ויעל כו' וירא אליו שיוסף הוא שנתגלה אל יעקב וא\"כ גם מה שאמר ויפול על צואריו קאי על יוסף דקאי אדסמיך ליה וירא אליו כו' דיוסף הוא שנתראה אל יעקב ויפול על צואר יעקב ויבך עליו כו' כי שרש יוסף היה במדריגה גבוה מאד נעלה הרבה מיעקב כנ\"ל שהיה במקור דבחי' התיקון דיעקב ע\"כ אמר שיוסף השפיל את עצמו ממקומו העליון להיות מתגלה ליעקב וז\"ש וירא אליו כו' ויפול על צואריו כו' להמשיך ליעקב ממקור הרחמים הרבים העליונים שבבחי' מקיף הכללי הנ\"ל שיבא בגילוי במדת ת\"ת דיעקב שיהיה נק' נחלה בלי מצרים כלל כו' וד\"ל ומ\"ש ויאסור יוסף מרכבתו לקראת ישראל אביו כו' שמובן מזה שהיה יוסף עולה לקבל פני אביו כתלמיד לרבו כו' הענין הוא מצד ירידה והתלבשות יוסף בק\"נ דמצרים להיות מלך על גוים (כמו הקב\"ה בגלות שנק' מלך הגוים כו') היה צריך לעלות במרכבתו לקראת ישראל אביו שהוא בבחי' התיקון דאצי' אבל בחי' מרכבה דיוסף היה למעלה ממדריגה דיעקב ע\"כ אסר מרכבתו להעלות כו' לקראת ישראל כדי שיוכל להיות כח ועוז בישראל לתקן לעה\"ד טו\"ר ע\"י תו\"מ שישראל עושים בגלות וכמ\"ש ויקם עדות ביעקב ותורה שם בישראל וד\"ל. וזהו שאמר יוסף לאחיו אל תעצבו כו' כי למחיה שלחני אלקים לפניכם כי זה שנתים כו' וישלחני אלקים לפניכם לשום לכם שארית בארץ ולהחיות לכם לפליטה גדולה כו' וגם אחרי מות יעקב אמר להם אל תיראו כי התחת אלקים אני כו' אלקים חשבה לטובה למען עשה כיום הזה להחיות עם רב דהנה התורה נצחית היא בכל דור ובכל זמן כידוע והענין הוא כידוע שבנ\"י בכל דור ודור נשלח להם בגלות בחי' יוסף צ\"ע שז\"ש למחיה שלחני אלקים כו' עד לפליטה גדולה להיות שמבואר למעלה בשרש יוסף שהוא במקור של בחי' התיקון דתורה ומצות ובכל דור שישראל עושים תורה ומצות שזהו בבחי' הבירור דק\"נ לא היה ביכולתם כלל לעשות בחי' יחו\"ע ע\"י המצות באהוי\"ר שלהם אם לא ע\"י בחי' יוסף שנשלח בגלות לעוזרם כו'. ולהבין ביאור הענין הנה יש להקדים תחלה שאי אפשר להיות יחו\"ע במצות אם לא ביחוד דב' שמות הוי' ואלקים שזהו בחי' סובב וממלא כידוע והן ע\"י ב' מיני אהבות אה\"ר ואה\"ע ששניהם נולדים מן ההשגה והתבוננות בגדולת ה' ביחו\"ע ויחו\"ת שההשגה ביחו\"ת בבשכמל\"ו שהוא בבחי' ממכ\"ע בביטול היש לאין והוא בבחי' אלקים כח הפועל האלקי' בנבראים מזה נולד האהבה שנק' אה\"ע שמתיישב האור בכלי המוח והלב כידוע ומבחי' יחו\"ע בהתבוננות דבחי' סוכ\"ע בכלל בשמע ישראל כו' נולד בלב בחי' אה\"ר שהיא למעלה מן הכלי כו' ואמנם בחבור ב' האהבות הללו ביחו\"ע ויחו\"ת (שזהו בכל נפשך ובכל מאדך) נתחבר ונתייחד ב' שמות דהוי' ואלקים יחד ומזה נעשה יחו\"ע שבמצות שהוא יחוד קוב\"ה ושכינתי' סובב וממלא כו' כידוע וד\"ל. והנה בזמן הגלות מחמת עוצם הסתר אלקות בנש\"י מצד הלחץ ודחק בטרדות הפרנסה וכובד שיעבוד הגלות וכה\"ג (לפי שהשכינה בגלות באוה\"ע) יכול להיות"],[2300680258,"שלפרקים בעת מן העתים לא יאיר אור הוי' בכנ\"י ביחוד דהוי' ואלקי' גם במצות שעושין מצד שלא יאיר בהם אור התפעלות ב' אהבות דאה\"ע ואה\"ר הנ\"ל לפי שנגרע כח ההשגה וההתבוננות ביחו\"ע ויחו\"ת כנ\"ל עד אשר אין בכח השגתם כלל להוליד ב' אהבות הנ\"ל ולהיות כן במשך זמן רב בגלות זה האחרון היה ח\"ו נפילה גמורה בכנ\"י בבחי' פירוד וריחוק גמור מאלקות במיעוט האור מיעוט אחר מיעוט עד שהיה נשכח מנפשם ולבם לגמרי כח השגות אלקות ביחו\"ע ויחו\"ת עד שלא היה נמצא בהם אפי' רושם בעלמא מב' אהבות הנ\"ל גם לפרקים כמו בשבת ומועדים מפני כלות כוחם בעצם ח\"ו אך בחמלת ה' עליהם ומצד התקשרות אה\"ר ואה\"ע שמלמעלה למטה כמ\"ש אהבת עולם אהבתנו כו' שלח לפניכם בחי' יוסף צ\"ע להיות לנש\"י הנמצאים בכל דור בגופי' למחיה ממש וז\"ש יוסף כי למחיה שלחני אלקים לפניכ' כו' לשום לכם שארית בארץ דהיינו שבחי' אור הזרוע לצ\"ע בנש\"י בכל דור הוא למחיה ושארית פליטה בכל משך זמן הגלות כו' שלא ישכח מלבם ונפשם ולא יכלה כחם בעוז ב' אהבות הנ\"ל ובהשגות אלקות כיחוד\"ע ויחו\"ת כו' והיינו ע\"י בחי' אור אה\"ר המסותרת שיסודתה בהררי קדש העליון בבחי' פנימי' ועצמות המאציל באה\"ר העצמות שמלמעלה למטה ומשם נמשך כח בכל ניצוץ מישראל שיהיה בו בחי' אה\"ר עצמית וטבעית שמוטבע ומושרש כמו טבע ממש בנקודת הרצון שלמעלה מן הטעם ודעת ולמעלה מן הלב להיות נכספה וגם כלתה נפשו לידבק בה' אחד ולא יזוז מהתקשרות זאת האמיתית בשום נסיון בעולם כידוע וזאת האה\"ר נק' אהבה המסותרת בהעלם ובכח כל אחד ואחד מישראל והיא הבאה מלמעלה מאליה בלי הכנת אדם לפרקים שנתגלה מבחי' העלם בלתי שום הכנת הכלי כו' להיותה למעלה מן הדעת וההשגה דכנ\"י ואמנם מסותרת היא בלב דכנ\"י וא\"צ רק להוציאה מן ההעלם לגלוי וגם זה בא מכח עליון דבחי' צ\"ע (שזהו בחי' רוחא דשביק בגווה כו') וע\"כ אין לכח אה\"ר זאת קץ וגבול ושיעור כלל דהיינו גם במשך זמן רב דגלות בטרדות המבלבלים לנקודת הלב והמוח עכ\"ז לא יחשיך אורה כלל וכמ\"ש מים רבים לא כו' רק שהיא מסותרת מאד ואמנם מיד שתצא מן ההעלם לגילוי יש בכחה הגדול לעורר את האהבה בב' מדריגות דיחו\"ע ויחו\"ת באה\"ע ואה\"ר שיאירו בתוקף גדול שלא יפול הנופל לעולם וד\"ל. וזהו כי למחיה שלחני כו' שנשלח ממקור התיקון ליתן כח ועוז בהמשכות אור אהבה מסותרת בלב כנ\"י שתבא מן ההעלם לגילוי וזאת היא עיקר סיבת קיומם וחיותם באור החיים בכל עת מצוא לבא להתפעלות ב' אהבות הנ\"ל בהמשך זמן רב בגלות ואם לא לזאת האהבה מסותרת שבאה מלמעלה מבחי' יוסף צ\"ע היה כבר כלה כחם האלקי' במעט זמן כו' וד\"ל. וזהו לשום לכם שארית בארץ העליונה שיהיה להם שארית בארץ החיים מבחי' מל' דאצי' וגם להחיות להם לפליטה גדולה בימות המשיח שאז אמר הגדיל ה' לעשות עם אלה וד\"ל (וכ\"ז מפני שנק' בן פורת פותר ותופר כו'"],[2300680270,"דגם בגלות השכינה באוה\"ע שנק' שינה שחולם חלומות בבחי' לבושים זרים דק\"נ שנפל מבחי' התוהו יכול להעלותם ולהביאם בבחי' התיקון כנ\"ל וע\"כ יש בכח המשכת צ\"ע באור הזרוע בנש\"י לעורר בהם כח האהבה מסותרת שתצא מן ההעלם שבזה יהיה כח להיות יחוד דמ\"ה וב\"ן במצות שהן ב' שמות דהוי' ואלקים שהוא בחי' התיקון וד\"ל) וזהו לשום לכם שארית בארץ דמ\"ה יברר לב\"ן ויהיה יחוד עליון בכל עת מצוא וגם לקבל שכר המצות בעוה\"ב שזהו שנק' בן פורת (שמפרה ומרבה האורות בכלים לאין שיעור כו') (ומ\"ש לפליטה גדולה קאי בימות המשיח (כמשי\"ת) דכתי' אז אהפוך אל עמים כו' דכמו שהיה יוסף שליט על כל הארץ ומשביר בר לכל עם הארץ בגשמיות כך לע\"ל ברוחניות החיות האלקי' להחיות עם רב אוה\"ע ויהיה נק' מלך הגוים כו'. ואמנם ישראל יהיה במעלה מרובה עד שיאמרו בגוים הגדיל ה' לעשות עם אלה והוא מה שע\"י אור הזרוע לצ\"ע כל משך זמן הגלות זריעה זאת היא בכח האהבה מסותרת להוליד יחו\"ע כנ\"ל הרי עשה פרי מרובה להצמיח בכפלי כפלים לאין שיעור מעצם אור הזרוע לצ\"ע בנש\"י בכל דור כמ\"ש וזרעתיה כו' וכמו שאדם זורע קב כדי להוציא כמה כורים דוקא וכמו הלוך ילך כו', בא יבא ברנה נושא אלומותיו כו' ונק' ראשית תבואתו כו' וז\"ש להחיות לכם דוקא לפליטה גדולה דוקא וגם להחיות עם רב ניצוצות דבחי' התוהו שבכל אוה\"ע שיבוררו לעבדו שכם אחד כו' וד\"ל):\n(י) <b>ובכ\"ז</b> יובן מ\"ש אסף על זמן הגלות רועה ישראל האזינה נוהג כצאן יוסף פי' רועה ישראל הוא בחי' מל' שנק' שכינה דבגלות שכינה עמהם והוא שנק' רועה כמו ברחל שאמר כי רועה היא שזן ומפרנס לישראל באהוי\"ר ואמונה פשוטה כו' ואמנם אין עיקר חיותם וקיומם בבחי' שרש ועצמית שיקוים כחם ולא יכלה הוא מ\"ש נוהג כצאן יוסף דוקא שהוא המשפיע ומעורר בנש\"י בחי' האהבה מסותרת הנ\"ל שהיא באה מלמעלה מאליה והוא מבחי' יוסף העליון דוקא שהוא בחי' אור הזרוע לצ\"ע בנש\"י בכל דור כנ\"ל וע\"כ אמר נוהג כצאן יוסף דוקא שממנו עיקר ושרש לפרנסת ישראל מרועה ישראל וכמ\"ש ביוסף מידי אביר יעקב משם רועה אבן ישראל שהוא היות יחוד דמ\"ה וב\"ן שנק' אבן ישראל כו' וד\"ל (וזהו שחלם יוסף השמש והירח משתחוים לו כו' שהן ב' מדריגות דהוי' ואלקים שמתייחדים בב' אהבות הנ\"ל אה\"ר ואה\"ע שהן משתחוים לקבל מבחי' יוסף שימשיך בהם כח ועוז ליחודם בתמידות כנ\"ל וכידוע בזוהר דשמשא וסיהרא היינו הוי' ואלקים שהן זו\"נ דאצי' ושרש יוסף בבחי' מלך הח' הדר שרש ומקור לבחי' התיקון כנ\"ל או פי' משתחוים לי בבחי' השתחואה מלמעלה למטה ליתן כח ועוז ליוסף צ\"ע בחי' יסוד שיעורר בנש\"י לאהבה מסותרת הנ\"ל שזהו גילוי דמדריגת יוסף להשפיע במל') וז\"ש ואביו שמר את הדבר שמר להבא שיהיה כך לע\"ל שיתגלה מדריגת יוסף שנאמר ולא יהיה לך עוד השמש לאור יומם וירח כו' רק ה' יהיה לך לאור עולם (והוא אור הגנוז לצדיקים) לע\"ל"],[2300680282,"שהן מטמוני יוסף שיתגלה לע\"ל (כמשי\"ת). ואמנם כ\"ז הנה דוקא בזמן הגלות בחי' יוסף גבוה מאד נעלה במדריגה ליתן כח ועוז למל' לשום לבנ\"י שארית בארץ מטעם הנ\"ל להיותו בבחי' מקור לתיקון כו' אבל בימות המשיח דכתיב ביה ישכיל עבדי כו' וגבה מאד בפנימי' ועצמות אא\"ס שבפנימית הכתר בכלל שזהו בחי' עליות המל' דיהודה למעלה מבחי' יוסף המשפיע כו' וכמ\"ש בהפטורה דפ' ויגש לקח עץ כו' עד ודוד עבדי נשיא להם לעולם שהוא כתר ש\"ט דמשיח שלמעלה יהיה מעץ אפרים דיוסף צ\"ע רק בזמן הגלות בחי' המל' מקבל ובטל ונכלל בבחי' יוסף צ\"ע כמ\"ש ויגש אליו יהודה כו' כידוע (בפ' ויגש באריכות). וטעם הדבר ידוע לפי שעכשיו בחי' שם מ\"ה דתיקון שהוא בבחי' יוסף מברר לבחי' ב\"ן דתוהו שנפל בשבה\"כ כענין החלומות דבזמן הגלות שנק' פותר ותופר כו' כנ\"ל וז\"ש כי למחיה שלחני אלקים לשום לכם שארית בארץ כנ\"ל אבל כאשר כבר יתברר בחי' ב\"ן ויעלה לשרשו בבחי' ס\"ג דבינה שלמעלה משם מ\"ה המברר כו' וכמ\"ש א\"ח עט\"ב כו' אז אין צריך המל' לבחי' יוסף כלל אדרבה יעלה למעלה הימנו כמ\"ש וגבה מאד (והוא למעלה גם ממח' הכללי' ופרטי' הנ\"ל והוא בחי' מל' דא\"ס עצמו כמו שהוא טרם שבא להיות נק' משפיע בכלל ופרט כו') ואע\"פ שיוסף הי' שליט על הארץ מלך על כל הגוים ומשביר בר לכל עם הארץ בסוד גלות בלבוש שק כו' וכך יהיה לע\"ל ברוחני' דכתיב מי לא ייראך מלך הגוים כו' זהו רק מבחי' מלך הח' הדר שמברר לז\"מ דתוהו שהן ע' אוה\"ע כמ\"ש אז אהפוך אל עמים כו' אבל משיח יהיה מלך על ישראל דוקא ולא מלך הגוים משום דשרש ישראל הוא מבחי' מל' דא\"ס עצמו שלמעלה גם משם מ\"ה החדש דא\"ק כו' (וז\"ש במשיח חיים נתתי לו חיים נצחיים דא\"ס דכתי' ביה ה' ימלוך לעולם ועד והוא ענין דוד מלך ישראל חי וקיים אבל משיח בן יוסף אין נצחי כו') וז\"ש תחלה לשום לכם שארית בארץ שזהו רק עכשיו בזמן הגלות דמ\"ה דתיקון מברר לב\"ן מכח יוסף מקור התיקון כנ\"ל ולכך אמר למחיה כו' לשום לכם שארית כו' ומ\"ש עוד ולהחיות לכם לפליטה גדולה היינו שמזה יגדל אור המל' דמשיח שיהיה אז למעלה מיוסף הרבה כנ\"ל ואז אין צריך למחיה דיוסף כלל ואמנם ע\"י זריעה דאור זרוע לצ\"ע בכל משך זמן הגלות יהיה זה הריבוי שנק' פליטה גדולה שיהיה בימות המשיח בישראל דוקא והוא שנק' בן פורת כו' ולכך אמר ולהחיות לכם דוקא כו' שגם זה מכחו בא אע\"פ שיהי' משיח בן דוד למעלה ממנו וז\"ש למען עשה כיום הזה להחיות עם רב לע\"ל שיבוררו כל בחי' הניצוצים דז\"מ דתוהו כנ\"ל כמ\"ש אז אהפוך כו' והכל מבחי' יוסף שליקט כל הכסף בזמן הגלות דוקא (כמשי\"ת) וז\"ש כי למחיה כו' היינו עד שיהיה בחי' עליות המל' דמשיח למחיה שלחני בכל משך זמן הגלות כו' מטעם הנ\"ל:\n(יא) <b>ובכ\"ז</b> יובן מ\"ש בזוהר על יוסף צ\"ע שנק' גננא דגינתא כו' והאי גינתא מגרמיה אזדרע כו'. ולכאורה אין זה מובן דאם האי גינתא מגרמיה אזדרע למה צריך"],[2300680294,"לגננא כלל. אך הנה ידוע דגינתא הוא בחי' המל' שרש נש\"י (שנק' שדה חקל תפוחין קדישין כו') כמו ג\"ע שנטע ה' שיצמיח כל עץ נחמד ועשבים טובים ביותר שהן כל בחי' גילוי אור האלקי בנש\"י בכמה מיני מדריגות שונות בבחי' כלים מכלים שונים (כמ\"ש גן נעול אחותי כלה כו') ובג\"ן סדרים דאורייתא והוא בבחי' התיקון בריבוי האורות בכלים רבים ברמ\"ח מ\"ע כו' ולמטה נק' כנ\"י כרם ה' צבאות כידוע וד\"ל. ובחי' אור הזרוע בגינתא הוא הנק' גננא כמו הגננא שהוא היודע בטוב איך לסדר סדר ותיקון טוב בזריעת הזרעים בגן במקומות מיוחדים שבו שמתקן שם שיקבל צמיחות טובות ממיני זרעים הרבה הטובים שהביא לשם ממקום טוב שכבר צמחו שם עד שבמשך זמן רב יהיה הגן בעצמו תוציא צמחה בכל מיני צמחים הטובות להיותה מסוגלת לצמיחה זאת ואמנם זה נעשה בה ע\"י התיקון דגננא כו' וד\"ל. וכך יובן למעלה בבחי' יוסף צ\"ע שנק' גננא אור בגנתא שהוא בחי' המל' היינו מה שמתקן ונותן כח ועוז בכנ\"י שתוכל להצמיח כל פרי טוב באהוי\"ר ובמצות מעשיות והיינו כמו תולדות ב' אהבות הנ\"ל דאה\"ר ואה\"ע שעושים יחו\"ע בב' שמות דהוי' ואלקים בכל המצות שעושים בריבוי האורות בכלים כנ\"ל לפי שמבחי' מקור התיקון דשם מ\"ה החדש דיוסף שהוא מלך הדר כו' הוא שנעשה ונמשך כח הטוב בגינתא שתקבל כל זריעה טובה מאורות העליונים ביותר עד שאח\"כ תצמיח מעצמה בלי זריעה כלל כי כארץ תוציא כו' וכגנה זרועיה תצמיח מעצמה כן יצמיח ה' צדקה כו' שהן אורות העליונים שבתו\"מ כו' (והוא ג\"ע העליון והתחתון כמ\"ש היושבת בגנים כו' כמ\"ש במ\"א). אך הנה יש עוד צמיחה בגנתא כמו בשדה שהן כמו ספיחים שגדלים מאליהן בלי זריעה כלל כך יש עשבים טובים ואילנות שצומחים בכרם בלי סיבה נטיעה וזריעה כלל וזהו בא מכח הגינה עצמו משא\"כ בזרוע שצומח מן הזריעה שאין זה מכח הגינה עצמה רק מכח הצומח שיש כבר בזריעה שטבעו להצמיח ואין זה צמיח' הארץ מכח עצמ' כמו שהיא בעצם הראשון כו' רק שמעורר גם לכח הצומח שבארץ להצמיח בזרוע יותר כמו שהוא בכפלי כפלים (שבזה יתרון מעלה לזריעה על הספיחים כמשי\"ת). וזהו ג\"כ למעלה בחי' אור זרוע דצ\"ע בנש\"י שהצמיחה באה מכח אור הזרוע שמצמיח ואין זה מכח עצמיות דכנ\"י שנק' גן ה' אבל מה שתצמיח בכח עצמה בלי זריעה דצ\"ע יותר עליון ממנו (והוא טעם עליית מל' דמשיח שיהיה לע\"ל למע' מבחי' יוסף כנ\"ל דכתיב ביה וגבה מאד והוא מ\"ש דהאי גינתא מגרמיה איזדרע בלי זריעה כלל וכמ\"ש וכגנה זרועיה כו'). וביאור הענין הנה מבואר למעלה בבחי' כח התעוררות דאהבה מסותרת בכנ\"י שיולד מזה ממילא תולדות ב' אהבות הנ\"ל שזהו בא מאור הזרוע לצ\"ע בארץ וז\"ש למחיה שלחני אלקים כו' כנ\"ל וזהו גננא דגנתא שמתקן לגינה שתתן את כחה להצמיח כל מיני צמיחות טובות והוא ע\"י הזריעה דזורע (וכמו שאמר יוסף הא לכם זרע וזרעתם את האדמה ה\"א דיסוד כו') אבל כמו ענין גידול הספיחים או העשבים ואילנות שגדלים מכח הגינה עצמה היינו מה שיש בנש\"י"],[2300680305,"להתעורר באה\"ר העצמיי' או בתשובה שלימה בלי התעוררות מלמעלה כלל וכלל כו' רק מכח עצמם דוקא וזהו דמגרמיה אזדרע כו' בבחי' העלאת מ\"ן שמכח עצמה וכמ\"ש וכגנה זרועיה תצמיח מאליה (והוא הנק' טוב מאד דגנוז בגווה כמ\"ש בזוהר ומבואר במ\"א). ואמנם הנה הגם שמעלת הספיחים גדולה מצד שבא מכח העצם כנ\"ל מ\"מ יש מעלה יתירה בזריעה הצומחת יותר מטעם אחר להיותה באה בריבוי גדול בכפלי כפליים לאין שיעור שהולך וצומח בלי הפסק כלל כמו ויזרע יצחק כו' מאה שערים שזהו בחי' התחדשות גמורה כמו בצמיחת התבואה בחידוש גמור שניתוספו בכפלי כפלים מכמו שהיה בזריעה כמו מקב א' כמה כורים וכך הוא ענין תולדות וצמיחת דב' אהבות הנ\"ל שבאו בחידוש גמור מן ההשגה וההתבוננות שעושים פרי במצות ע\"י כח דאור זרוע לצ\"ע בהתעוררות כו' זהו אין לו שיעור כלל ונוסף על הזריעה בכפלי כפליים כו' אבל בחי' התעוררות אהבה מסותרת שבאה מכח העצם שזהו כצמיחת הספיחים אין בזה חידוש גמור רק במה שבאה כח האהבה מסותרת לגילוי לבד שהרי זהו בחי' עצמיות וטבעית בנה\"א כו' ולא בא רק לידי גילוי מן ההעלם לבד (ויש בזה שיעור ומדה כפי אופן כח הצמיחה שבארץ שתוציא צמחה ע\"פ מאמר תדשא הארץ דשא כו' וד\"ל). (אך באמת אין הענין כן דנהפוך הוא דבזריעה גם שניתוסף הרבה גם זה בא מכח הצומח שבארץ שיש בכחו לחדש מאין ליש שנק' חידוש גמור והוא בא מחמת ביטול היש לאין דחטה הזרוע בארץ וזהו נק' יש מיש עכ\"פ אבל מה שנצמח מעצם הצומח שבארץ בלי זריעה כלל זהו נק' חידוש יש מאין ממש והוא צמיחה בלי שיעור כלל שגם שקוצר כמה אלפים פעמים חוזר וצומח כו'. וזהו שלע\"ל אמר אור חדש על ציון תאיר שהוא כח האהבה מסותרת שבעצמות שנק' אור חדש ממש משא\"כ עכשיו בזמן הגלות הוא ע\"י התעוררות רוח ממרום דיוסף צ\"ע שלמחיה כו' שנק' גננא דגנתא דאע\"פ שמוליד ריבוי תולדות בברכה מרובה ביותר יש לו שיעור והפסק משא\"כ ברכת הארץ מכח עצמה שאין לה שיעור כלל וזהו ששם ב\"ן יעלה למעלה משם מ\"ה דמשפיע והוא מל' דמשיח שיעלה למעלה מיוסף דהיינו מ\"ש ולהחיות לכם לפליטה גדולה שבימות המשיח לא יצטרכו למחיה דיוסף כלל כנ\"ל וד\"ל):\n(יב) <b>ובכ\"ז</b> יובן מ\"ש וילקט יוסף את כל הכסף כו' דהנה אמרו רז\"ל ג' מטמונים הטמין יוסף א' נתגלה לקרח כו' והג' יתגלה לע\"ל כו'. והענין יובן עד\"מ אדם שרוצה לילך בדרך רחוקה מאד מהלך כמה שנים בים ויבשה דודאי הרי לפי שיעור הדרך שיתעכב זמן רב כ\"כ צריך האיש להכין צידה לדרך רחוקה כזו הרבה מאד שיספיק לכל הזמן שיתעכב בדרך הזה. והנה עיקר הספקת האדם וביתו הוא במזון דלחם ולבוש דכסות אבל שארי הצטרכות במזון כבשר ודגים ויין ושמן וכה\"ג א\"א שיכין הכל כפי הצריך לזמן רב כזה ובמה ישאם שתהיה הוצאה יתירה על השבח כו' וכן בלבוש דכסות וגם במזון דלחם לא יוכלו להכין רק לחודש ימים ולא יותר שיופסד המזון והכסות יבלה בשנה א' כו'. הנה לזאת עיקר"],[2300680316,"הצידה לדרך הוא צרור הכסף שירבה לרוב בידו ויטמינה בסתר למען יוכל לקנות בכסף כל אשר יצטרך לו בדרך גם כשיכלה הלחם ויבלה הכסות יקנה מחדש הכל בכסף כל אשר יחסר לו במזון ולבוש ויתקיים בכסף רב כל משך רב הזמן שהולך בדרך כו'. והנמשל מכ\"ז יובן למעלה בהיות מבואר למעלה בשרש יוסף צ\"ע שהוא בחי' מלך הח' הדר כו' שממנו מקור מוצא לבחי' התיקון באו\"כ בתו\"מ ואהוי\"ר בכנ\"י בכל הימים וזהו שליקט יוסף כל הכסף שהן כל בחי' החסדים הטובים והרבים מאד שיאירו מעצמות המאציל ממש (כמו שאומר וגומל חסדים טובים וקונה הכל כו') כדי שיהיה הכל בהכין מזה להיות צידה לדרך רב מאד דהיינו שיהיה הכנה רוב כסף העליון הזה לבחי' התיקון שאח\"כ בכנ\"י שהוא כמשל הנסיעה בדרך רחוקה כו' והן כל משך זמן רב דגלות בד' גליות שהן צריכין למזון ולמחיה לנשמתם האלקי' בתו\"מ ואהוי\"ר באה\"ע ואה\"ר הנ\"ל שכבר הי' כלה כחם לגמרי באריכות הגלות כזה כנ\"ל וכידוע שהתורה נק' מזון לחם לאכול ומצות נק' בגד ללבוש כו' (וכמ\"ש יעקב אם יהיה אלקים עמדי ושמרני בדרך הזה (בד' גליות) ונתן לי לחם לאכול כו'). אך בחי' צ\"ע הוא שהכין צידה לדרך רב כזה והוא בחי' החסדים העליונים דשם מ\"ה החדש דיוסף שליקט בכל משך הגלות מעצמות המאציל שלמעלה מעלה מכל ההשתלשלות דתוהו ותיקון ומורידם עד למטה ממש שמזה יהיה כל שפע המזון דלחם דתורה ולבוש דמצות ואוי\"ר בכנ\"י בכל משך אריכות הגלות כו' שיקנה בכסף זה והוא מה שיתן התחדשות כח בעצם בכנ\"י בהתעוררות אהבה מסותרת כנ\"ל ע\"י המשכות חסדים העליונים העצמיי' כו' וד\"ל. וזהו וילקט יוסף את כל הכסף כו' מחסדים העליונים שבהם עושה צידה לדרך לכנ\"י שבגלות כנ\"ל והכסף הוא שליקט מן הבירורים דק\"נ כמ\"ש בשבר אשר הם שוברים (כידוע דז' שני השבע הוא בחי' שמיטה של חסד ויוסף הוא בחי' יסוד דשמיטה זו כו' והיה מקבץ כל אוכל בז' שנים הטובות שיצבור בר כחול הים כו' ובשמיטה דגבורה שהן ז' שני הרעב ליקט כל הכסף כו') וזהו ויביאם ביתה פרעה בחי' המל' פריעה והתגלות דכל נהורין שנקרא עלמא דאתגליא והוא בחי' שם ב\"ן דקדושה שמלובש בגלות בבחי' ב\"ן דנוגה כדי להיות כח לכנ\"י שהן בגלות ושכינה עמהם בכל משך זמן רב הזה לפרנס את עצמם במחיה ומזון דתורה ומצות ולא יכלה כחם ח\"ו כנ\"ל וזהו שאמר כי למחיה שלחני אלקים לפניכם דוקא ולהחיות לכם דוקא זמן רב עד ימות המשיח וד\"ל. וזהו שאמרז\"ל ג' מטמונות הטמין יוסף פי' מטמון כמו אם כמטמונים תחפשינה היינו כאוצר מלא כסף שנטמן בעומק הארץ והוא בחי' כח החסדים העליונים הנ\"ל שהן בעומק גדול בנש\"י טמונים ונעלמים ובאים לידי גילוי לפרקים שזהו כמוצא המטמון שיחיה בו זמן רב לכל אשר יצטרך לפיקוח נפשו ונפשות ביתו כו' וד\"ל. ומה שאמר ג' מטמונים הענין הוא כידוע שיש בבחי' החסד ג' פרקין חב\"ד חג\"ת נה\"י וב' שלישים התחתונים שהן בחי' חג\"ת ונה\"י ירדו ונתגלו למטה בכנ\"י בכל משך זמן דד' גליות עד ימות"],[2300680327,"המשיח. והענין הוא דגם שנק' מטמון כאוצר הנעלם ונק' אוצרות חיים העליונים להחיות הנשמות כו' כנ\"ל מ\"מ מתגלין מן ההעלם והוא להיות מאהבה רבה העליונה כח ועוז לנש\"י להתעוררות באהוי\"ר באה\"ר ואה\"ע כנ\"ל שזהו בחי' המדות דחג\"ת (כמו בג' רגלים שמאיר בכנ\"י מבחי' חג\"ת דז\"א מחמת חסדים העליונים שנמשך בכל אחד ואחד כו' וכן בג' תפלות בכל יום) וכמ\"כ השליש האחרון בחי' נה\"י דחסד שהוא לחזק כח המעשה דצדקה וכל המצות מעשיות בפו\"מ שיש כח ועוז בכנ\"י כל משך זמן הגלות בתוקף עוז גדול כמו שנראה לעין תוקף כח המעשה דמצות באמונה פשוטה בלי שינוי כלל כו' וד\"ל. ואמנם בחי' פרק העליון דחסד שהוא בבחי' חב\"ד דכנ\"י לא נתגלה למטה עדיין ונשאר בהעלם ויתגלה לע\"ל והיינו מה שבימות המשיח יתגלו טעמי מצות וסודות ורזי' דאורייתא בריבוי אור החכמה עילאה שיאיר בכל נש\"י מגדול עד קטן כמ\"ש ומלאה הארץ כו' והיינו בזמן עליות המל' לע\"ל שיהיה כנ\"י לפליטה גדולה כנ\"ל אז יתגלה בהם מטמון דיוסף הג' שהוא בפרק העליון דחסד שבא מעצמות המאציל שנק' הון יקר ונעים כמו אם יתן איש כל הון ביתו שהן פנימיות וסודות התורה שנק' אוצרות סתומים ונעלמים שלא הוציא מהן לצידה לדרך בגלות כלל כמ\"ש למחיה שלחני כו' וזהו ע\"י ב' שלישים התחתונים דחג\"ת ונה\"י באהוי\"ר ותו\"מ לבד אבל מטמון הג' דפרק העליון דחסד לא נתגלה בגלות להיות למחיה אלא נשאר לע\"ל והוא שאמר ולהחיות לכם לפליטה גדולה לע\"ל דוקא וזהו אור הגנוז לצדיקים לע\"ל כידוע וד\"ל:\n(יג) <b>ובכל</b> הנ\"ל בענין שרש יוסף למעלה יובן ג\"כ מה שאמרז\"ל שנענש יוסף על שאמר לשר המשקים כי אם זכרתני כאשר ייטב לך כו' והזכרתני אל פרעה והוצאתני כו' שבטח באדם ולא בטח בה' שמתיר אסורים כו' דלכאורה זהו פלא למה נענש ע\"ז הלא אין סומכין על הנס וכי טוב הי' יוסף מיעקב אבינו ומצינו ביעקב לגבי עשו שירא מאד שמא יגרום החטא דכתיב ויירא יעקב מאד ויצר לו כו' ולא סמך על הנס ועשה תחבולות להכניע את עצמו ביותר לפני עשו ושלח לו מנחה גדולה לכפר פניו בהכנעה גדולה וקראו אדוני כמה פעמים ואיך לא תלה בטחונו בה' אלא מפני שהיה ירא שמא יגרום החטא כו' וא\"כ למה נענש יוסף על זה כו'. אך הענין הוא לפי שיש הפרש גדול במעלה ומדריגה בין יוסף ליעקב לפי הנ\"ל דהנה מבואר למעלה בשרש בחי' יעקב ויוסף דיעקב שרשו למעלה בבחי' התיקון דהיינו שכבר הוא נעשה בבחי' התיקון באורות וכלים שהאורות מצומצמים כבר בכלים מכלים שונים בדקדוק ושיעור ע\"פ מאמר קו המדה בג' מדריגות פנימי ואמצעי וחיצון ואז יש מקום ושרש גם ליניקות החיצוני' דבחי' ק\"נ מחיצונית דחיצונית הכלים שהאור שם בתכלית ההסתר עד שיכול להיות תוס' יניקה להם מחיצונית הכלים דקדושה (ואע\"פ שיעקב היה שלם בשלימות דבחי' התיקון לא כאברהם שיצא ממנו ישמעאל כו' והוא בקו האמצעי דבחי' ת\"ת בשם הוי' ששם לא נמשך לחיצונים אפי' מחיצונית דחיצונית הכלים כמ\"ש ה' אלקיו עמו"],[2300680337,"כמ\"ש במ\"א וכמ\"ש וכבודי לאחר לא אתן כו' (ולכך אמרו דיעקב לא מת כו') עכ\"ז היה ירא שמא יגרום החטא מאחר שבבחי' התיקון הוא נמשך בדקדוק ומשפט התורה בבחינת הדין ביותר כו' וכמ\"ש וסביביו כו' שמדקדק כחוט השערה כו' ועיקר פחדו היה מד' מאות איש דעשו שנפלו מבחי' גבורות עליונים דמקיפים דתוהו ולא נתבררו עדיין שלא יגברו כחם על בחי' או\"פ דתיקון) ומפני שהכל במדה קצובה שכבר קצוב ועומד הרי לפעמים יוכל להיות תגבורת כחות הדינין שבקו השמאל ליניקת החיצוני' ע\"פ קו המדה וצריך להתנהג עמהם בביטול והכנעה דוקא שבהכנעה וביטול דוקא ימשיך מעשו כח הטוב הגנוז בו שנפל ומלובש בו כמו שהיה שרץ עשו לקראתו ויחבקהו (כמ\"ש בפ' וישלח) ועם שרו של עשו הי' עושה מלחמה ונצחו כמ\"ש ויאבק איש עמו כו' ולגבי עשו שלמטה היה צריך יעקב להכניע את עצמו ולא במלחמה כי כך היה צריך לפי אופן שרשו למעלה דכתיב ולאום כו' שהוא מדות דעשו לנגד מדות דיעקב דאת זה לעומת זה כו' וד\"ל. וכ\"ז בבחינת מדריגת יעקב אבל לגבי בחי' מדריגת יוסף זה היה נחשב לחטא ונענש על כך כנ\"ל דהנה שרש יוסף הוא בבחי' מקור ושרש לבחי' התיקון והוא מלך הח' הדר כו' שהוא הגבה למעלה מכל ההשתלשלות דתוהו ותיקון וע\"כ נק' פותר ותופר כו' שממנו מקור להיות אופן המשכת הקו המודד לאורות בכלים אם כך או כך כו' וא\"כ אין מנגד לו כלל שיפול ביראה ממנו בתוס' יניקה לחיצוני' אחר שהוא למעלה מעלה מהמשכות מקיפים ופנימים או\"כ כו' ולזאת לא היה ראוי לפי שרשו העליון שיהיה תולה בטחונו באדם כלל ולא לעשות תחבולות להזכירו אל פרעה ע\"י מליץ טוב כי אין לו יראה מן החיצוני' כלל ואין צריך להכניע את עצמו כלל וכלל כי שרשו גבוה הרבה מבחי' הצמצום דתיקון הנ\"ל וד\"ל אלא אדרבה צריך הוא להתנהג רק כפי שיהיה רצון ה' למעלה מעלה מן החכמה והטעם דבחי' התיקון כו' והוא כפי שירצה ה' לבד כך טוב לפניו ולא יעשה דבר מעצמו בזה כלל דאם רצון ה' שישב בבור דוקא ישב בבית האסורים ולא יעשה שום תחבולה איך לצאת מבית האסורים וכשיגיע זמנו לצאת ע\"פ ה' אז יצא כו' וכפי שיזמין לו ה' כן יהיה בלי התאמצות מכח עצמו בשום דבר מה כי כך הוא שרשו למעלה מעלה מכל סדר ההשתלשלות לגמרי כנ\"ל ע\"כ היה השגחת ה' ביוסף עד\"ז דוקא כו' וד\"ל. (ומטעם הנ\"ל שהוא למעלה מבחי' ההשתלשלות דתוהו ותיקון שאינו תלוי בבחי' החכ' ודעת דתיקון כו' ושר המשקים הוא בבחי' המשכת החסדים דחכ' כידוע ולכך נענש על שאמר לו כי אם זכרתני כו'. ומה שברח משה מלפני פרעה ולא תלה בטחונו בה' לבדו כו' גם הוא היה ירא שמא יגרום כח הדין ביותר לפי ששרשו דוקא בבחי' הדעת דתיקון דתורה ומצות דמשה מלגאו יעקב מלבר כו'). (וכמ\"כ יובן גם בכל דור ודור שבחי' יוסף צ\"ע בגלות כו' שנאמר עינו בכבל רגלו כו' וכן מלך אסור כו' כמו שראה ריב\"ל למשיח שרי ואסיר ואמר לו אימתי אתי מר כו' וד\"ל) וזהו בן פורת יוסף כו' פי' פורת אותיות תופר ופותר חלומות והוא ענין פורת"],[2300680347,"שמפרה ומרבה לאורות דתיקון כנ\"ל והכל מטעם א' להיותו מלך הח' הדר כו':\n(יד) <b>אך</b> הנה עדיין י\"ל מה שכפל עוד לומר בן פורת עלי עין כו'. הענין הוא דכתיב כל הדברים יגיעים לא יוכל איש לדבר לא תשבע העין לראות ולא תמלא האוזן כו'. פי' דברים יגיעים הם אותן דברים שלא יוכל איש לבררם ולהעלותם למעלה כלל כי הן דברים של הבל ומותרות שאין בהם ממש כלל להוסיף דברים יגיעים שיגיעים לריק והבל מצד ריבוי הפסולת שבהן לבטלה ממש כי הנה באמת אנו רואים כמה דברים הן מחשבות או דבורים או מעשים וענינים רבים ושונים שהמה יוצאים בעולם לבטלה ממש שלא יגיע מהם שום בירור והעלאת הטוב כלל אפי' בצדיקים שכל מעשיהם ומחשבתם ודבורם וכוונת לבם רק לה' לבדו מ\"מ נופל במח' ודבור שלהם וגם מעשים וענינים שהן זרים לגמרי כמחשבות של שטות והבל שאינו בעולם ודבורים של מה בכך כדברים הבטלים לגמרי וכן מעשים ויגיעים רבים של הבל וריק הרבה יותר מן החלומות שהן צירופים שנלקחו מעין הרהורי לבו ביום שהיה בהן אור וחיות מעט מזעיר עכ\"פ אלא שנתבלבלו הצירופים ואינן כסדרן וגם יש מהן ענינים כוזבים ביותר עכ\"ז המחשבה ודבור של הבל הבא בדרך מותרות ופסולת לגמרי למטה גם מן החלומות (שהרי החלומות שהן בבחי' התוהו לפי שכבר היה בבחי' אורות וכלים קודם הנפילה ע\"כ יכולים לבא לבחי' התיקון ע\"י פתרון דיוסף כנ\"ל משא\"כ בחי' המותרות דמחשבה ודבור ומעשה כמשי\"ת) וכ\"ש וק\"ו בבינונים ופשוטים שירבה בהם המותרות ופסולת במדו\"מ וגם הרבה יגיעה ועמל בגופם במשא ומתן שלא לצורך ותועלת כלל שלא הגיע מזה שום תועלת בעולם כלל וכלל וגם יש ריבוי שינוי מעשים ומחשבות רבות שמתחדשים בעולם בכל חלקי העולם בד' יסודות ודצח\"מ שנעשים ומתחדשים בכל יום בעוה\"ז אשר לא לה' המה ולא לאדם כי הן יוצאין רק לבטלה לגמרי כו' והטעם הוא כידוע שבחטא אדה\"ר בעה\"ד נתערב טו\"ר בכל הברואים גם בארץ וכל חלקי דצח\"מ וכמו שרואים בצמיחת החטה בארץ יצא ממנה הפסולת והרע ברקבון בארץ וגם בצמיחתה יהיה בה מוץ ותבן שאינו מאכל אדם ועד שיהיה בה טעם לחם צריך ריקוד טחינה לישה ואפיה וגם בבישול בקיבה יוצא הפסולת לחוץ וכך הוא בחי הנולד שיצא עמו פסולת מהדמים ושליא כו' וגם באדם יש פסולת רב שיוצא לאיבוד כליחות האוזן ופה וחוטם ומי רגלים וכה\"ג בגופו שערות וצפרנים כו' עד גם באורות וחיות דמחשבה דבור ומעשה שבגופו יש מחדו\"מ טובים ורעים כמו שיש טו\"ר בדצ\"ח. אך הנה יש הפרש בזה דטו\"ר גם ברע יש טוב אחר הבירור כמו הסיגים בכסף שיבורר מן הטוב וכן מחשבה רע יהפך לטובה כמכירת יוסף שאמר אתם חשבתם לרעה אלקים חשבה לטובה להחיות עם רב כו' וכן מעשה ודבור ורצון וחו\"ב ומדות בתערובות טו\"ר שבהן הרי יש חיות גדול ברע כמו בטוב ויכול לבא לידי תיקון לאחר זמן כידוע וכמ\"כ יש בכל דבר פנימיות וחיצוניות וחיצוניות דחיצוניות כמוץ ותבן בחטה וכקליפת הפרי ועור ובשר וגידים"],[2300680357,"ועצמות בחי שיש בהן מדריגות בחיצוניות וחיצוניות דחיצוניות (כציפרנים ושערות באדם) וכמ\"כ במחשבה דבור ומעשה שנופל בבחי' חיצוניות דחיצוניות כטרדת העמוקות במשא ומתן שהיה סבור שיגיע לתועלת הענין וכן יגיעות וסבות מתהפכים שהיה נדמה לאיזה תועלת חיצוני ביותר גם זה יכול הכל לבא לבירור (כחלומות שהן הנופלים ממחשבות חיצונים ודמיונות שוא וכזב גם הן יבוררו כנ\"ל) וכמ\"כ יש בתענוגי בנ\"א טו\"ר וחיצוניות דחיצוניות כתענוג המאכל שיצא בבחי' פסולת ורע באכילה גסה המזיק לו וכן בתאוות המשגל שיאבד כחו וכה\"ג בעושר והון לרע לו וכן בגדולה וכבוד כו' וגם חיצוניות דחיצוניות שלהם שהם רוב המחשבות זרות בתאוות וחמדת עוה\"ז הכל יכולים לעלות למעלה כי שרש התענוגים הגשמיים וכל הפסולת וחיצוניות דחיצוניות בארמ\"ע ודצח\"מ הכל נפל בבחי' מותרות ופסולת מתערובות טו\"ר שבחטא עה\"ד (בנהר) שיוצא חוץ לג\"ע הארץ אחר להט החרב כו' (וראי' לזה ממה שיש עליה ותיקון לרע להפוך לטוב בתשובה שלימה וכן יבוררו כל אוה\"ע לע\"ל דכתיב אז אהפוך אל עמים כו' וכן יש בירור עכשיו במאכל ומשגל כו'). אבל יש עוד בחי' פסולת שנקרא מותרות דמותרות שאין בהם חיות כלל גם לא בבחי' חיצוניות דחיצוניות כמו ברקבון הגרעין בארץ והפסולת שבארץ עצמה שאין מגיע ממנה תועלת כלל כי המוץ והתבן ראוי למאכל בהמה עכ\"פ כו' וכן בפסולת דאדם בדמים ושליא וכו' וכה\"ג בכל חלקי דצח\"מ גם בפנימיות שלהם כמו מחשבות זרות שאין בהם חיות כלל לא לטוב ולא לרע רק הן של הבל וריק שעולה במחשבה ודבור שנק' שוא ממש כו' וכן ברצון ושכל ומדות שנופלים בבחי' מותרות דמותרות שאין בהן חיות כלל אלא הולכים לבטלה לגמרי (וכך הוא בכל ריבוי הענינים ומעשים שנעשו בעולם שהן לריק ולבטלה ממש שאין להם שרש בתחלת התהוות כל בריאה מאין ליש) דבאמת יש להפליא בזה מאד מאין יצא מציאות מותרי שפע כזאת שהוא לריק ולבטלה לגמרי הרי כל הברואים נבראו בדבר ה' כי אין לך דבר חוץ ממנו כו' וגם בחי' הפסולת ורע שבא בתערובות בכל הברואים הרי אמר דאת זה לעומת זה עשה האלקים כו' וגם שאין רע יורד מלמעלה כו' אבל למטה נברא מציאת הרע כמו בראת צדיקים בראת רשעים כו' כמו בכל חלקי הפסולת וחיצוניות דדצח\"מ שיכולים להתקן כמ\"ש לעשות ולתקן כו' וא\"כ כל המחשבות ודבורים שלא לה' המה כלל כנ\"ל הם נשפעים מלמעלה שאין לך דבר שאין לו שרש למעלה רק שנמשך מבחי' חיצוניות דחיצוניות דשפע האלקי' בנבראים בצמצומים רבים ועצומים עד שיש כח וחיות גם לבחי' המותרות ופסולת משום דאת זה לעומת זה עשה כו' ובדרך שאדם רוצה כו' וכן יש טו\"ר בדצ\"ח ותענוגים זרים כו' אבל מהיכן ימצא מציאות מותרות שפע כזו שאינן כלום רק לריק והבל ממש (וכמו גקה\"ט שנק' אין ואפס ממש וכמו הכל ברא חוץ מן השקר כו' וכמו האפיקורסים כו' שמורידין ולא מעלין דגם חזיר עתיד ליטהר כו' וגם הנפילים שהיו בארץ שנפלו בבחי' פסולת יבוררו לע\"ל כנ\"ל):"],[2300680367,"(טו) <b>אך</b> הענין הוא דודאי א\"א לומר שיש למותרות כזה שרש למעלה שנמשך בדרך בריאה מבחי' דבור העליון כשאר הברואים שאין לך דבר שאין לו מקור ושרש למעלה ובהסתלק המקור ושרש מאלקו' בורא הכל אין לו מציאות כלל כידוע אך שבעת ירידת השפע האלקית מלמעלה על כל הברואים והנמצאים יצא גם מותרות שפע כזו שהוא בא בדרך איבוד ובטלה כמשל הזורע זריעה בארץ א\"א שלא ילך לאיבוד ולבטלה מתמצית הנופל למטה וכן השופע יין או שאר משקים או אפשר שלא ילך טיפה אחת לבטלה או השמרים הנשארים שזורקים חוץ וכן גם במשפיע דבר חכמה אי אפשר שברוב דברים יפול גם דברי פסולת שאין בהם חכמה כלל רק שטות וסכלות או דברי ערמה ומרמה שאין זה נחשב גם מחיצוניות דחיצוניו' דחכ' רק כמו דברי הבל ושוא וכזב (ולכך נק' ערמ' הפוך דחכמה שנק' כח מ\"ה כמ\"ש במ\"א בענין אני חכמה שכנתי ערמה לברר לערמה דק\"נ) (וכך יש בתענוגי בני אדם בדבר שאין בו שום טעם וחיות כלל רק כדבר הבל וריק ממש והוא התענוג שבליצנות והוללות שהוא השחוק וקלות ראש שמזה ירבה מאד דברים בטלים כו' וכן להפוך גם בצער יש שאין בו ממש והוא העולה על דעתו פחד ודאגה שאין בו שום ממשות כלל לא בהיזק גופו ולא בממונו רק שזהו מחמת ריקנות הנפש (בל\"א פויעלט) כריקבון הגרעין וכטפה שנסרח כו') וכה\"ג יובן גם ברוחניות בברואים שנבראו בע\"ש ביה\"ש שהוא אחר כל השפע גם בחיצונות דחיצוניות והן השדים כידוע) ויש שדין יהודאין שהן מקום שנזרע אור הזרוע צ\"ע שיוצאים לאיבוד באחרונה וכמו הנפילים היו בארץ כו' ויש שדין נוכראין כאפקורסים וכל ע\"ז שנק' אין ואפס וכמו מר מדלי וכשחק כו'). ואמנם הנה עכ\"ז גם בחי' מותרות כזו לא ילך לאיבוד לבטלה לעולם דודאי ירידה כזו גם היא לצורך עליה שיתעלו גם הם כי לא ידח ממנו נדח גם בחי' המותרות דמותרות מאחר שממקום גבוה באו (וכדוגמא דשפע האלקי' בע\"ש דנוגה) גם שירבו כל תועבה נשפע להם כל טוב תענוגי עוה\"ז שהוא רק בחי' המותרות שפע שבא מצד בחי' הרוממות דוקא שלפי ערך ריבוי התגברות השפע במקור העליון ביותר יפלו משם גם בחי' מותרות שפע בלי שיעו' (כחבית המליא' ביות' שישפך ממנה לחוץ יותר כמ\"ש במ\"א) וזהו פי' כל הדברים יגיעים לא יוכל איש לדבר כו' דמה שיכול איש לדבר ועין לראות זהו מה שבא באור שפע הפנימית דחכ\"ע בכלי הדבור ובעין לראות ואוזן לשמוע כו' אבל דברים יגיעים שנופל בבחי' מותרות שלא יוכל איש לדבר זהו מצד עומק השפע בבחי' רוממות שמופלא ומובדל מן ההשגה שלא יוכל להביא בדבור שלפ\"ע התגברות השפע בבחי' הרוממות דוקא יפול בחי' המותרות א\"כ הרי דברים יגיעים באמת שלא יוכל איש להשיגם ולדבר בדיבור גם ביגיעה רבה שלזה נק' דברים יגיעים שלא תשבע העין דחכ' לראות ולא תמלא האוזן דבינה לשמוע ולקבל מזה דוקא יפול בחי' המותרות שנק' דברים יגיעים דריק כמשל התינוק שלא יוכל להשיג העומק של החכ' ומדבר בדבור אז ידבר דברי הבל ושטות מפני בלבול כלי דעתו שלא יכילנו כו' אבל"],[2300680376,"להפוך בחכם המופלג ביותר שגם בהתגברות אור השפע בעומק דעומק החכמה שיפול גם ריבוי מותרות דברים לבטלה לגמרי ולא יהיה בהם איבוד כלל כי הכל יתקן ויביאם אל הפנימי ולא יהיה אף אות אחת לבטלה על דרך שאמר בתלמידי חכמים ועליהו לא יבול דגם שיחת ת\"ח שנופל מחכמתו בבחי' נובלות כעלה הנובל בארץ צריכה לימוד דגם שיחה בטלה שלו יש בה חכמה גדולה כו' וכמו משלי שלמה שבא עומק מחשבתו במשלים וחידות שהן כמו דברים בטלים ממש ובהן מלובש כל עומק החכמה דוקא ואין בהם אפי' אות אחת לבטלה וכן מ\"ש וידבר שלמה מן הארז אשר בלבנון עד האזוב אשר בקיר כו' שהיה אור חכמתו בשרשו בחכמה עילאה דאור אבא שבמל' שמפני הרוממות דחכ' דוקא יכול להשפיל את עצמו למטה מטה ביותר כידוע הכלל הזה דכל הגבוה גבוה יותר יותר יכול לירד למטה שזהו גם שיחת ת\"ח כו' וע\"כ היה חכמה דשלמה נמשך למטה גם בכל דברים הגשמיים מארז אשר בלבנון עד האזוב כו' היה מדבר בהם דברי חכ' עילאה כו' לתקנם ולהעלותם מעולם הפירוד לעולם היחוד והוא מה שעשה מהם צירופים טובים ומתוקנים גם מכל המעשים ודבורים זרים וגם מחשבות זרות שנופלים בבחינת מותרות עשה בהם צירופים טובים בחכמתו ובירר והעלה הכל דבחכמה אתברירו דוקא. וזהו בחכמה תתאה דשלמה ששרשו בחכמה עילאה כמ\"ש חכמת בחוץ דוקא תרונה כמ\"ש במ\"א (וכמ\"כ בחכמה תתאה שבתורה דוקא שנתלבשה בדברים גשמיים וכידוע שהוא נק' משל הוי' וכל מה שדברה תורה בכל דצח\"מ כמו בהבדלה בין טהור לטמא בעופות ובהמות וחיות וגם בכל דיני מאכל באסור והיתר כשר ופסול ובדיני אדם בזה נברר כל חלקי כו'. (אך הנה כ\"ז היינו מה שיוכל איש לדבר בדברי חכ' הפנימית לברר ולתקן כל בחי' החיצונות ומותרות ג\"כ כענין שיחת תלמידי חכמים דעליהו לא יבול כו' אבל דברים יגיעים לגמרי שהן דברי בטלה וריק לגמרי שלא יוכל איש לדבר בהן בחכ' ולבררם ולתקנם מצד שהן בחי' מותרות דמותרות לגמרי שהולך לאיבוד גמור ואין כח בחכמה שבדבור לבררם ולא בעין ואוזן דראיה ושמיעה דפנימיות הלב כו' מפני ששרש נפילתם באה מעומק רוממות החכ' כשנתגבר השפע ביותר כנ\"ל דמחמת עוצם הרוממות יפול גם מותרות כזו דכלא ממש חשיב (וכעצמות וקליפות שנופלים מן השלחן לארץ כו'). אמנם הנה ע\"י יוסף דוקא הוא שיש עליה ותיקון גם למותרות כזו והוא מה שבחי' יוסף צ\"ע עושה צירופים טובים גם מכל המעשים ומח' ודבורים שהן דברים בטלים וריק לגמרי (יותר מן החלומות ששוא ידברו שיש בהן אמת ג\"כ כנ\"ל) וכמו מערמה ושקר שהוא שוא וכזב ממש אני חכמה שכנתי ערמה לבררה ולהעלותה לקדושה כיעקב שבירר ללבן הארמי (שזהו ענין גלות זה האחרון כמ\"ש במ\"א) וכמו שהחכם המופלג ביותר שגם בהתגברות אור השפע ברוממות בעצמו יכול לתקן גם המותרות דדברים בטלי' לגמרי ולא יהי' לאיבוד אפי' אות א' כנ\"ל וזה לא היה ביכולת רק ביוסף להיותו במעלה יתירה בשרשו למעלה מאד והוא"],[2300680384,"בבחי' מקור התענוג העליון שזהו יוסף שיוסיף וירבה להיותו מקור כל התענוגים בא בתוספת וריבוי לאין שיעור והוא מקור השעשועים שבחכ' הקדומה דתוה\"ק כו' ע\"כ יש בכח להעלות גם הצירופים הזרים ביותר שנפלו לאיבוד לעשות מהם צירופים עליונים דקדושה למע' עד שיבורר הכל גם כל תענוג זר של הבל כשחוק וליצנות כמ\"ש אז ימלא שחוק פינו כו' וכל דברי בלע ומרמה דק\"נ ושוא ושקר כאפקורסים וכה\"ג שנק' אין ואפס ממש שנאמר כל הגוים כאין כו' רק שיש מהם שמתעכב הבירור ע\"י זמן רב כמאה שנים ויותר ויש שמתברר ועולה במעט זמן ביו\"ד ועשרים שנה אבל בכל יום ויום מתברר ועולה ע\"י יוסף גם מן כל הדברים הנופלים לבטלה וריק לגמרי ואעפ\"כ לא ידח ממנו נדח אפי' דבר כ\"ש ממש שהכל יתעלה ע\"י יוסף דוקא ובזאת יתרון מעלתו גם על החכמה דתורה שמברר גם החיצוניות אבל להיות יוסף בשרש ומקור דחכ' דתיקון והוא בשעשועים העצמיים דא\"ס בבחי' האין האמיתי יכול לתקן ולהעלות גם הדברים יגיעים דבטלה וריק לגמרי שנק' אין ואפס ממש לפי שכל הגבוה יותר יכול להשפיל את עצמו למטה יותר (שאין כח ירידה כזו גם בחכ' שלמה וחכ' דתו' מפני שאין שרשה רק בעונג שבחה\"ק כו'):\n(טז) <b>ובזה</b> יובן מה שמספרים בשבחי הבעש\"ט ז\"ל שהתפלל כמה תפלות והתענ' תעניתי' שיוכל להשיב לשואלו דבר בעת עליות נשמתו בע\"ש בין השמשות בקבלת שבת דוקא ולא שהיה כוונתו שיהיה יכול להשיב לשואלו דוקא אלא הענין הוא דבשעת קבלת שבת אז עליות כל העולמות עד רום המעלות והיה נשמתו עולה במעלה ומדריגה גבוה מאד (כמו בבחי' יוסף ומשיח בחי' צ\"ע שבכל דור ודור כידוע) ולא היה יכול להשפיל את עצמו למטה כלל להשיב לשואלו וכה\"ג שזהו ענין התיקון ובירור בדברים בטלים לגמרי שנשאר למטה דוקא בעת עליית הפנימי' (וכנ\"ל בענין השדים שנבראו בע\"ש בין השמשות וכמ\"ש בזוהר דקידוש השבת הפסיק שלא נברא גופים שלהם כו') ולזה התפלל כמה תפלות שיוכל לירד למטה דוקא בעת עליות נשמתו הגבה למעלה לפני קבלת שבת שיוכל לתקן גם מה שנשאר למטה בבחי' מותרות דריק ובטלה כמדריגות יוסף הנ\"ל שיש בכחו להשפיל את עצמו כ\"כ למטה בצירופי הדברים בטלים וריקים לבררם ג\"כ כי כל הגבוה יותר כו' כנ\"ל. וזהו שהיה יכול להשיב לשואלו דבר בדברים בטלים אחר שעשה כמה יחודים בתפלה ותענית ע\"ד זה שלא היה בכחו תחלה לירד למטה כ\"כ לפי שלא היה ברוממות המדריגה כ\"כ וד\"ל. ובכ\"ז יובן מ\"ש בזוהר בר\"מ דשכינתא אזלא מאתר לאתר ומדוך לדוך כו'. פי' שכינתא ידוע שהוא עולם הדבור העליון ששוכן למטה בתחתונים להוות כל הברואים מאין ליש כמ\"ש ומלכותו בכל כו'. ואמנם בכל הברואים שבעולם גם בחיצוניות דחיצוניות השפע כמו בע\"ש ומזלות שמשפיעים רוחניות דד' יסודות ודצח\"ם וגם בכל חלקי העולם הגשמי בארץ וכל אשר בה יוכל להיות שם מאור שפע האלקי ממש כי אין לך דבר חוץ ממנו כו' רק שהוא בבחינת"],[2300680392,"צמצום והסתר גדול מאד כידוע אבל מ\"ש שכינתא אזלא מאתר לאתר כו' שהוא כמו גלות האדם שהוא נע ונד בארץ ולא ישכון במקום אחד לפי שלא יכול לסבול המקום שדר בו והוא ענין גלות השכינה בע\"ש מאתר לאתר כו' שהוא מצד גלות השכינה שאין בכח הדבור העליון לברר ולהעלות כל הנופל בע\"ש בבחי' מותרות דמותרות שנק' ריק ובטלה כדברים בטלים ומעשים הבטלים מעיקרן כו' רק ע\"י יוסף צ\"ע הוא המע' לשכינה משם ע\"י שמתקן ומעלה לעשות מכל הנופל בק\"נ צירופים טובים ומתוקנים כנ\"ל. וזהו שאמר דשכינתא אזלא כו' שע\"י בחי' הדבור דשכינה הוא שנעשה עליה זו כאשר אזלא מאתר לאתר כו'. והענין הוא ע\"ד דוגמא שאנו רואים כמה מעשים וענינים בטלים מעיקרן כמלחמות רבות שנהרגו ונאבדו רבבות נפשות לחנם כי בטל טעם המלחמה אמנם מהקולות המרים וגם שמחים מנאנחים וזועקים ברינה בעת המלחמה שמתערבים יחד מתבררים ונעשים שיר וניגון טוב למעלה שיוכלו לעשות התפעלות אהוי\"ר בלב כמה בני אדם צדיקים שעי\"ז נתברר הכל בכל אשר נעשה כל מעשה הבטל וכן כמה דבורים בטלים שיספרו בני אדם זה לזה עד שיגיע לאיזה חכם וצדיק שיתפעל מזה ויקח ממנו כחות מוסר וכה\"ג וד\"ל. וז\"ש דשכינתא אזלא מאתר לאתר שזהו עליה מנמוך לגבוה וגבוהים עליהם כו' עד שיתעלה כל עולם הדבור למע' גם מן הדברים יגיעים שנפלו לארץ כנ\"ל וזהו ע\"י יוסף דוקא שהוא המברר ועושה מהם צירופים אחרים דקדושה העליונה וזהו מצד יתרון מעלתו הרבה מן הדבור העליון ע\"כ יכול להעלות גם מה שאין בכח הדבור העליון כו'. וזהו בן פורת יוסף בן פורת עלי עין פי' פורת הא' הוא מה שתופר ופותר חלומות שתפירה זו אינו אלא באותיות שנפלו מבחי' התוהו כנ\"ל שיכול להביאם בכלים מכלים שונים כנ\"ל שזהו פורת מפרה ומרבה (שזה הכח יש גם בחכמה דתורה ומצות שהוא בחי' התיקון כידוע רק שיוסף הוא מלך הח' הדר מקור זה התיקון) אבל מה שחזר וכפל עלי עין היינו שחוזר ותופר תפירה שני' יותר גבוה מן תפירה הראשונה והוא מה שמשפיל את עצמו כל כך למטה מטה לתפור ולחבר ולעלות גם כל הצירופים הבטלים הנמוכים ביותר מותרות דמותרות מדבור העליון כמו דברים בטלים לגמרי כנ\"ל עד שגם הם יעלו למעלה ודאי זהו בא מכח העליון ורם ביותר שכל הגבוה יותר יוכל להשפיל למטה יותר ולא שאינו גבוה כל כך כנ\"ל שזהו פורת שמפרה ומרבה שזהו הכח יש גם בחכמה דתומ\"צ שהוא בחי' התיקון כידוע. וז\"ש עלי עין מפני שהיה מדריגתו למעלה מבחי' עין דח\"ע כמו עיני העדה כו' שאין ראיה דחכ' יכול לבררם כלל (וכמ\"ש כל הדברים יגיעים לא תשב' עין לראו' כו') ולפי שיוס' היה עלי עין היה יכול להשפיל א\"ע כ\"כ להעלו' גם הדבורי' שנפל משרשו בח\"ע בבחי' המותרו' לגמרי לתקן כו' כנ\"ל ולזאת המעלה היתירה כפל עוד לומר ב\"פ ע\"ע שמפני שתפירה זו עלי עין דחכ' דתורה היא למעלה הרבה מתפירה הראשונה שהי' תופר ופותר חלומות מטעם הנ\"ל וד\"ל:"],[2300540044,"<b>ב\"ה פ' שמות אשר שמעתי בשנת תקפזיי\"ן בק' לובאויץ</b>\n<span data-k=\"pg\">א</span> ּ<b>ואלה</b> שמות<sup data-n=\"1\">1</sup> בני ישראל<sup data-n=\"2\">2</sup> הבאים מצרימה את יעקב איש וביתו באו. הנה יש להבין בזה שפתח כאן בפ' זו במ\"ש ואלה שמות בנ\"י כו' דמשמע כמודיע דבר חדש במספר הבאים וגם בשמותם והלא כבר הזכירם בסדר ויגש בא' ואלה שמות בנ\"י הבאים מצרימה יעקב ובניו<sup data-n=\"3\">3</sup> כו', וא\"כ למה כפל הדבר עוד פעם שנית לומר ואלה שמות כו' (ורש\"י פי'<sup data-n=\"4\">4</sup> אע\"פ שמנאן בחייהם חזר ומנאן במיתתן להודיע חיבתן שנמשלו לכוכבים ש[נ]א' המוציא במספר צבאם<sup data-n=\"5\">5</sup> כו' ואין זה תירוץ כלל דבחייהן הי' ראוי להודיע מספר הנפשות הבאים ואמנם לאחר מיתת כל הדור ההוא למה צריך לכפול הדבר עוד כו' מאחר שכבר הודיע, וגם איך אומר כאן הבאים והל\"ל אשר באו דבאים משמע שבאים כעת כו'). ועוד יש להבין למה שינה הלשון כאן מכמו שא' בפ' ויגש דכאן א' הבאים מצרימה את יעקב איש וביתו באו ושם א' הבאים מצריימה יעקב ובניו, דמלשון זה משמע שגם יעקב עצמו נכלל בכלל בנ\"י הבאים שהזכיר שהן יעקב ובניו, ולפי האמת הרי יעקב הוא ישראל עצמו כמ\"ש ולא יקרא כו' כ\"א ישראל<sup data-n=\"6\">6</sup> וע\"כ א' ברישא ואלה שמות בני ישראל דוקא, וא\"כ איך א' יעקב ובניו שסותר לרישא שא' רק ואלה שמות בני ישראל כו' ושינה שמו מישראל ליעקב, וכאן א' ואלה שמות כו' את יעקב דמשמע",[["1","1","<b>ואלה שמות</b>: מיוסד על ד\"ה ואלה שמות שנדפס בתו\"א שמות מט, א (וראה גם) מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ריט. ומאמר התו\"א בתוס' הגהות וכו' באוה\"ת שמות כרך א ע' ז-נא. כרך ז ע' ב'תעה-ב'תצא. כרך ח ע' ב'תתכג. ב'תתל. וראה גם ד\"ה ואלה שמות תשמ\"ו. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2","2","<b>ואלה שמות בני ישראל</b>: שמות א, א."],["3","3","<b>ואלה שמות. . ובניו. . בכור יעקב ראובן</b>: ויגש מו, ח."],["4","4","<b>ורש\"י פי'</b>: לשון רש\"י כאן בדילוגים."],["5","5","<b>המוציא במספר צבאם</b>: ישעי' מ, כו."],["6","6","<b>ולא יקרא. . ישראל</b>: וישלח לה, י [ושם: לא — ראה לקמן יט, ד. מאמרי אדה\"א דברים ח\"ג ע' א'נו]."]]],[2300540082,"שיעקב אינו נמנה עם הבאים כי הוא עיקר רק את יעקב טפל אליו איש וביתו כו' שאינו סותר לרישא שא' רק ואלה שמות בנ\"י כו', אבל מה ששינה שמו גם כאן וקראו יעקב והול\"ל את ישראל איש וביתו כו' כמ\"ש ברישא ואלה שמות בנ\"י זהו פלא (והנה באמת בפ' ויגש לא מנה שמות כל השבטים כסדרן כמו שמנה כאן רק א' שם בכור יעקב ראובן כו' לפי שבא רק לספר משפחת כל איש הנולדי' וכאן העיקר הוא למנות מספר שמות השבטים כסדרן<sup data-n=\"7\">7</sup> כו'). וידוע שהתורה נצחי'<sup data-n=\"8\">8</sup> היא ומדברת בכל זמן ובכל דור, כי שרש האבות והשבטים גם עכשיו הן במספר שמות למעלה בכל העולמות העליונים אף בעולם האצי' בבחי' ישראל ויעקב דלעילא ויב\"ש שנק' שבטי י\"ה וכן מאצי' לבריאה כו' (כמבואר בזהר פ' פקודי<sup data-n=\"9\">9</sup> בהיכלות העליוני' דיש שם ד' דגלי' כו' ואיש על דגלו באותות<sup data-n=\"10\">10</sup> כו') להיותם בחי' שרשים אל הנשמות שבכל הדורות שנק' ענפים כמ\"ש הבאים ישרש יעקב<sup data-n=\"11\">11</sup> כו' כידוע<sup data-n=\"12\">12</sup> ), ולפ\"ז גם עכשיו בכל דור ובכל זמן הוא אומר ואלה שמות בנ\"י הבאים כו' לפי שכל גלות ידמה לגלות מצרים<sup data-n=\"13\">13</sup> וכמו שהיו יעקב ובניו בגלות מצרים כך גם עתה, וגם השכינה בגלות עמו כמ\"ש אנכי ארד עמך<sup data-n=\"14\">14</sup> כו' וד\"ל.\n[ב] <b>והנה</b> תחלה יש להקדים מ\"ש כימי צאתך מאמ\"צ<sup data-n=\"15\">15</sup> אראנו נפלאות וידוע דזה קאי על גאולה העתידה לבא בביאת גואל אחרון שהוא משיח ב\"ד כמו שאו' גאלתי אתכם אחרית כבראשית<sup data-n=\"16\">16</sup> כו' וכמ\"ש בקי\"ס עד יעבור עמך הוי'<sup data-n=\"17\">17</sup> עד יעבור, ב\"פ עד יעבור, לשון להבא דזהו גאולה אחרונה דמשיח בקיבוץ גליות שע\"ז א' עד יעבור עמך הוי' כמ\"ש אהי' אשר אהי'<sup data-n=\"18\">18</sup> אהי' הא' אנא זמין לאתגלאה<sup data-n=\"19\">20</sup> בימות המשיח, ואהי' הב' בעוה\"ב<sup data-n=\"20\">19</sup> שע\"ז א' עד יעבור סתם למעלה משם הוי' <span data-k=\"pg\">4</span> ּ דתו\"מ<sup data-n=\"21\">21</sup> כו' (כמ\"ש במ\"א במ\"ש<sup data-n=\"22\">22</sup> ובשביעית כו' חנם בלא מצות<sup data-n=\"23\">23</sup> ) והוא שיעברו נהר פרת<sup data-n=\"24\">24</sup> (דהוא דמעיקרא<sup data-n=\"25\">25</sup> שהוא נהר שיוצא מעדן עצמו וכמ\"ש במ\"א). וזהו שארז\"ל (במס' מנחות) יבא טוב ויקבל טוב<sup data-n=\"26\">26</sup> כו' יבא טוב זה משה שהוא משיח<sup data-n=\"27\">27</sup> (כמ\"ש מה",[["7","7","<b>למנות. . השבטים כסדרן</b>: היינו רק השבטים (ולא תולדותיהם)."],["8","8","<b>שהתורה נצחי'</b>: ראה תניא פי\"ז. מאמרי אדה\"ז תקס\"ג ח\"א ע' קלג. לקמן א, ד. פ' וארא עב, ג. פג, ג. בשלח קלז, ג. יתרו רנז, ג. תצוה שסג, ג. שעא, ג. ויקהל שצג, א. תיב, א. מאמרי אדה\"א בראשית ע' צג־ קונטרסים ע' רמא־ הנחות תקע\"ז ע' פב ובהנסמן בהנ\"ל. שע\"ת ס, ד. ד\"ה וספרתם לכם (מר\"ה — בוך 972 ע' לז) בשם הבעש\"ט — יודפס בעה\"י בפלח הרמון על ספר ויקרא."],["9","9","<b>בזהר פ' פקודי</b>: ראה מאמרי אדה\"א בראשית ע' תצח. וש\"נ. תו\"ח ח\"ש קכט, ג ובהערה 22. אוה\"ת במדבר ע' ל. זהר במדבר קיח, ב. בהעלותך קנד, א ואילך. לקמן פ' וארא עט, א."],["10","10","<b>ואיש על דגלו באותות</b>: במדבר ב, ב."],["11","11","<b>הבאים ישרש יעקב</b>: ישעי' כז, א. ראה גם לקמן פ' וארא סו, א."],["12","12","<b>כידוע)</b>: גם בהכת\"י לא נסמן התחלת החצע\"ג."],["13","13","<b>שכל גלות. . מצרים</b>: ראה ויק\"ר פי\"ג, ה."],["14","14","<b>אנכי ארד עמך</b>: ויגש מו, ד. ראה לקמן פ' וארא פו, ב."],["15","15","<b>כימי צאתך מאמ\"צ</b>: מיכה ז, טו."],["16","16","<b>גאלתי אתכם אחרית כבראשית</b>: נוסח קדושת כתר בסידור אדה\"ז. ראה הנסמן בשער האמונה פט, א הערה 11."],["17","17","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה לקמן פ' בשלח קפה, ד. קצח, ג. רכד, ג. מאמרי אדה\"א שמות ח\"א ע' סא־ דברים ח\"א ע' טו ואילך־ ח\"ד ע' א'קפד ובהנסמן בהנ\"ל. שה\"א ס, א."],["18","18","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["19","20","<b>אנא זמין לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."],["20","19","<b>אהי' הא'. . בימות המשיח. . הב' בעוה\"ב</b>: ראה בהנסמן לעיל הערה 17."],["21","21","<b>עד יעבור. . למעלה משם הוי' דתו\"מ</b>: ראה גם שה\"א ס, א. שם לא, א הערה 3. לג, ב הערה 22. וראה גם לקמן פ' וארא נ, ד. פ' בשלח קפה, ד. קצח, ד."],["22","22","<b>במ\"ש</b>: ייח: ליתא."],["23","23","<b>ובשביעית </b>[כה: בשביעית]<b> כו' חנם בלא מצות</b>: משפטים כא, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רנט ואילך. תו\"א משפטים עו, א וסע\"ג. מאמרי אדה\"א דברים ח\"ג ע' א'קל. נ\"ך ע' תעא־ דרושי חתונה ח\"ב ע' תקכו ובהנסמן בהנ\"ל. במדבר ח\"ב ע' תשעה. תו\"ח לך צד, ד. תולדות קנב, א. לקמן פ' משפטים רעט, א. רפו, א. רצב, ד. שב, א."],["24","24","<b>שיעברו נהר פרת</b>: נסמן לקמן מ, ד."],["25","25","<b>דהוא דמעיקרא</b>: בכורות נה, ב. ראה גם לקמן לה, ב. פ' בשלח קפו, א. שה\"א פג, ב."],["26","26","<b>יבא טוב ויקבל טוב</b>: נסמן לקמן מג, ד."],["27","27","<b>משה שהוא משיח</b>: ראה הנסמן לקמן שם. תו\"ח בראשית יד, ב ובהערה 12."]]],[2300540120,"שמו<sup data-n=\"28\">28</sup> אותיות משה<sup data-n=\"29\">29</sup> מה שם בנו הוא משיח<sup data-n=\"30\">30</sup> שא' בו בני היום ילדתיך<sup data-n=\"31\">31</sup> כו') שיקבל התורה שנק' טוב עוד הפעם כו', והענין הוא דכמו שמשה קיבל התורה הנגלית לנו במ\"ת בי' הדברות לברר לעה\"ד טו\"ר בפו\"מ שזהו מה שח\"ע דתוה\"ק שהיא בבחי' עה\"ח שכולו טוב וחיים כו' ירדה למטה לתקן לעה\"ד כו', כך הוא עצמו דוקא (שנק' טוב בטי\"ת<sup data-n=\"32\">32</sup> רבתי<sup data-n=\"33\">33</sup> שירדה נשמתו מעה\"ח (משמטה<sup data-n=\"34\">34</sup> הא' דחסד<sup data-n=\"35\">35</sup> כמ\"ש במ\"א [במ\"ש] כי מן המים<sup data-n=\"36\">36</sup> עליונים<sup data-n=\"37\">37</sup> משיתיהו) יתלבש בנשמת משיח ב\"ד ויקבל טוב דתורה הפנימי'<sup data-n=\"38\">*38</sup> שנק' טעמי תומ\"צ כמו שהוא למעלה ממש (כמ\"ש במ\"א<sup data-n=\"39\">38</sup> ). וז\"ש כימי צאתך מאמ\"צ היו נסים ונפלאות למטה בשביל קבלת התורה הנגלית וגם בשביל זה הי' עיקר הגלות במצרים בעבודה קשה בחו\"ל<sup data-n=\"40\">39</sup> (כמשי\"ת) כדי שעי\"ז יזכו לקבלה זו בה\"ס פב\"פ<sup data-n=\"41\">40</sup> שלא הי' אפשר להיות להם גילוי אור גדול כזה בלתי השעבוד הקשה בחו\"ל רד\"ו שנה<sup data-n=\"42\">41</sup> כו' (כמ\"ש במ\"א ע\"פ וארא כו' ושמי הוי' דתו\"מ בגשמיות לא נודעתי להם<sup data-n=\"43\">42</sup> רק ברוחניות אבל כדי שיזכו ישראל לזה צ\"ל הגלות הזה דוקא), וכך יהי' בדוגמא זאת במעלה עליונה ביותר והוא מ\"ש אראנו נפלאות העליוני' שיבאו מהעלם לגילוי למעלה (שהוא גילוי דהעלם חשמל העליון<sup data-n=\"44\">43</sup> שישת חשך סתרו<sup data-n=\"45\">44</sup> שמפני זה יבא כל רז וסוד ה' לגילוי שהן טעמי<sup data-n=\"46\">45</sup> תו\"מ), וכ\"ש וק\"ו הוא דאם בשביל קבלת התורה הנגלית הוצרכו להיות בגלות רד\"ו שנה א\"כ כדי שיזכו לקבלת התורה הפנימי' צריך שיהי' בגלות זמן רב בכפלי כפליים יותר דלפ\"ע התגלות מעלת אור גדול ביותר כן לפ\"ע צריך להיות תחלה ההסתר והצמצום בגלות יותר דודאי לפום צערא אגרא<sup data-n=\"47\">47</sup> דממילא מובן שלפ\"ע השכר כן יהי' ערך הצער ולכך נתארך זה הגלות ביותר<sup data-n=\"48\">46</sup> כו'. וכידוע שבזמן הגלות נק' בחי' ההסתר פנים כמ\"ש ביום ההוא אסתיר פני<sup data-n=\"49\">48</sup> כו' והוא בחי' עלי' והסתלקות הפנימי' למעלה מעלה כמ\"ש בזהר דקוב\"ה",[["28","28","<b>מה שמו. . מה שם בנו</b>: משלי ל, ד [ושם: ומה שם — ראה לקמן י, א. לד, ג. מט, ב. פ' בשלח קנו, ד. קס, ד. ריג, ד. ש\"א לא, ב. הנסמן בתו\"ח ויצא קעה, ב הערה 25. שעה\"י קלב, ב הערה 23]."],["29","29","<b>מה שמו אותיות משה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' טז. (וראה גם הנסמן לקמן מג, ג)."],["30","30","<b>מה שמו. . משה. . בנו הוא משיח</b>: ראה גם תו\"ח בראשית יד, ב. שה\"א צה, ב. לקמן מט, ב. וש\"נ."],["31","31","<b>בני </b>[יז: ניתוסף: כו']<b> היום ילדתיך</b>: תהלים ב, ז. ראה סוכה נב, א. הנסמן מאמרי אדה\"א דברים ח\"ד ע' א'תקט. שה\"א קד, א. תו\"ח נח נח, ב ובהערה 27. לקמן פ' וארא עא, א. בשלח קנה, ד. קצו, ג. משפטים רצו, ד. ש, ב. ויקהל שצט, ג. תא, ג."],["32","32","<b>שמשה. . טוב בטי\"ת רבתי</b>: נסמן לקמן מג, ד הערה 48."],["33","33","<b>רבתי</b>: אולי צ\"ל: רבתי). וראה הערה שלאח\"ז."],["34","34","<b>(משמיטה</b>: ה: משמיטה. כה: כבפנים."],["35","35","<b>משמיטה הא' דחסד</b>: ראה ברית הלוי (לר\"ש אלקב\"ץ) בסופו בתשובה היסוד הששי (מא, סע\"א ואילך). לקמן מג, א ואילך ובהנסמן בריש המאמר שם. לקמן פ' משפטים רעט, א. רפה, א. מאמרי אדה\"ז אתהלך לאזניא ע' מה. תקס\"ב ח\"א ע' טז. יז. הנסמן בתו\"ח מקץ ריז, ב הערה 20."],["36","36","<b>כי מן המים. . משיתיהו</b>: שמות ב, י. ראה גם לקמן מג, א ובהנסמן לשם."],["37","37","<b>עליונים</b>: איז: ליתא."],["38","*38","<b>שמשה. . בנשמת משיח. . דתורה הפנימי'</b>: ראה גם רש\"י שה\"ש א, ב (ומובטחים מאתו וכו'). שער האמונה צה, ב. אמרי בינה שער הציצית פט, ג ואילך. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרכה."],["39","38","<b>יתלבש בנשמת. . במ\"א)</b>: ט: ליתא. וכנראה שזהו טעות המעתיק."],["40","39","<b>בחו\"ל</b>: בחומר ו(ב)לבנים."],["41","40","<b>פב\"פ</b>: ואתחנן ה, ד."],["42","41","<b>רד\"ו שנה</b>: ראה תנחומא מקץ ח. רש\"י מקץ מב, ט. ועד\"ז במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שג. ולהעיר מלקמן פ' וארא סה, א. מאמרי אדה\"א בראשית ע' רעט. וש\"נ."],["43","42","<b>וארא. . לא נודעתי להם</b>: וארא ו, ג. ראה מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע יב. מאמרי אדה\"א בראשית ע' קעט. שמות ח\"א ע' רנז ובהנסמן בהנ\"ל. ש\"א נ, א."],["44","43","<b>חשמל העליון</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תצד ואילך ושם נסמן. שם ע' תצז. תו\"ח ויצא קעח, א. לקמן ח, א. פ' בשלח קנח, ב. קעט, ג. קצ, ד. ויקהל תה, ד. תכ, ב."],["45","44","<b>שישת חשך סתרו</b>: תהלים יח, יב."],["46","45","<b>טעמי</b>: אבטייא: ע\"י. הזחיח: בטעמי."],["47","47","<b>לפום צערא אגרא</b>: אבות ספ\"ה. ולפי גי' אדה\"ז בסידורו מכ\"א."],["48","46","<b>דלפ\"ע. . אור גדול. . נתארך זה הגלות ביותר</b>: ראה גם לקמן פ' וארא סג, ד. מאמרי אדה\"א הנחות תקע\"ז ע' צו. וש\"נ."],["49","48","<b>ביום ההוא אסתיר פני</b>: וילך לא, יח [בהיפך הסדר — ראה גם לקמן פ' בשלח קפא, א. שה\"א ד, א. שע\"ת קיד, א. וראה גם תו\"ח ח\"ש קכז, ב הערה 20]."]]],[2300540158,"בגלותא אסתלק לעילא לעילא<sup data-n=\"50\">49</sup> כו' כמו אלכה אשובה אל מקומי<sup data-n=\"51\">50</sup> כו', וממילא מובן מזה דכל שהעלי' למקום גבוה ונעלה ביותר משם דוקא יהי' הגילוי אור, ומפני זה הי' ההעלם וההסתר בתחלה בזמן רב יותר כדי שיהי' העילוי אח\"כ במעלה ומדרגה עליונה יותר כו' וד\"ל.\n[ג] <b>והנה</b> יש להבין תחלה ענין מהות הגלות מהו, דהנה כתיב וימררו את חייהם<sup data-n=\"52\">51</sup> בעבודה קשה בחו\"ל ובכל עבודה בשדה כו', דודאי אין מקרא יוצא מידי פשוטו<sup data-n=\"53\">52</sup>, ועכ\"ז התורה נצחי' היא ומרמז גם על הגלות ברוחניות שזהו עיקר הגלות והוא שנק' גלות השכינה כמ\"ש ליעקב אנכי ארד עמך כו' וכך [הוא] בכל גלות כמא' גלו לאדום שכינה עמהם<sup data-n=\"54\">53</sup> כו' כידוע, וזהו שא' בזהר ע\"פ זה דוימררו את חייהם<sup data-n=\"55\">54</sup> שזהו חייהם דכנ\"י לעילא שהוא בחי' המל'<sup data-n=\"56\">55</sup> הנק' שכינה<sup data-n=\"57\">56</sup> כו'. וביאור זה ידוע דודאי לכאורה אין שייכות לומר ענין גלות גשמי באור האלקי שנק' שכינה ואפי' גלות רוחני בבחי' אלקי' מאחר שבחי' מדה זו דמל' שנק' שכינה הוא מקור כל העולמות שמחי' אותם מאין ליש כידוע, א\"כ איך שייך <span data-k=\"pg\">ב</span> ּ לשון גלות לאדון ביד עבדו וכה\"ג, אלא מה שמתלבש אור האלקי בלבוש שק שהוא בחי' הטבע (דאלקי' גימ' הטבע<sup data-n=\"58\">57</sup> ) והולך האור ושפע האלקי דרך הממוצעי' שהן המזלות וכה\"ג, וכח האלקי עצמו מוסתר ונעלם וכמ\"ש אתה אל מסתתר<sup data-n=\"59\">59</sup>, זהו<sup data-n=\"60\">58</sup> שנק' גלות השכינה וכמו אלביש שמים קדרות<sup data-n=\"61\">60</sup> כמ\"ש<sup data-n=\"62\">61</sup> במ\"א), (וראי' ממה שא' אותותינו לא ראינו<sup data-n=\"63\">62</sup> דקאי זה בזמן הגלות השכינה בע\"ש דנוגה שאין אותות ומופתים בהיפוך הטבע בהתגלות לראי' העין כמו שהי' כבר לעולמי' ביצ\"מ וקי\"ס וגם במדבר ובנביאי' כו', רק כל הנסים<sup data-n=\"64\">63</sup> ואותות<sup data-n=\"65\">64</sup> מתלבשי' בדרכי הטבע כמו נס דחנוכה ופורים כידוע). וכך הוא ענין הגלות בפרט בנש\"י במה שהן משועבדים בכל",[["50","49","<b>דקוב\"ה בגלותא אסתלק לעילא לעילא</b>: נסמן לקמן לט, א."],["51","50","<b>אלכה אשובה </b>[דהיז: ואשובה]<b> אל מקומי</b>: נסמן לקמן שם."],["52","51","<b>וימררו את חייהם</b>: שמות א, יד."],["53","52","<b>אין מקרא יוצא מידי פשוטו</b>: שבת סג, א."],["54","53","<b>גלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תלה. נ\"ך ע' פח. שע\"ת קיג, ד. קלו, ב. תו\"ח לך צג, א."],["55","54","<b>דוימררו את חייהם</b>: ראה ת\"ז תכ\"א מט, סע\"ב. מאמרי אדה\"א ויקרא ח\"א ע' עא. נ\"ך ע' תכח. תו\"ח נח ס, א."],["56","55","<b>דכנ\"י. . המל'</b>: ראה זהר בלק קצז, א."],["57","56","<b>המל' הנק' שכינה</b>: ראה זהר (רע\"מ) תצא רפא, ב. תניא רפנ\"ב. אגה\"ק סכ\"ה (קלט, א). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשלט ובהנסמן במ\"מ לשם."],["58","57","<b>דאלקי' גימ' הטבע</b>: נסמן לקמן לח, א."],["59","59","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["60","58","<b>והולך. . זהו</b>: יד: (והולך. . ז: (זהו. וראה לקמן הערה 61. כה: כבפנים."],["61","60","<b>אלביש שמים קדרות</b>: ישעי' נ, ג. ראה סידור שער המילה קמה, ג. לקמן יט, ג. ל, ד. לט, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתצו. וש\"נ."],["62","61","<b>כמ\"ש</b>: חיז: ((ו)כמ\"ש. וראה לעיל הערה 58. כה: כבפנים."],["63","62","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["64","63","<b>הנסים. . בדרכי הטבע. . דחנוכה ופורים</b>: ראה גם שה\"א ל, א."],["65","64","<b>ואותות</b>: דחיז: ניתוסף: ומופתים. יח: כבפנים."]]],[2300540195,"נפשם וגופם בדרכי הטבע האנושית כמו בטרדת הפרנסה<sup data-n=\"66\">66</sup> שמפרנסי' א\"ע ביגיעה גדולה בטרדות הלב והמוח בהתחכמות ותחבולות הכל בבטחון על הטבע<sup data-n=\"67\">65</sup> ובנפשם יביאו לחמם<sup data-n=\"68\">67</sup> עד מיצוי הנפש ממש כי כלה ביגון ואנחה כל ימי [חיי]הם ע\"ד טרדתם הקשה שמונעי' אותם מעבודת ה' בשמחה כו' מחמת צוק העתים בלחץ וד[ו]חק של הפרנסה עד שתעל שועתם אל ה' מן העבודה<sup data-n=\"69\">68</sup> הקשה כו' שזהו ממש כעובדי' עבודה קשה בחו\"ל לשונאיהם כו' עד שתקצר רוחם בעמלם ויגיעתם ולא ימצאו מרגוע לנפשם האלקי' בתורה ועבודה האלקי' כמו שהי' בגלות מצרים שלא שמעו למשה<sup data-n=\"70\">69</sup> מקוצר רוח ועבודה קשה כו', ולפי שבאמת אין מזל לישראל<sup data-n=\"71\">70</sup> כי ה' חלקם המשפיע להם בגשמיות בפרנסתם כמו ברוחניו' בנשמתם כידוע, לזה<sup data-n=\"72\">71</sup> הטעם נק' טרדת הפרנסה בשם גלות השכינה בפרט מצד בחי' הסתר אלקות שהסתיר פניו מהם ושולח להם שפע חיותם הגשמי' ע\"י דרכי הטבע שעובדי' בזה עבודה קשה כמו בחו\"ל כו'. משא\"כ בא\"י הי' הולך אור ושפע ברכה בכל אשר יעשו בבית ובשדה מאת ה' מן השמים בהשגחה אלקי' ממש שלא ע\"י ממוצעי' דטבע הנק' לבוש שק<sup data-n=\"73\">72</sup> ולכך הי' איש תחת גפנו<sup data-n=\"74\">73</sup> כו' ולא היו טרודי' כלל במיצוי הנפש רק על ה' בטחו שישלח ברכתו בארץ כו' כידוע וכמ\"ש וברכך<sup data-n=\"75\">74</sup> ה' אלקיך בכל אשר תעשה שלא היו צריכי' רק לעשות בחי' כלי לבד שישכון בזה הברכה כו', כענין יגיע כפיך<sup data-n=\"76\">75</sup> כי תאכל אשריך בעוה\"ז כו' רק יגיע כפיו במעשה בלבד ולא בפנימי' הלב והמוח כלל, משא\"כ בגלות שכל פנימית הלב והמוח טרוד בכל עומק תחבולות למצוא טרף לנפשם שזהו לילך לפי אופן הצלחת הטבע לבד שע\"ז א' כי לא לחכמים לחם<sup data-n=\"77\">76</sup> כידוע שזהו החכמים בעיניהם לומר כוחי ועוצם ידי<sup data-n=\"78\">77</sup> וחכמתי עמדה לי<sup data-n=\"79\">78</sup> כו' שעושה עיקר טפל וטפל עיקר, כי הצלחת [ה]טבע במזלות אינו רק כגרזן ביד החוצב<sup data-n=\"80\">79</sup> כו' ויהופכו מטוב לרע ומרע לטוב בשינוי הרצון העליון כמו שא' עת לכל חפץ<sup data-n=\"81\">80</sup> כו' ומשנה עתים ומחליף ומסדר כו' כרצונו<sup data-n=\"82\">81</sup> דוקא, ולכך גזר[ו] או' דישראל שבחו\"ל דוקא כמו עובדי ע\"ז בטהרה<sup data-n=\"83\">82</sup> כו' מטעם הנ\"ל, וכמ\"ש אותי עזבו מקור מ\"ח לחצוב להם בורות<sup data-n=\"84\">83</sup> נשברים כו' (אבל בא\"י הי' השכינה שורה בגילוי גם בגשמיות כמו ברוחניות",[["66","66","<b>בטרדת הפרנסה</b>: ראה גם שה\"א א, א ובהערה 7. תו\"ח נח נח, ד ובהערה 6."],["67","65","<b>האנושית. . הטבע</b>: י: ליתא. וכנראה שנשמט מפני תיבות הדומות: הטבע. . הטבע."],["68","67","<b>ובנפשם יביאו לחמם</b>: ע\"פ פיוט (לימים נוראים) כי כשמך."],["69","68","<b>שתעל שועתם. . העבודה</b>: ע\"פ שמות ב, כג."],["70","69","<b>שלא שמעו למשה</b>: וארא ו, ט."],["71","70","<b>אין מזל לישראל</b>: שבת קנו, א. ראה מאמרי אדה\"א דברים ח\"א ע' קסד. שמות ח\"ב ע' שפ. וש\"נ. הנחות תקע\"ז ע' ר."],["72","71","<b>לזה</b>: אח: ולזה."],["73","72","<b>לבוש שק</b>: ראה הנסמן לעיל בהערה 60."],["74","73","<b>איש תחת גפנו</b>: מלכים-א ה, ה."],["75","74","<b>וכמ\"ש </b>[יח: במ\"ש]<b> וברכך</b>: ראה גם לקמן לח, ג. וש\"נ."],["76","75","<b>יגיע כפיך</b>: תהלים קכח, ב. אבות פ\"ד מ\"א. ברכות ח, א. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קע. סה\"מ מלוקט ח\"ד ע' קמח. וש\"נ. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שסו. תקס\"ג ח\"ב ע' תשט. כתובים ח\"א ר\"ע ו. לקמן פ' ויקהל תיד, ב ואילך. תטו, ב."],["77","76","<b>כי לא לחכמים לחם</b>: קהלת ט, יא [בדילוג — ראה לקמן ג, ד. פ' ויקהל תטו, ב. מאמרי אדה\"א דברים ח\"ב ע' תקלג. שע\"ת י, ב ובהנסמן בהנ\"ל]. ראה שע\"ת ה, ד ואילך. וש\"נ. מאמרי אדה\"א דברים שם."],["78","77","<b>כוחי ועוצם ידי</b>: עקב ח, יז."],["79","78","<b>וחכמתי עמדה לי</b>: קהלת ב, ט."],["80","79","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. ישעי' י, טו."],["81","80","<b>עת לכל חפץ</b>: קהלת ג, יז."],["82","81","<b>ומשנה עתים. . כרצונו</b>: ברכות ק\"ש ערבית [ושם: ובתבונה משנה. בדילוג]."],["83","82","<b>דישראל שבחו\"ל. . בטהרה</b>: ראה גם לקמן לח, א. וש\"נ."],["84","83","<b>אותי עזבו. . בורות</b>: ירמי' ב, יג [ושם: בארות בארת]."]]],[2300540229,"בלי העלם כלל כו' ולכך היו גם ניסים בגילוי כו') ואז נא' <span data-k=\"pg\">6</span> ּ והחכמה תחי' בעלי'<sup data-n=\"85\">84</sup> כמ\"ש במ\"א<sup data-n=\"86\">85</sup>).\n[ד] <b>והנה</b> כמו שבחיי הגוף א' וימררו את חייהם בעבודה קשה כו' שזהו שיעבוד עול העבודה קשה בפרנסה שבנפשו יביא לחמו כמו שנתקלל אדה\"ר בזעת אפיך תאכל לחם<sup data-n=\"87\">86</sup> עד שמבלבל למוחו ולבו בלתי יוכל לעורר רוחו לעבודת ה' כלל, כך גם בחיי הנשמה האלקי' מררו את חייהם והוא במה שתקצר גם רוח האדם בעמלו שיעמול כו' אף בעמל תורה ועבודה שבלב בתפלה, כמו שאנו רואי' שגם בעבודה שבלב ומוח בק\"ש ותפלה לא יוכל להעמיק דעתו ולבו בהשגת אלקות ביחו\"ע ויחו\"ת<sup data-n=\"88\">87</sup>, ואף שמשיג ומבין ונתאמת אצלו במוח בינה איך שהוא ית' עיקרא ושרשא דכ\"ע<sup data-n=\"89\">88</sup> ומהוה מאין ליש תמיד וכה\"ג אינו מתפעל באוי\"ר שבלב כלל כאלו רחוק הדבר ממנו לגמרי רק בחיצוניות וקרירות מן השפה ולחוץ יכבד בפסוד\"ז בשבחו ש\"מ ולבו רחוק<sup data-n=\"90\">89</sup> כו', שזהו שנק' בכלל טמטום הלב<sup data-n=\"91\">90</sup> וטמטום המוח<sup data-n=\"92\">91</sup> באלקות לגמרי עד שכמת יחשב במיתה רוחני'. וגם מה שמייגע עצמו בעבודה האלקי' תכבד עליו העבודה ותקצר רוחו האלקי' בה כי אינו מוצא בנפשו טעם וחיות בהתפעלות אלקו' כלל, ולא עוד אלא גם בהתחכמו' ותחבולות ימצא לו דרך להחיות נפשו האלקי' באיזה השגה בגדולת ה' ביגיעת המוח והלב, הנה מיד יבלבלו אותו מ\"ז מטרידי' את לבו בהבלי עוה\"ז או מהרהורי' דגופני' ויתערב הטוב ברע ורע בטוב ומאור נעשה חושך וחשך נעשה אור כו' מצד תערובות שקר באמת ואמת בשקר עד שנפשו מליאה עכרורי' מלבושי' צואים ולא תוכל להטהר בעקירת כל רצון זר ולהיות בר לבב כלל, רק בראותו בנפשו שנתרחק מאור האלקי לגמרי ולרע ושקר נמשך בכל מיני תערובות רע ואע\"פ שמייגע נפשו אינו מוצא שום הארה אלקי' בלב ומוח באמת כלל אזי יבא לכלל מרירות בנפשו מאד ותעל צעקתו מתוך עוצם מרירות גדולה על נפשו, והוא שנק' עבודה קשה במרירות רוחניות כענין מ\"ת בוכין<sup data-n=\"93\">92</sup> אנן בעינן כו'. וכל זה נכלל במ\"ש וימררו את חייהם דכנ\"י שהוא חיי הנשמות, שהנשמות עצמן הן במרירות מגודל הריחוק ממקורם",[["85","84","<b>והחכמה תחי' בעלי'</b>: קהלת ז, יב [ושם: החכמה. ראה לקמן פ' בא קה, א. קלב, ד. בשלח קמו, ב. ד. יתרו רעא, א. ויקהל שצט, א. תטו, ב. מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. שע\"ת סח, א. ובהערה 1]. ראה שע\"ת ה, ד. וש\"נ."],["86","85","<b>במ\"א)</b>: יזיח: במ\"א. כה: כבפנים."],["87","86","<b>בזעת אפיך תאכל לחם</b>: בראשית ג, יט."],["88","87","<b>ביחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["89","88","<b>עיקרא ושרשא דכ\"ע</b>: זהר בהקדמה יא, ב."],["90","89","<b>ולבו רחוק</b>: ישעי' כט, יג."],["91","90","<b>טמטום הלב</b>: ראה יומא לט, א. בחיי משפטים כג, יט. לקמן פ' תצוה שסח, ד. מאמרי אדה\"א שמות ח\"ב ע' תקס ואילך. וש\"נ. תו\"ח מקץ ריג, ב ובהערה 37. שע\"ת ג, סע\"ג ואילך. סג, ב. פב, ד. ד\"ה לפיכך נק' הראשונים סופרים תשט\"ז (סה\"מ תשט\"ז ע' 477 ואילך)."],["92","91","<b>וטמטום המוח</b>: ראה גם לקמן פ' תצוה שסח, ד. ויקהל תט, רע\"ג. שע\"ת שם. דרך חיים יח, ג. כ, א. סה\"מ תשט\"ז שם ע' 479 ואילך."],["93","92","<b>מ\"ת בוכין</b>: ראה ת\"ז ת\"ה (יט, ב). הנסמן במאמרי אדה\"א בראשית ע' קג. שמות ח\"א ריש ע' לו."]]],[2300540261,"מקור כל חיי הנשמות שצועקי' במר נפשם לבלתי ידח ממנו נדח<sup data-n=\"94\">93</sup> כו'. וזהו שנק' גלות השכינה בפרט והוא כל ניצוץ אלקי בפרט שנתמלא עכרורי' ותערובות טו\"ר מחומר הגוף עד שכמת יחשב בנשמ' שבמוח ורוח בלב (וזהו כמו הגרעין הזרוע בארץ שנרקב<sup data-n=\"95\">94</sup> והי' לעפר שיש בו ב' מיני רקבון, א' בחומר שהוא גשם החטה שכלה בעפר והוא המרירו' גשמי' מצוק הדחק בפרנסה וביטושי' גשמיי', והב' רקבון בצורה שזהו מרירות דנה\"א שהוא רוחני). וכל זה אינו בא רק מצד חטא עה\"ד טו\"ר שנתערב טוב ברע<sup data-n=\"96\">95</sup> ורע בטוב בכל חלקי העולם גם בדצח\"מ ולזאת נתקלל אדם על אדמתו שקוץ ודרדר תצמיח כו' בעצבון תאכלנה<sup data-n=\"97\">96</sup> בזיעת אפיך כו' לברר בזה העוצב וזיע' אפו הפסולת מן האוכל שהוא הרע מן הטוב כמו שמלבני' ומבררי' במצרף לכסף וכור לזהב<sup data-n=\"98\">97</sup> שע\"י האש שבמצרף מבלבל לטו\"ר ועי\"ז יובדל הפסולת דכסף מן הנקי עד שיצא הנקי בלי תערובות רע ופסולת כלל וכלל, והוא ענין בירור דפת בל\"ט מלאכות<sup data-n=\"99\">99</sup> חורש וזורע<sup data-n=\"100\">*100</sup> עד שלש ואופה וכן בבגד ללבוש<sup data-n=\"101\">98</sup> אורג וטוה כו'. וכך הוא בפרנסה שהוא חסד וברכה אלקי' אבל זהו כמו בירור דלחם <span data-k=\"pg\">ג</span> ּ מן הארץ בזיעת אפו כו', וכך טרדות הפרנסה שמבלבל למוח ולב כנ\"ל עד שעי\"ז מתברר הטוב מן הרע ויתלבש בזה השפע וברכה כמו שאחר רקבון החטה בצו\"ח<sup data-n=\"102\">100</sup> שבה אז דוקא תצמיח בריבוי גדול לפי שנברר הפסולת שלה ונתברר כח הרוחניו' שבה ועלה לכח הצומח שבארץ בבחי' ביטול היש לאין כידוע שאז דוקא חוזר וצומח מאין ליש חטים חדשים לגמרי (ולא החטה הזרוע שכבר כלה לגמרי). וכן טפת הזרע שנקלטה אינו מוליד כ\"א באיבוד וכליון הגשמי' שלה)<sup data-n=\"103\">101</sup>, וכך הוא בחסד דפרנסה אינו נמשך מאין ליש כ\"א אחר הביטול דיש וגסות לאין ממש, והוא מה שבזיעת אפו יאכל כו' במיצוי הנפש שיאמר נואש לגמרי ותקצר רוחו בעמלו מבלבול המוח והלב ואינו מוצא מנוח לנפשו בהלך ילך ובכה<sup data-n=\"104\">102</sup> נושא כו' אח\"כ דוקא בא יבא כו'. כך הוא במרירות ורקבון הרוחניות דנה\"א בצר לה יותר מהריחוק העצום וכנ\"ל ותקצר רוח האדם בעבודה האלקי' עד שיאמר נואש בנפשו כו' אז יצמיח אור [ה]אלקי בנשמה זאת מאין ליש להוציא לאור כל בחי' הטוב הגנוז בה במוחי' ומדות שכליי' וטבעיי' ויוליד רצון ושכל ומדות באלקי' בתוס' אור גדול ומחודש בק\"ש ותפלה ותו\"מ כו' לפי שיצא מן הבירור דמצרף",[["94","93","<b>לבלתי ידח ממנו נדח</b>: שמואל-ב יד, יד."],["95","94","<b>הגרעין. . שנרקב</b>: ראה לקו\"א להה\"מ סק\"י (כד, ד). אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. הנסמן במ\"מ לשע\"ת סג, ב. לקמן ו, א. פ' בשלח קלג, ד. קפז, ג. תצוה שכ, ב. ויקהל תכד, ג. פקודי תמד, ב. תמז, ב. לקו\"ת פקודי ד, ד [ושם מציין לתו\"א ויקהל פט, ג]."],["96","95","<b>חטא עה\"ד טו\"ר שנתערב טוב ברע</b>: ראה גם לקמן מ, ב. וש\"נ."],["97","96","<b>שקוץ ודרדר. . בעצבון תאכלנה</b>: בראשית ג, יח. יז. ראה גם שע\"ת סה, ג."],["98","97","<b>במצרף לכסף וכור לזהב</b>: משלי יז, ג. כז, כא."],["99","99","<b>בל\"ט מלאכות</b>: ראה שבת עג, א."],["100","*100","<b>חורש וזורע</b>: ראה גם לקמן פ' ויקהל תיט, א. וש\"נ."],["101","98","<b>בירור דפת בל\"ט מלאכות. . בבגד ללבוש</b>: ראה עד\"ז תו\"ח בראשית לא, ד."],["102","100","<b>בצו\"ח</b>: בצורה וחומר."],["103","101","<b>שלה)</b>: גם בהכת\"י לא נסמן התחלת החצע\"ג."],["104","102","<b>בהלך ילך ובכה</b>: תהלים קכו, ו."]]],[2300540290,"במה שבא לכלל שפלות וענוה וביטול בנפשו לעלות במרירות עצומה רק לבלתי ידח כו' כנ\"ל, שזה עצמו הוא הגורם הצמיחה והעליי' מטעם הנ\"ל, וכמשל כור הברזל והמצרף שמבלבל הטוב ברע כו' ואח\"כ מתברר הטוב, כך הוא בחי' בר לבב שנעשה ע\"י מרירות אלקי' מן ההיפוך שהוא בחי' תערובות טו\"ר דמ\"ז המבלבלו' כו' שמחמת זה יצעק במר נפשו כנ\"ל, וכמו שא' שאין עומדין להתפלל<sup data-n=\"105\">103</sup> אלא מכובד ראש דוקא כידוע וד\"ל (והכל מטעם הנ\"ל בבירורי' דעה\"ד שצ\"ל בביטול היש לאין באו\"ח דוקא כו').\n[ה] <b>והנה</b> ע\"ד הנ\"ל במרירות דחיי הגוף וחיי הנשמה בעבודה שבתפלה שנק' עבודה קשה (ובחו\"ל זהו תיקון לדור הפלגה שעבדו בחו\"ל בחשק נפלא לבנות מגדל לעשות להם שם [ב]פירוד מאלקו' כידוע ומבואר במ\"א<sup data-n=\"106\">104</sup>, וזהו עכשיו שרודפי' בחשק נפלא אחר הבלי עוה\"ז לבנות בנין ושם בכל הון ועושר וגדולה ותאר<sup data-n=\"107\">105</sup> חמדת עוה\"ז ע\"כ לא תכבד העבודה במו\"מ בפיזור הנפש בכל טורח וטלטול הקשה כו', ואף שלא ימצאו ריוח לא תקצר רוחם בע[מ]לם כלל אדרבה יקבלו הכל באהבה וחשק מרוב חפצם להתגדל בהון ועושר, כמו מי שעובד בחשק לא ירגיש כלל טורח ועמל בעבודתו אף שגם הם יחוגו וינועו<sup data-n=\"108\">106</sup> בבלבול גדול לא יאמרו נואש ואדרבה בוטחי' על רב כחם וחכמתם כנ\"ל, והתיקון לזה אינו אלא ההיפוך מזה ממש והוא אשר מאד תכבד עליו עול ד\"א עד שימאס בחייו ויצעק לה' במר נפשו כנ\"ל), כך ממש יתפרש וימררו את חייהם במרירות ועוצב שבעמל תורה שנק' ג\"כ חייהם דכנ\"י שהוא כמו מקור חיי הנשמות ממש הנ\"ל דכמו שמרירות הרוחני' האלקי' בכל ניצוץ בפרט כנ\"ל, כך הוא בכללות נש\"י למעלה שנק' חייהם דכנ\"י למעלה דודאי גם השכינה בגלות עמהם בלחץ ודחק זה ברוחניו' וגשמיות דנשמה וגוף הנ\"ל כנ\"ל בענין התלבשות אלקו' בלבוש שק דנוגה כו'. וידוע בזהר דג' קשרי' הן<sup data-n=\"109\">107</sup> ישראל מתקשראן באוריי' ואוריי' בקוב\"ה כו', ויש ב' מדריגות בזה א' בשרש הנשמו' באותיות דתושב\"כ<sup data-n=\"110\">108</sup> (שנק' לחם <span data-k=\"pg\">8</span> ּ מן השמים כמשי\"ת) שהוא בבחי' קדש העליון דח\"ע הברורה מכבר<sup data-n=\"111\">109</sup> בתוה\"ק<sup data-n=\"112\">110</sup> כמ\"ש ואתא מרבבות קדש<sup data-n=\"113\">111</sup> והוא מ\"ש אז ראה ויספרה<sup data-n=\"114\">112</sup> כו' כידוע והן ס\"ר נש\"י שקשורי' בס\"ר אותיות דתושב\"כ<sup data-n=\"115\">113</sup> (וכמ\"ש",[["105","103","<b>שאין עומדין להתפלל</b>: ראה ברכות ל, ב."],["106","104","<b>תיקון לדור הפלגה. . במ\"א</b>: ראה לקמן פ' וארא פו, ג. בשלח רלא, א. ויקהל תיד, ג. מאמרי אדה\"א שמות ח\"א ע' כה. וש\"נ."],["107","105","<b>ותאר</b>: יזיח: תאוות."],["108","106","<b>יחוגו וינועו</b>: תהלים קז, כז."],["109","107","<b>דג' קשרי' הן</b>: ראה זהר אחרי עג, א. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"א ע' לט. וש\"נ. ח\"ג ע' תשעח ואילך וע' תשפג ואילך. הנחות תקע\"ז ע' שיח. לקמן פ' בשלח קפג, ג. תרומה שיד, א."],["110","108","<b>דתושב\"כ. . לחם מן השמים</b>: ראה סידור שער בהמ\"ז קז, ג. תו\"ח בראשית לג, ז. תולדות קסג, א. לקמן פ' בשלח ריא ב. ויקהל תטז, ד. תמ, ד."],["111","109","<b>דח\"ע הברורה מכבר בתוה\"ק</b>: ראה גם תו\"ח בראשית יד, ד ובהנסמן לשם. לקמן פ' בשלח קעג, ב ובהערה 442."],["112","110","<b>בתוה\"ק</b>: ראה עמק המלך (שער שעשועי המלך) ש\"א, פ\"ד (ג, א)."],["113","111","<b>ואתא מרבבות קדש</b>: ברכה לג, ב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תקכז. לקו\"ת ברכה צג, ג [בלקו\"ת מובא: ואתה אבל ראה שם שה\"ש ה, ב — ראה הנסמן במאמרי אדה\"א בראשית ע' כב]."],["114","112","<b>אז ראה ויספרה</b>: איוב כח, כז."],["115","113","<b>ס\"ר נש\"י. . דתושב\"כ</b>: ראה בא יב, לז. ז\"ח שה\"ש עד, ד. של\"ה מס' פסחים מצה עשירה קסג, ב. קסה, ב. תניא פל\"ז ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ."]]],[2300540318,"כאן ואלה שמות בנ\"י כו' את יעקב בחי' קול יעקב דתורה אור כו' וכמשי\"ת)<sup data-n=\"116\">114</sup>, והב' בתושבע\"פ (שנק' לחם מן הארץ<sup data-n=\"117\">115</sup> כמשי\"ת<sup data-n=\"118\">116</sup>) שהן ו\"ס משנה<sup data-n=\"119\">117</sup> שכוללי' ס' מסכתות<sup data-n=\"120\">118</sup>, וזהו ששים המה מלכות<sup data-n=\"121\">119</sup> כמשי\"ת<sup data-n=\"122\">120</sup> דמתני' מלכתא<sup data-n=\"123\">121</sup> וכ\"י בנ\"מ<sup data-n=\"124\">122</sup> כו', ולכך כמו שיתכן לומר וימררו חייהם דנש\"י למעלה בבחי' מל' שנק' שכינה כך ממש יתכן לומר שמררו חייהם דתורה דאוריי' וקוב\"ה כולא חד<sup data-n=\"125\">123</sup> כו' כי התורה בכלל נק' חייהם דנש\"י למעלה ולמטה וכמו שאו' ונשמח בד\"ת כי הם חיינו<sup data-n=\"126\">124</sup> כו' וכמ\"ש כי אמרתך חייתני<sup data-n=\"127\">125</sup>, ואו' למען תהי' תורת ה' בפיך<sup data-n=\"128\">126</sup>, כי הוא חייך<sup data-n=\"129\">127</sup> כו', כי על כל מוצא פי ה' דתורה דוקא יחיה האדם<sup data-n=\"130\">128</sup> שהיא הנשמה שהיא בצלם אדם העליון כידוע וד\"ל.\n<b>אך</b> הנה איך יתכן ענין המרירות שמררו לחייהם דאור תורה מאחר ששרש החכמה דתורה נמשך מלמעלה בבחי' אור כמ\"ש ותורה אור<sup data-n=\"131\">129</sup> ממש ומתאחדת במהו\"ע ית' כנ\"ל איך יתכן לומר בה ענין מרירות בעבודה קשה כו'. אמנם הנה א' בזהר ור\"מ ע\"פ זה דוימררו<sup data-n=\"132\">130</sup> את חייהם בעבודה קשה דא קושיא בחומר דא קל וחומר ובלבנים דא ליבון הלכתא ובכל עבודה בשדה דא ברייתא כו', וזהו מא' פלאי<sup data-n=\"133\">131</sup> דאיך יתכן לומר בעסק זה דתורה הנגלי' בפלפול בקושיות ותירוצי' כמו הויות דאביי ורבא<sup data-n=\"134\">132</sup> בתלמוד בבלי שלנו שנק' גלות בעבודה קשה בקושי' וקו\"ח כו' ולבינים ליבון הלכתא, דאדרבה זהו עיקר מצות ת\"ת לברר וללבן הדין והלכה לאמיתת' ע\"י עיון רב בפלפול עמוק בקושיות ותירוצי' הרבה כמו שא' בכ\"ד קושיות וכ\"ד פירוקי'<sup data-n=\"135\">133</sup> דממילא רווחא שמעתתא כו'. ומה שא' דבמחשכים הושיבני זה תלמוד בבלי<sup data-n=\"136\">134</sup> כו' דמשמע פשט הדבר שהוא כהולך בחושך ולא אור לפי שלא יוכלו לעמוד ע\"ד אמיתית הדין וההלכה מרוב הפלפול כו', זהו דוקא קודם שמתברר הדין לאמיתתו אבל לאחר גמר הפלפול ודאי יבא ע\"ד האמת ויוציא לאור כל",[["116","114","<b>וכמשי\"ת)</b>: כ\"ה ביז. בתו\"ח: וכמשי\"ת. כה: (וכמשי\"ת)."],["117","115","<b>בתושבע\"פ. . לחם מן הארץ</b>: נסמן בהערה 108."],["118","116","<b>כמשי\"ת)</b>: כ\"ה ביז. בתו\"ח: כמשי\"ת. כה: (כמשי\"ת)."],["119","117","<b>ו\"ס משנה</b>: ראה זהר בראשית מב, א. במדב\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. לקו\"ש בשלח (כרך יא) ע' 56 הערה 13."],["120","118","<b>ס' מסכתות</b>: ראה זהר (רע\"מ) פינחס רטז, א. לקמן יא, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שעח ובהנסמן במ\"מ לשם. תקס\"ח ח\"ב ע' תריט. תק\"ע ס\"ע ו ואילך (ובהנסמן בריש המאמר שם). מאמרי אדה\"א דברים ח\"ב ע' תד. וש\"נ. ס' השיחות תשמ\"ט ח\"א ע' 104 הערה 41. וראה גם לקמן פ' ויקהל שצ, ב. תמ, א."],["121","119","<b>ששים המה מלכות</b>: שה\"ש ו, ח."],["122","120","<b>כמשי\"ת</b>: יזיח: כמ\"ש."],["123","121","<b>דמתני' מלכתא</b>: ביצה כח, ב. ראה לקמן יא, א."],["124","122","<b>וכ\"י בנ\"מ</b>: וכל ישראל בני מלכים — שבת סז, א."],["125","123","<b>דאוריי' וקוב\"ה כולא חד</b>: מובא בתניא (פ\"ד ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חקת ע' תשס."],["126","124","<b>ונשמח. . חיינו</b>: ברכות ק\"ש (ערבית) בדילוג."],["127","125","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["128","126","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["129","127","<b>כי הוא חייך</b>: נצבים ל, כ."],["130","128","<b>כי על. . יחיה האדם</b>: עקב ח, ג. ראה מאמרי אדה\"א בראשית ע' קט."],["131","129","<b>ותורה אור</b>: משלי ו, כג."],["132","130","<b>בזהר ור\"מ. . דוימררו</b>: ראה זהר בראשית כז, א. רע\"מ בהעלותך קנג, א. פינחס רכט, ב."],["133","131","<b>וזהו מא' פלאי</b>: השוה מאמרי אדה\"א נ\"ך ס\"ע תכח."],["134","132","<b>הויות דאביי ורבא</b>: סוכה כח, א."],["135","133","<b>בכ\"ד קושיות וכ\"ד פירוקי'</b>: ראה ב\"מ פד, סע\"א. תו\"ח נח עב, א ובהערה 15. שע\"ת קלו, ד. ש\"א כב, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רצט."],["136","134","<b>דבמחשכים </b>[חטז: במחשכים]<b> הושיבני זה תלמוד בבלי</b>: איכה ג, ו. ראה סנהדרין כד, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' קו."]]],[2300540343,"דבר על בוריו ונק' ליבון הלכתא שמלבנו מכל פסולת וטעות וקושי' כו'. וגם א\"א לומר הטעם בזה מצד ריבוי המחלוקת שנמצא בדורות האחרוני' שאחר הזוגות<sup data-n=\"137\">135</sup>, כב\"ש וב\"ה ואחריהם שהללו אוסרי' והללו מתירים<sup data-n=\"138\">136</sup>, והכל במחלוקת שנויה לכך אין בידינו הלכה ברורה<sup data-n=\"139\">137</sup> במקום א', ולזאת צריך לברר וללבן הדברי' להעמיד לכל א' על מקומו באופני' פרטיי' ולא יהי' שום מחלוקת כמו ורמינהי כו' ומתרץ ל\"ק כו' (וזהו<sup data-n=\"140\">138</sup> סלסלה<sup data-n=\"141\">139</sup> כו' כמסלסל בשערות שמפריד הדיבוק והבלבול שבהן עד שיוצא כל א' בפ\"ע, כך ההלכות נק' נימין<sup data-n=\"142\">140</sup> ושערות כהילוך השפע המצומצם בחלל השערה כך נמשך מאור ח\"ע דתושב\"כ בדין והלכה זו, וזהו הלכה אותיות הכלה<sup data-n=\"143\">141</sup> שנק' נימין דמט' (וכמ\"ש במ\"א<sup data-n=\"144\">142</sup> ), עכ\"ז לא יתכן בזה לומר וימררו את חייהם בעבודה קשה בחו\"ל דגם שודאי עבודה קשה היא לברר וללבן הלכתא בקושי' וקו\"ח עד שיוציא הלכה ברורה בתכלית מכל סיג ופסולת כו'. מ\"מ מה שייך ענין המרירות בעבודה זו כי הרי זה[ו] עיקר מצות העיון ביגיעה [ב]תורה <span data-k=\"pg\">ד</span> ּ ונק' עמל תורה כידוע וכמ\"ש אשרי מי שעמלו בתו'<sup data-n=\"145\">143</sup> כו' (וכידוע<sup data-n=\"146\">144</sup> בשרש ענין הפלפול שנעשה זה ע\"י הכאת הסלע במטהו פעמיים<sup data-n=\"147\">145</sup> כו' שזהו המוציא לך מים<sup data-n=\"148\">146</sup> כו' כך מים דחכ' דתו' נמשך ע\"י הפלפול כו' (כמשי\"ת), ומה שייך זה לענין הגלות דוקא [דמשמע שבגלות דוקא] עיקר העסק בעבודה קשה זו בחו\"ל והלא תשבע\"פ כבר נמסרה למשה בסיני כמ\"ש תורה ציוה לנו משה<sup data-n=\"149\">147</sup> בע\"פ וכל מה שתלמיד ותיק עתיד לחדש<sup data-n=\"150\">148</sup> הכל ניתן למשה בסיני ומהו שיש בזה ענין המרירות לחייהם דכנ\"י.\n[ו] <b>אך</b> הנה ארז\"ל ג' נובלות הן<sup data-n=\"151\">149</sup> נובלות חש\"מ תורה ונובלות בינה שלמעלה שכינה<sup data-n=\"152\">150</sup> כו', ומבואר למעלה בענין ג' קשרי' וכו' דנש\"י בשרשם שנק' שכינה דזהו בחי'",[["137","135","<b>הזוגות</b>: ראה אבות פ\"א, מ\"ד ואילך."],["138","136","<b>שהללו אוסרי' והללו מתירים</b>: חגיגה ג, ב."],["139","137","<b>אין בידינו הלכה ברורה</b>: ראה שבת קלח, סע\"ב ואילך."],["140","138","<b>כו' (וזהו</b>: ב: וד\"ל) וזהו. ז: וד\"ל שזהו. כה: כבפנים — ולא נסמן סיום החצע\"ג."],["141","139","<b>סלסלה</b>: משלי ד, ח. ראה תו\"א מקץ לא, ד. מאמרי אדה\"ז כתובים ח\"ב ע' ק. מאמרי אדה\"א ויקרא ח\"א ע' קז. וש\"נ. קונטרסים ע' תקלג. וש\"נ."],["142","140","<b>ההלכות נק' נימין</b>: ראה ת\"ז תקונא שתיתאה קמד, ב. לקו\"ת שה\"ש מ, א בשם הזהר ובהנסמן במ\"מ לשם. שם ו, סע\"ג ואילך. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרכ. מאמרי אדה\"א בראשית ע' תקכו. וש\"נ. תו\"ח מקץ רכה, א. לקמן פ' משפטים רצא, ג."],["143","141","<b>הלכה אותיות הכלה</b>: פע\"ח (שער הנהגת הלימוד) שי\"ז. ראה לקמן פ' משפטים רצ, ד. רצא, ג. תרומה שיח, ב. מאמרי אדה\"א ויקרא ח\"א ע' קיא. וש\"נ. תו\"ח בראשית לה, ד ובהערה 61. שה\"א לב, א ובהערה 1."],["144","142","<b>וכמ\"ש במ\"א</b>: ראה הנסמן בהערות שלפנ\"ז."],["145","143","<b>אשרי מי שעמלו בתו'</b>: ראה ברכות יז, א."],["146","144","<b>(וכידוע</b>: יח: וכידוע."],["147","145","<b>הפלפול. . הכאת הסלע. . פעמיים</b>: ראה ת\"ז תכ\"א (מד, א). מאמרי אדה\"א בראשית ע' קנ־ ויקרא ח\"א ע' קיב־ דרושי חתונה ח\"ב ע' תקכג ובהנסמן בהנ\"ל. שע\"ת קלו, ד."],["148","146","<b>המוציא לך מים</b>: עקב ח, טו."],["149","147","<b>תורה ציוה לנו משה</b>: ברכה לג, ד."],["150","148","<b>וכל מה. . לחדש</b>: ראה מגילה יט, ב. ירושלמי פאה פ\"ב, ה\"ד. הנסמן בלקו\"ש דברים (כרך ד) ע' 1088־ ח\"י אלול (כרך יט) ע' 252."],["151","149","<b>ג' נובלות הן</b>: ראה ב\"ר פי\"ז, ה. פמ\"ד, יז."],["152","150","<b>ונובלות בינה שלמעלה שכינה</b>: כ\"ה בכ\"מ, ומהם: ע\"ח שער הכללים ספ\"א: שארז\"ל. יונת אלם פכ\"ו. מאמרי אדה\"א ויקרא ח\"ב ע' תתסו. וש\"נ. תו\"ח לך פב, ג ובהערה 20. לקמן פ' בא קג, ב. יתרו רסז, א."]]],[2300540366,"נובלות דבינה ש\"מ בחי' ה\"א<sup data-n=\"153\">151</sup> עילאה כו' כך התורה הנגלית לנו נק' נובלות דחש\"מ כשבאה למטה בבחי' אותיות דתושב\"כ ושבע\"פ לברר לעה\"ד טו\"ר בפו\"מ כידוע וכמו שמבואר למעלה בכללות ענין גלות השכינה למטה, ובפרט בכל ניצוץ בחיי נשמתו וחיי גופו בעול פרנסה, כך יובן עד\"ז ממש בענין התורה שהיא ג\"כ בגלות וכמא' שהתורה חוגרת שק<sup data-n=\"154\">152</sup> כו' והוא בחי' לבוש שק דק\"נ שמדבר בזמן הגלות דוקא כי בזמן בהמ\"ק כמו ששכינה שורה בהיכל ק\"ק כך אור דתורה הי' גנוז בארון (ולוחות וירדה להיות בב' מדרגות<sup data-n=\"155\">153</sup> בבחי' אור המאיר שהוא במנורה להאיר לנש\"י בשרשם שנק' נרות הוי'<sup data-n=\"156\">154</sup> בכלל שהן ששה קנ[י] המנורה שמקבלי' האור ממול פני<sup data-n=\"157\">155</sup> כו' שהן ו\"ס משנה<sup data-n=\"158\">156</sup> כמ\"ש במ\"א, והב' בבחי' מזון ולחם בלחם הפנים על השולחן שלפני ה' כו', והן ב' מדרגות דתושב\"כ שנק' אור ותושבע\"פ שנק' מזון ולחם מן הארץ כנ\"ל). והנה מבואר למעלה בכל פרטי אופני ענין הגלו' דשכינה והנשמ' אלקי' בפרט שזהו מה שכח האלקי מתלבש בלבוש הטבע שמעורב טו\"ר ומתנהג הכל ע\"י בחי' לבוש שק דנוגה, וכן בנשמה שמתלבשת בשעבוד פרנסה בתחבולות ויגיעה במיצוי הנפש ובוטח על חכמתו וכח עוצם ידו כו' ואינו מוצא ריוח כי לא לחכמים לחם כו'.\n<b>וכמו\"כ</b> יובן בענין מה שהתורה חוגרת שק בהיותה בגלות דהיינו מה שנמשך ומתלבש מאור דח\"ע דתושב\"כ (שנק' נובלות דחש\"מ כנ\"ל) בעיון דפלפול שבא בדרך השכל האנושי' להסתיר אור האמת בריבוי קושיו' ובלבולי' שכל קושיא אינו אלא שמסתיר ומעלים אור האמת, כי הקושי' שעומד ומקשה על הדין האמת שיהי' להיפוך מצד סברא ושכל שאינו אמת, כמו על השחיטה מן הצואר שאו' דאימא מעורף<sup data-n=\"159\">157</sup> וכה\"ג בכל דיני המצות, דקושיא ענין קושי כסלע שמקשה הדבר ומעלימו כמסך בעובו שלא יגלה אור האמת (וכמ\"ש בר\"מ דכל קושיא מסט' דקליפה<sup data-n=\"160\">158</sup> כו', והאריז\"ל הי' מקשה עד שמזיע<sup data-n=\"161\">159</sup> כדי לשבר ולהכניע הקליפו' כידוע). ויש קושיות רבות שבאי' בבירור שמתוכם יובן דוקא אור האמת אחר שיתורצו והוא עיקר ענין הפלפול, כמו המוציא מים מקושי הסלע שאחר ריבוי הקושיות והעלמות דוקא אז יובן שרש אמיתי' הסברא לאסוקי שמעתתא אליבא דהלכתא<sup data-n=\"162\">160</sup> (כמו כ\"ד קושי' כו' דרווחא שמעתתא כו' וכמו שא' ר\"י לראב\"פ<sup data-n=\"163\">161</sup> שהי' ר\"ל חריף ומקשה",[["153","151","<b>דבינה. . ה\"א</b>: ראה פרדס (שער האותיות) שכ\"ז, פ\"ח. מאמרי אדה\"א בראשית ע' רלג. וש\"נ."],["154","152","<b>שהתורה חוגרת שק</b>: ראה סנהדרין קא, א. שע\"ת קלו, ב ואילך."],["155","153","<b>בב' מדרגות. . במנורה. . בלחם הפנים</b>: ראה גם לקמן פ' ויקהל תמ, א ואילך. הנסמן בהערה 156."],["156","154","<b>לנש\"י. . נרות הוי'</b>: ראה משלי כ, כז."],["157","155","<b>ששה קנ[י]. . ממול פני</b>: ראה בהעלותך ח, ב."],["158","156","<b>ששה קנ[י] המנורה. . ו\"ס משנה</b>: ראה ש\"ך תרומה כה, לא (ד\"ה ועוד יכולין). מאמרי אדה\"ז תקס\"ה ח\"א ע' שמב וריש ע' שמח. תו\"א ויקהל פח, סע\"ב. לקמן פ' ויקהל תמ, ב."],["159","157","<b>דאימא מעורף</b>: ראה חולין כז, ב. ב\"ר רפמ\"ד."],["160","158","<b>דכל קושיא מסט' דקליפה</b>: ראה זהר (רע\"מ) נשא קכד, ב. אגה\"ק סכ\"ו."],["161","159","<b>והאריז\"ל. . שמזיע</b>: ראה שו\"ע האריז\"ל כוונת תלמוד תורה ס\"א. ש\"א כד,א. מאמרי אדה\"א ויקרא ח\"ב ע' תתמג־ דברים ח\"ד ע' א'תעד ובהנסמן בהנ\"ל. לקמן ד, ב."],["162","160","<b>לאסוקי שמעתתא אליבא דהלכתא</b>: יומא כו, א."],["163","161","<b>שא' ר\"י לראב\"פ</b>: ב\"מ פד, א."]]],[2300540387,"לו כו'). אבל יש הרבה קושיות שמסתירי' ומבלבלי' אור האמת שנק' סיג ופסולת ממש והוא כמו הטעות והשקר בסברות כוזבות בשכל <span data-k=\"pg\">10</span> ּ האנושי מצד בחי' תערובות רע ופסולת, וזהו מי שחריף ומקשה ומפלפל פלפול של הבל ואינו מסיק להלכה ברורה כלל אדרבה יצא לחוץ מאור האמת לשקר ולטעות כמו תלמידי' שלא שמשו כ\"צ שרבו מחלוקת בישראל<sup data-n=\"164\">162</sup> לטהר את הטמא ולטמא כו' וכמו שהי' יודע לטהר את השרץ<sup data-n=\"165\">163</sup> כו' (וכמו<sup data-n=\"166\">164</sup> שא' בדואג ואחיתופל דבעו<sup data-n=\"167\">165</sup> ד' מאות בעיי כו' שלא ידעו לאסוקי שמעתא<sup data-n=\"168\">166</sup> להלכה ברורה כלל אלא להיפוך ולטעות ושקר נוטה כל הפלפול, וזהו מצד שלומדי' של\"ש רק להתגדל ולקנות שם כו' או להתפרנס כו' שבוטחי' בחכמתם ועוצם חריפותם בטבע כח השכל האנושי שהוא כזב ושקר והבל מחמת תערובות רע ופסולת הרבה כו', והוא הסימן שאין בהם שפלות וביטול כלל רק גסות הרוח שמתנשאי' בחכמתם ויפרדו מאור אלקי' שבח\"ע דתורה שאינו רק בבחי' מה ואין בשפלות בלי הרגשה בעצמם כלל, וע\"כ עליהם א' כי לא לחכמים לחם וחכמים המה להרע<sup data-n=\"169\">167</sup> כו' שלחם דתורה אמיתי' לא ימצא בהם וכמו שא' לא תמצאנה בגסי הרוח<sup data-n=\"170\">168</sup> שגס לבם בחכמתם לעמוד ע\"ד אף שמנגד לאמת, כי א\"א להם לכוין להלכה אמיתי' מטעם הנ\"ל דקושיו' ופלפול שלהם נגד אור האמת להסתיר ולהעלים כי ילכו בדרך עקלתון לנטות מקו היושר דאמת דח\"ע כו' וד\"ל (וזהו<sup data-n=\"171\">169</sup> שא' בעוסקי' של\"ש ממש דלמשמאילי' בה סמא דמותא<sup data-n=\"172\">170</sup> לנשמתם, מלבד שאין אור דתורה שלהם מחי' לנשמתם אלא שממית אותם ומפילם משרשם למעלה כמו ונר רשעים ידעך<sup data-n=\"173\">171</sup> כו', לפי שמחמת לבוש זר דרע ופסולת שבהם שמלבישי' לאור דתורה עד שנוטי' מדרך האמת כנ\"ל לפי שעוסקי' בחלק הרע שבנה\"ט נעשה להם למות ברוחניו', דמות ורע שבהם עצמם לפי שלא יסבלנו אור האמת דתורה ובחי' תערובו' הפסולת שהמשיכו בתורה תמותת אותם, כידוע במשל הרפואה שמחי' לראוי' לה וממית למי שאינו ראוי לה כו' (וכמו<sup data-n=\"174\">172</sup> הפסולת שבמאכל לחם שמזיק וממית לגוף והמובחר נעשה חיות ומזון לנפש וכך ותורתך בתוך מעי<sup data-n=\"175\">173</sup> שנדחה הפסולת לחוץ והמובחר עולה ללב ומוח כו', וכמו החטה הזרוע בארץ שתרקב הפסולת וגם הרוחניו' שלה עולה בבירור עד שתצמיח עי\"ז חטים חדשי' כנ\"ל<sup data-n=\"176\">174</sup> שזהו עיקר ענין הבירור וכמצרף לכסף שמברר הסיגי' עד שיצא הנקי כו', כך הוא ענין הפלפול בעיון שמברר כל סיג ופסולת דקושיות המעלימו' כנ\"ל.",[["164","162","<b>תלמידי'. . מחלוקת בישראל</b>: ראה סוטה מז, ב."],["165","163","<b>שהי' יודע לטהר את השרץ</b>: עירובין יג, ב."],["166","164","<b>(וכמו</b>: כה: לא נסמן סיום החצע\"ג."],["167","165","<b>בדואג ואחיתופל דבעו</b>: סנהדרין קו, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקפח (נוסח א')."],["168","166","<b>בדואג ואחיתופל. . שלא ידעו לאסוקי שמעתא</b>: סנהדרין שם."],["169","167","<b>וחכמים המה להרע</b>: ירמי' ד, כב."],["170","168","<b>לא תמצאנה בגסי הרוח</b>: ראה עירובין נה, א."],["171","169","<b>(וזהו</b>: סיום החצע\"ג לא נסמן בהכת\"י."],["172","170","<b>דלמשמאילי' בה סמא דמותא</b>: ראה שבת פח, ב. וברש\"י שם סג, א ד\"ה למשמאילין. לקמן פ' בא קכה, א. בשלח ריא, סע\"ב. תו\"ח מקץ רכח, ג."],["173","171","<b>ונר רשעים ידעך</b>: משלי יג, ט. יז: נר — איוב כא, יז. ראה ש\"א לז, א."],["174","172","<b>(וכמו</b>: בזחיטויז: וכמו."],["175","173","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["176","174","<b>כנ\"ל</b>: פ\"ד."]]],[2300540407,"<b>ונמצא</b> מובן דיש ב' מיני בירורי' שהן ב' הפכי' דהיינו שיש בזה בירור מקצה לקצה דכל קושיא וקושיא שיכול עי\"ז לבא לבירור האמיתי זהו הבירור השלם שיוצא אור האמת מתוך היפוכו דוקא כמו פלפול דתלמוד בהויות דאביי ורבא וכה\"ג שמלבן ההלכות דוקא, אבל מה שיש קושיות שהן מצד הפסולת ממש שהוא הטעות ושקר ממש כמו פלפול של הבל בעוסקי' של\"ש דע\"ז א' כי לא לחכמים בעיניהם לחם דתו' כו', היינו השקר המנגד לאמת שבא מסט' דקליפה כנ\"ל, וזהו כמו קוץ ודרדר שתצמיח הארץ וכפסולת החטה שתרקב כו'. וזהו עיקר ענין עמל תורה דעמל זה הוא היגיעה בפלפול אמיתי שהוא רק בבירור האמת מן השקר וטעות שזהו כבורר אוכל מפסולת וטוב מרע ממש עד שילבן ההלכה בתכלית שזהו <span data-k=\"pg\">ה</span> ּ כעובד אדמה שחורש וזורע וקוצר כו' או שטוחן המאכל בשיני' ומתברר במעיו הטוב מן הרע כנ\"ל שנק' בירור אמיתי בעה\"ד טו\"ר לאסוקי שמעתא אליבא דהלכתא דוקא כנ\"ל וד\"ל. ונמצא מובן מכ\"ז דעמל תורה הנ\"ל דומה לעמל תפלה ברוחניות כנ\"ל ולעמל מלאכה בגשמיות, דהנה כמו שמבואר למעלה בעבודה שבלב ומוח בתפלה שזהו עיקר הבירור בין טו\"ר אמת ושקר והפסולת הן המ\"ז וכה\"ג ותקצר רוחו בעמלו ביגיעת המוח והלב כי יתעלם ויסתיר לו חומר הגוף ואינו מוצא טעם עד שיאמר נואש בנפשו ויבא לכלל מרירות ברוחניות ע\"ד הריחוק כו' וע\"ד התערובו' הקשה שמבלבלו לגמרי כו', כך הוא בעסק התורה כשמייגע מוחו ולבו לדעת דין והלכה על בוריה וקשה לו קושיות וסתירות שמסתיר אור האמת וגם מתערב רע ופסולת מחלק הרע והגסות שבנפשו עד שילך בדרך חושך ולא אור כו' שאז תקצר רוחו בעמלו זה, והוא מה שהתורה חוגרת שק דק\"נ לפי שנהפך מאמת לשקר ומטוב לרע כו'. אך עכ\"ז גם בחושך יאיר אור להיות עומד ע\"ד האמת אחר הקושיא והיגיעה במיצוי הנפש שזהו כמו שא' אין אדם עומד ע\"ד הלכה עד שנכשל בה<sup data-n=\"177\">175</sup> כו', ואין התורה מתקיימת<sup data-n=\"178\">176</sup> אלא במי שממית עצמו עלי' כו', וכן אמר מיץ חלב כו' במי אתה מוצא חמאה של תורה במי שמציץ<sup data-n=\"179\">178</sup> חלב שינק משדי אמו<sup data-n=\"180\">177</sup> כו' שזהו ביטול היש לאין כרקבון הגרעין כנ\"ל שיצמיח שפע וברכה חדשה מאין ליש בריבוי גדול, כך בבחי' העמל דתורה לאחר היגיעה במיצוי הנפש בביטול כל עצמו לגמרי עד שמתייאש לגמרי אז יבא על אור האמת לחדש דברים רבים על אמיתתן ביתר מכפי מדת חכמתו בעצם. וזהו שא' עובד אדמתו ישבע לחם<sup data-n=\"181\">179</sup> דקאי בלחמה",[["177","175","<b>אין אדם. . שנכשל בה</b>: ראה גיטין מג, א."],["178","176","<b>ואין התורה מתקיימת</b>: ראה שבת פג, סע\"ב. שע\"ת כג, ב. תו\"ח בראשית לד, ב ובהערה 17. לקמן פ' בשלח ריא, ד. תצוה שע, ג."],["179","178","<b>שמציץ</b>: דטו: שמקיא. יא: תיקן: שמקיא. אבל כ\"ה לקמן פ' תצוה שיט, א [ושם הוגה מגוכתי\"ק). וראה גם מאמרי אדה\"א ויקרא ח\"א ע' קי בהערה."],["180","177","<b>מיץ חלב. . משדי אמו</b>: משלי ל, לג. ראה ברכות סג, ב."],["181","179","<b>עובד אדמתו ישבע לחם</b>: משלי יב, יא. כח, יט."]]],[2300540427,"דתורה שבע\"פ דוקא שנק' לחם מן הארץ שהיא באה בעבודה קשה כנ\"ל, אבל כל שעובד אדמתו ביגיעה ועמל תורה ביותר, יותר ישבע אח\"כ לחם זה דתורה כו' מטעם הנ\"ל. וזהו ג\"כ מה שא' בזיעת אפך תאכל לחם דתורה<sup data-n=\"182\">*180</sup>, בעצבון תאכלנה כו' (והוא מצד הקושיות שנק' עבודה קשה וכמו שהי' האריז\"ל מקשה עד שמזיע כו', דזיעה זו הוא הנברר מן היגיעה במלאכה כזיעה שיוצא בחום כו' שאז ירפא לו וישוב רוחו כו', והיינו מה שמשבר כח הקליפה שהוא חלק הרע והפסולת דשקר וטעות היפך האמת דאור תורה כנ\"ל), וכמו שבעמל מלאכה א' בזיעת אפיך תאכל לחם גשמי בעצבון תאכלנה וקוץ ודרדר כו', הכל הוא ג\"כ בלחם דתושבע\"פ כו'.\n<b>וזהו</b> שא' במדרש אדם לעמל יולד<sup data-n=\"183\">180</sup> א\"י אם לעמל תורה אם לעמל מלאכה או לעמל שיחה בשיחה בטילה הרי א' כל עמל אדם לפיהו<sup data-n=\"184\">181</sup>, דעמל מלאכה זהו מצד התערובות טו\"ר דעה\"ד שנתקללה הארץ כנ\"ל, וכך הוא עמל תורה שהוא שרש לתיקון דעמל מלאכה לברר לפסולת ורע וכמו ותורתך בתוך מעי ונדחה הפסולת לחוץ כו', אז גם בפרנסתו יהי' באמונה אלקי' ויזרוק הרע ופסולת דגסות הטבעיות שבטח בחכמתו והצלח' הטבע כו'. ולכך גזרו או' דכל תורה שאין עמה מלאכה<sup data-n=\"185\">182</sup> דוקא סופה בטילה לפי שיגיעת שניהם<sup data-n=\"186\">183</sup> יחד דוקא משכחת עון, וא' טוב תורה עם ד\"א<sup data-n=\"187\">184</sup> דוקא, רק שיהי' מלאכתו עראי ותורתו קבע<sup data-n=\"188\">185</sup> <span data-k=\"pg\">12</span> ּ כו' כידוע, והוא שיעסוק בד\"א בעמל מלאכה בבירור הטוב מן הרע כמו שעוסק בעמל תורה כנ\"ל דהכל א' והא בהא תליא. ואמנם בעמל תורה בלא מלאכה אין בירור זה נמשך למעשה בפו\"מ בטו\"ר שביגיע כפיו לכך סופה בטילה (דזהו במשפיע בלא מקבל כי אדם שם מ\"ה<sup data-n=\"189\">186</sup> שמברר לב\"ן<sup data-n=\"190\">187</sup> דנוגה שנק' עובד אדמתו ובתורה אין זה רק בבירור בדיבור כשר ופסול טו\"ט כו' ולא לענין מעשה שהוא המלאכה במו\"מ שיהי' נושא ונותן באמונה ובטחון כו' כנ\"ל) (רק<sup data-n=\"191\">188</sup> מי שתו\"א מלאכתו נעשי' ע\"י אחרים כרשב\"י<sup data-n=\"192\">189</sup> וכה\"ג כידוע). וזהו וימררו את חייהם [חייהם] דכנ\"י למעלה בעמל תורה בזמן הגלות שחוגרת שק בעבודה קשה בקושיא וקו\"ח ובלבינים ליבון הלכתא כו' שזהו הבא מתערובות קשה דפסולת ורע הרבה כנ\"ל (וכמו שא' בדור ההפלגה לאחר בחי' התיקון כנ\"ל ותהי להם הלבינה לאבן והחומר<sup data-n=\"193\">190</sup> כו' דהיינו כמו באותיות הדיבור דתושבע\"פ שמפלפלי' כמו בשיחה בכל לשון כל' בנ\"א ויש בזה",[["182","*180","<b>בזיעת אפך תאכל לחם דתורה</b>: ראה גם לקמן פ' ויקהל תטז, סע\"ד."],["183","180","<b>במדרש אדם לעמל יולד</b>: איוב ה, ז. ראה סנהדרין צט, ב. אלפא ביתא דר\"ע אות ת בסופו [נוסח א — באוצר המדרשים אייזענשטיין ח\"ב ע' 424]. מאמרי אדה\"א בראשית ע' קלה. וש\"נ."],["184","181","<b>כל עמל אדם לפיהו</b>: קהלת ו, ז [ושם: האדם — ראה מאמרי אדה\"א נ\"ך ס\"ע תל]. פסוק זה מובא באלפא ביתא דר\"ע שם."],["185","182","<b>דכל תורה שאין עמה מלאכה</b>: אבות פ\"ב, מ\"ב. ראה גם לקמן פ' ויקהל תטז, א. מאמרי אדה\"א שמות ח\"א ע' רכט. דברים ח\"ד ע' א'רכה."],["186","183","<b>לפי שיגיעת שניהם</b>: אבות שם בבבא שלפנ\"ז (בהמשך למאמר שבהערה הבאה)."],["187","184","<b>טוב תורה עם ד\"א</b>: אבות שם [ושם: יפה תלמוד תורה — ראה לקמן פ' ויקהל תטז, א. מאמרי אדה\"א דברים ח\"ד ע' א'רכה. וש\"נ. נ\"ך ע' תכט]."],["188","185","<b>מלאכתו עראי ותורתו קבע</b>: ראה ברכות לה, ב. רמב\"ם הל' ת\"ת פ\"ג, ה\"ז."],["189","186","<b>אדם שם מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א בהערה 14."],["190","187","<b>מ\"ה שמברר לב\"ן</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["191","188","<b>(רק</b>: תוקן ע\"פ ב. כה: רק."],["192","189","<b>שתו\"א. . כרשב\"י</b>: שבת יא, א. ראה גם שע\"ת פ, ג ובהנסמן במ\"מ לשם."],["193","190","<b>ותהי להם. . והחומר</b>: נח יא, ג. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' סז ואילך. תו\"א משפטים עז, ג ואילך."]]],[2300540447,"צירופי' רעי' וטובי' שקר ואמת יחד בבלבול גדול אך לאחר הבירור לכוין לאמיתת ההלכה שנק' ליבון הלכתא הרי הלבינה הי' לאבן באותיות דתושב\"כ ממש שהן בעצמם והווייתם אבני קדש העליון כנ\"ל<sup data-n=\"194\">191</sup> וד\"ל) והוא<sup data-n=\"195\">192</sup> ע\"י שנשרפו בכבשן שהן אוי\"ר אמיתי' כו' והחמר הבל הדיבור הי' לחומר [ו]צורה וכך בנין דמל' בקדושה בתושבע\"פ בת\"ח שנק' בוניך שעוסקי' בבנינו ש\"ע<sup data-n=\"196\">193</sup> כו' (וכענין לבנת הספיר<sup data-n=\"197\">194</sup> וכאבן ישפה<sup data-n=\"198\">195</sup> כמ\"ש במ\"א וד\"ל).\n[ז] <b>והנה</b> להבין בתוס' ביאור ענין בחומר ובלבינים שזהו ליבון הלכתא שזהו כל ענין הגלות דתורה ושכינה (ושעי\"ז יהי' הגילוי דאור הגדול לע\"ל וכמ\"ש העם ההולכי' בחשך<sup data-n=\"199\">196</sup> ראו אור גדול כו'). יש להקדים ענין מה שאו' משובח ומפואר עדי עד<sup data-n=\"200\">197</sup> שמו הגדול כו', דהנה ידוע בשרש ענין ירידות הנשמות בגופות שזהו ירידה גדולה כמו מאיגרא רמה לבירא עמיקתא<sup data-n=\"201\">198</sup> דשרש נש\"י עלו במחה\"ק<sup data-n=\"202\">199</sup> כו', אך ירידה לצורך עלי'<sup data-n=\"203\">200</sup> היא שעי\"ז יתעלו למעלה יותר, וכמו תכלית העילוי דעוה\"ב שנק' עדן עילאה דעין לא ראתה<sup data-n=\"204\">201</sup> כו' והוא מ\"ש ויהי נועם ה' עלינו כו' וכן לחזות בנועם ה'<sup data-n=\"205\">202</sup> שאז יהי' תכלית ענין גילוי עצמו' אוא\"ס כמו שהוא למטה כמו למעלה ממש עד שכל א' מראה<sup data-n=\"206\">203</sup> כו' וא' הנה אלקינו זה לנוכח כו', הנה זה השכר והעלי' הגדולה לא יהי' רק ע\"י הירידה דעכשיו דנשמות בגופי' בעוה\"ז ע\"י תו\"מ ותשובה כו' וגם בעוה\"ב יהי' עלי' אחר עלי' עד אין שיעור למעלה, וראי' ממה שא' דת\"ח אין להם מנוחה אפי' בעוה\"ב שנא' ילכו<sup data-n=\"207\">204</sup> מחיל אל חיל כו' ממדרגה למדרגה עליונה יותר וכן עד אין קץ כו', וכמו שאנו או' וקדושים בכ\"י יהללוך סלה שהן נשמות הצדיקי' הגדולי' שנק' קדושים ממש כנשמות האבות ומשה ואהרן<sup data-n=\"208\">205</sup> ושאר הנביאי' כמו לקדושים אשר בארץ<sup data-n=\"209\">206</sup> בארץ החיים דגעה\"ע כו' שהן עולי' תמיד בעילוי אחר עילוי ברום המעלות וזהו יהללוך סלה בלי הפסק<sup data-n=\"210\">207</sup> כלל (וק\"ו הוא [אם] בחייהם בגופי' היו הולכי' מדי יום ויום מדרגא לדרגא כמ\"ש לאברהם התהלך לפני<sup data-n=\"211\">208</sup> כו' וכמ\"ש בזהר<sup data-n=\"212\">209</sup>, כ\"ש במיתתן שנשמתם עולה בתכלית המעלה באא\"ס",[["194","191","<b>דתושב\"כ. . קודש העליון כנ\"ל</b>: לעיל ב, סע\"ד ואילך."],["195","192","<b>והוא</b>: אחיטויח: (והוא."],["196","193","<b>בת\"ח שנק' בוניך שעוסקי' בבנינו ש\"ע</b>: ראה ברכות סד, א. שבת קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ."],["197","194","<b>לבנת הספיר</b>: משפטים כד, י. ראה בהנסמן לעיל הערה 190. לקמן ז, א."],["198","195","<b>וכאבן ישפה</b>: תצוה כח, כ. פקודי לט, יג. ראה גם לקמן ז, א ובהנסמן לשם. מאמרי אדה\"א שמות ח\"ב ע' שצ ואילך. ויקרא ח\"ב ע' תתלז. דרושי חתונה ח\"ב ע' תרלג וע' תרנט."],["199","196","<b>העם ההולכי' בחשך</b>: ישעי' ט, א."],["200","197","<b>שאו' משובח ומפואר עדי עד</b>: בברכת ברוך שאמר."],["201","198","<b>מאיגרא רמה לבירא עמיקתא</b>: ראה חגיגה ה, ב. רש\"י איכה ב, א. מאמרי אדה\"א דברים ח\"ב ע' תכה. שמות ח\"א ע' קח. לקמן פ' בשלח קסד, ד. משפטים רפח, ד."],["202","199","<b>נש\"י עלו במחה\"ק</b>: נסמן לקמן לב, ב."],["203","200","<b>ירידה לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["204","201","<b>עדן. . דעין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["205","202","<b>ויהי נועם. . לחזות בנועם ה'</b>: תהלים צ, יז. כז, ד."],["206","203","<b>שכל א' מראה. . זה</b>: תענית בסופה. ישעי' כה, ט."],["207","204","<b>דת\"ח אין להם מנוחה. . ילכו</b>: ברכות בסופה. תהלים פד, ח. ראה גם מאמרי אדה\"א שמות ח\"א ע' פ. נ\"ך ע' תעב. לקמן טז, ג. כג, ב. פ' בשלח רכא, סע\"ג ואילך. ויקהל תלא, א. תלט, ב פקודי תנז, א."],["208","205","<b>וקדושי' בכ\"י. . כנשמות האבות ומשה ואהרן</b>: ברכת אתה קדוש. ראה לקמן ה, ג. פ' בשלח קפה, ד. ויקהל תכג, ב. פקודי תנז, א. מאמרי אדה\"א נ\"ך ע' תסה. וש\"נ. תו\"ח תולדות קנט, ד ובהערה 45."],["209","206","<b>לקדושים אשר בארץ</b>: תהלים טז, ג."],["210","207","<b>סלה בלי הפסק</b>: עירובין נד, א."],["211","208","<b>התהלך לפני</b>: לך יז, א."],["212","209","<b>וכמ\"ש בזהר</b>: ראה זהר לך פ, א. פד, א."]]],[2300540467,"עד אין שיעור כו'). וכך גם בעדן בעוה\"ב ילכו נשמות הצדיקי' ות\"ח מחיל כו' בלי מנוחה כלל, והטעם <span data-k=\"pg\">ו</span> ּ הוא לפי שאין שיעור כלל לעליות המדרגות בהשגות רוממו' אלקות באא\"ס עצמו כמו בחכ' דא\"ס שלתבונתו אין מספר<sup data-n=\"213\">210</sup> כלל ונק' חכים ולא בחכ' ידיעא<sup data-n=\"214\">211</sup> כלל ודאי שאין שיעור לע[ליו'] המדרגות בעילוי ההשגה לרוממות דא\"ס בחכ' מאחר שהוא בבחי' א\"ס עד דלמת\"ב כלל<sup data-n=\"215\">212</sup> ולכך יהללוך בהלל ושבח סלה בלי שיעור, וזהו לפי שכל שעולי' יותר בהפלא' [ה]השגה יותר נפלא ומרומם ונק' נורא תהלות וכן א' לך דומי' תהלה<sup data-n=\"216\">213</sup> כו' ולכך הלל זה אין לו הפסק כלל משום דאא\"ס למעלה מעלה<sup data-n=\"217\">214</sup> עד אין קץ כו', וכמו\"כ במדות דא\"ס כמו הגדולה שלגדולתו העצמי' אין חקר כלל וכן מדת הגבורה והת\"ת כו' וכמ\"ש לך ה' הגדולה<sup data-n=\"218\">215</sup> והגבו' כו' שהן בחי' מדות דא\"ס עצמו שכל א' בפ\"ע הוא בבחי' א\"ס ממש (ולזאת יכול להיות שכל נשמה כפי מדריגתה בשרשה באצי' באו\"כ המוגבל כמו נשמת אברהם באו\"כ דחסד דאצי' עולה היא במדרגתה זאת בעליות לאין שיעור בבחי' חסד דא\"ס עצמו שאין לה שיעור כלל כנ\"ל וכן נשמת יצחק בפחד ודין דאו\"כ דגבו' דאצי' עולה בבחי' גבו' דא\"ס וכמו מי ימלל גבורות ה'<sup data-n=\"219\">217</sup> כו' שהוא בבחי' א\"ס וכן יעקב בבחי' ת\"ת<sup data-n=\"220\">216</sup> דאצי' עולה בת\"ת דא\"ס לאין שיעור כו' והוא מ\"ש ליעקב ופרצת ימה וצפונה<sup data-n=\"221\">218</sup> כו', וז\"ש אשר נשבעת לאבותינו<sup data-n=\"222\">220</sup> מימי קדם כו'<sup data-n=\"223\">219</sup> ) ושרש נשמת משה בחכ'<sup data-n=\"224\">221</sup> דאצי' עולה בחכ' דא\"ס וכן שמואל הנביא בנצח<sup data-n=\"225\">222</sup> כו', וכה\"ג בכל נשמת צדיק בפרט ילכו בעליות לאין שיעור למעלה אפי' בעוה\"ב מטעם זה דבבחי' א\"ס כל פרט הוא בחי' א\"ס, ולכך גם עדן דעוה\"ב אין לו שיעור בעליות כי גם בחי' התענוג דעצמו' א\"ס ב\"ה אין לו שיעור למעלה בעילוי אחר עילוי כמו שהחכ' ומדות שלו הן בבחי' א\"ס ממש כנ\"ל וד\"ל<sup data-n=\"226\">223</sup> ).\n[ח] <b>והנה</b> מעין ודוגמא דעוה\"ב יש גם עתה בעליות הנשמות בגעה\"ת וגעה\"ע, דבודאי גם בג\"ע שהוא בריאה מאין ליש כמ\"ש ויטע ה' כו' גן בעדן מקדם (וא\"ת זהו גן זהו עדן<sup data-n=\"227\">224</sup> כו'), דעדן זה הוא העדן דעוה\"ב שמתעדנין בו הנשמות",[["213","210","<b>שלתבונתו אין מספר</b>: תהלים קמז, ה."],["214","211","<b>חכים ולא בחכ' ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה (יז, ב)."],["215","212","<b>דלמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["216","213","<b>נורא תהלות. . לך דומי' תהלה</b>: בשלח טו, יא. תהלים סה, ב."],["217","214","<b>דאא\"ס למעלה מעלה</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). סתנ\"ז. תו\"ח נח סט, ב ובהערה 11."],["218","215","<b>שלגדולתו. . אין חקר. . לך ה' הגדולה</b>: תהלים קמה, ג. דהי\"א כט, יא."],["219","217","<b>מי ימלל גבורות ה'</b>: תהלים קו, ב."],["220","216","<b>אברהם. . דחסד. . יצחק. . דגבו'. . יעקב. . ת\"ת</b>: נסמן לקמן פ' וארא סא, ד."],["221","218","<b>ופרצת ימה וצפונה</b>: ויצא כח, יד [בדילוג]."],["222","220","<b>אשר נשבעת לאבותינו</b>: מיכה ז, כ. ראה גם לקמן פ' וארא סב, ב."],["223","219","<b>כו'. . כו')</b>: ב: כו'. . כו'. איאיז: כו'). . כו'."],["224","221","<b>נשמת משה בחכ'</b>: ראה לקו\"ש שמות (כרך ו) ע' 244 ואילך. לקמן פ' ויקהל שצב, ד."],["225","222","<b>שמואל הנביא בנצח</b>: ראה גם שע\"ת קטו, א ובהנסמן במ\"מ לשם."],["226","223","<b>וד\"ל)</b>: יז: וד\"ל. כה: כבפנים. ולא נסמן התחלת החצע\"ג."],["227","224","<b>ויטע. . זהו עדן</b>: בראשית ב, ח. ראה ברכות לד, ב."]]],[2300540486,"כמ\"ש ונחל עדניך תשקם<sup data-n=\"228\">225</sup> שאפס קצהו מאיר ונמשך בג\"ע כמ\"ש ונהר יוצא מעדן<sup data-n=\"229\">226</sup> להשקות הגן (דעתה זהו גן סדרי' דאוריי'<sup data-n=\"230\">228</sup> (כמשי\"ת), וא\"כ יש בג\"ע דעכשיו מעין העוה\"ב ממש. וזהו שגם דעכשיו אין ההארה גם בגעה\"ע רק ממל' דאצי' (מבחי'<sup data-n=\"231\">227</sup> העונג העליון שבכתר מל' שנק' זיו השכינה כו'), מ\"מ יש בזה ריבוי עליות לנשמות עד אין שיעור למעלה וכענין שא' דמיכאל כה\"ר<sup data-n=\"232\">229</sup> דאצי' מקריב נשמות<sup data-n=\"233\">230</sup> ע\"ג המזבח שזהו נשמות דבריא' שעולי' באצי' (כערך בהמ' ע\"ג המזבח, שלגבי האצי' גם בחי' פני אדם דבריא' נחשב שם רק בחי' פני שור<sup data-n=\"234\">231</sup> כו' כמ\"ש במ\"א) ובאצי' עולי' בעליות רבות עד אין קץ כו'. וכמו\"כ גם בגעה\"ת יש ריבוי עליות המדרגו' עד געה\"ע, דודאי אין ערך כלל לנשמות ומלאכים דיצי' ועשי' לגבי מלאכי' ונשמות דבריא' (כמו שאין ערך למדות ומעשה לגבי אור השכל וההשגה שבמוחין כידוע). וכל זה הוא לפי שיש ריבוי חילוקי מדריגות בבחי' העונג שמורכב בג' מדרגות דבי\"ע בכלל שהן נר\"נ<sup data-n=\"235\">232</sup> והוא שכל ומדות ומדו\"מ, שעונג שבעשי' למטה מעונג שבדיבור ועונג שבדיבור למטה מעונג שבמח' הרוחניות, כמו שגם השכל דעשי' למטה משכל דדיבור ושכל שבדיבור למטה משכל דמח' (וסוף<sup data-n=\"236\">233</sup> אותיות השכל שבמח' <span data-k=\"pg\">14</span> ּ נמשך לשכל שבדבור, ונמצא עליי' פנימי' השכל שבדיבור במח' באותיות שבשכל דמח', וכן העלי' משכל דעשי' לדיבור מאחר דאותיות שכל של הדיבור מנהיג למעשה, וידוע דיש בכל א' מדו\"מ שנק' בי\"ע<sup data-n=\"237\">234</sup>, שזהו מו\"ד שבמעשה עולה למעשה שבדבור (כעקימת שפתיו לעשות מעשה<sup data-n=\"238\">235</sup> ), ודו\"מ שבדיבור עולה לעשי' דמח' (כמו שמצייר אותיות או בנין במח' וכה\"ג). וכך הוא בעליות הנשמות בגעה\"ת ממדרגה דשכל והשג' שבמעשה לבד [ב]נשמו' דעשי' וגם העונג ורצון שבזה (כשמחה ש\"מ מצד המעשה לבד כמו במצותיו חפץ מאד<sup data-n=\"239\">236</sup> כו') עולה למעלה במדרגה דשכל והשגה שבדיבור כד\"ת שלומדי' ת\"ח בגעה\"ת (כמו שא' אם בהרת קדמה<sup data-n=\"240\">237</sup> כו' כמ\"ש במ\"א דכל הלכות הנגלות בתלמוד ומשנה לומדי' בגעה\"ת בבחי' הרוחניות שלהם כו'<sup data-n=\"241\">238</sup> (ולכך מכריזי' בג\"ע אשרי מי שבא לכאן<sup data-n=\"242\">239</sup> ותלמודו שלמד בעוה\"ז בידו כו'), (וכן העושי' מצוה בלא כוונה ורעותא דלבא שמקומם בגעה\"ת<sup data-n=\"243\">240</sup> דעשי' עולים בשבת",[["228","225","<b>ונחל עדניך תשקם</b>: תהלים לו, ט."],["229","226","<b>ונהר יוצא מעדן</b>: בראשית ב, י [בדילוג]."],["230","228","<b>גן סדרי' דאוריי'</b>: ראה זהר (מדהנ\"ע) וירא קד, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רג."],["231","227","<b>(דעתה. . (מבחי'</b>: ב: (דעתה. . מבחי'. יז: ליתא. . מבחי'. כה: כבפנים ולא נרשם סיום החצע\"ג."],["232","229","<b>דמיכאל כה\"ר</b>: ראה זהר (ס\"ת) לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["233","230","<b>דמיכאל. . מקריב נשמות</b>: ראה חגיגה יב, ב כגי' הע\"י. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. שע\"ת נו, ג ובהערה 71. תו\"ח בראשית מ, ב ובהערה 24. אוה\"ת ויקהל ע' ב'קצט. לקמן ו, סע\"ג ואילך. פ' יתרו רס, ד. רסט, סע\"ג ואילך. תרומה שו, א. תצוה שמח, רע\"ד. ויקהל תכב, ג. תמא, ג."],["234","231","<b>שלגבי האצי'. . פני שור</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' פג. תקס\"ז ע' רנב. לקמן פ' ויקהל תכח, ב ואילך."],["235","232","<b>דבי\"ע. . נר\"נ</b>: ת\"ז סתכ\"ח (סח, סע\"ב)."],["236","233","<b>(וסוף</b>: כה: לא נסמן סיום החצע\"ג."],["237","234","<b>מדו\"מ שנק' בי\"ע</b>: נסמן לקמן פ' בשלח קמד, ב."],["238","235","<b>כעקימת שפתיו לעשות מעשה</b>: ראה בבא מציעא צ, סע\"ב. הנסמן בלקו\"ת דרושים לשמ\"ע פד, ג. אוה\"ת נח כרך ג ע' 1232. מאמרי אדה\"א דברים ח\"ג ע' תתקכו."],["239","236","<b>במצותיו חפץ מאד</b>: תהלים קיב, א."],["240","237","<b>אם בהרת קדמה</b>: לקמן כב, ג: ”במשנה\". ראה נגעים פ\"ד, מי\"א. בבא מציעא פו, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסח ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך. ש\"א נט, ב. וש\"נ."],["241","238","<b>כו'</b>: אוצ\"ל כו')."],["242","239","<b>אשרי מי שבא לכאן</b>: פסחים נ, א. ראה גם לקמן פ' בא צב, ד. תצוה שלד, ב. ויקהל תיט, ג."],["243","240","<b>מצוה בלא כוונה. . בגעה\"ת</b>: ראה אגה\"ק סכ\"ט (קנ, ב). מאמרי אדה\"א ויקרא ח\"ב ע' תרפא ואילך. דברים ח\"ג ע' תתקח. וש\"נ. במדבר ח\"ד ע' א'תקכב. וש\"נ. לקמן ח, א. פ' בשלח קסט, ד."]]],[2300540504,"ויו\"ט בג\"ע דיצי' שהוא החכ' שבדיבור דתורה אור והעונג שבה כו' (כמו שאמר אכתי לוי מאבראי<sup data-n=\"244\">241</sup> כו'). וכן נשמות דיצי' עולים לגעה\"ע דבריאה כעליי' השכל ועונג שבדבור לעיון המח' כנ\"ל דגם פנימי' השכל ועונג שבדיבור נעשה רק בחיצוני' דמח', שהשגה ושכל אלקו' כמו בטעמי' וסודות התורה שלומדי' בגעה\"ע במל' דבריאה נבדל בערך לגמרי מעונג וחכ' דמל' דיצי' בגעה\"ת שהוא בחי' דיבור, ויש ג' מדרגות דמדו\"מ גם במח' דבריאה ע\"כ יש עליות רבות גם בגעה\"ע עד בחי' כתר דחכמה דמל' דאצי' שמלובש בבריאה שזהו ענין עליות הנשמות דבריא' אף בעונג שבחכ' שלהם במל' דאצי' ע\"י כה\"ר כו' לאשתאבא בגופא דמלכא<sup data-n=\"245\">242</sup>, שהוא עלי' עוד ממל' דאצי' למדות דאצי' כו' וממדות לחו\"ב דאצי' ומחו\"ב לכתר דאצי' שהוא העונג ורצה\"ע, ויש בזה ג\"כ עליות המדרגות למעלה יותר (דכתר<sup data-n=\"246\">243</sup> דאצי' זהו מקיפי' דנר\"נ דאצי' ומבחי' מל' דא\"ק נעשה כתר דע\"י<sup data-n=\"247\">244</sup> דאצי' עד ממל' דא\"ס בכתר דא\"ק<sup data-n=\"248\">245</sup> בכלל כידוע בע\"ח וזהו שנק' שמו הגדול (כמשי\"ת), דודאי כמו שיש ג' מדרגות דמדו\"מ בבי\"ע כמו בגעה\"ע וגעה\"ת כנ\"ל כך יש בחי' נר\"נ שהן שכל ומדות ומל' שכולל מדו\"מ יחד (שנק' ג' לבושי'<sup data-n=\"249\">246</sup> כידוע).\n<b>וכמו</b> שמבואר למעלה בהפרש שבין שכל ועונג שבמעשה לדיבור ומדיבור למח' כך יש הפרש בין המדות שבמעשה וגם בדו\"מ כאוי\"ר שבמעשה לבד או גם במו\"ד הרוחניות יותר כדיבור דתפלה ותורה לגבי אוי\"ר שבמדות שבלב עצמו, כידוע דהמח' מקבל מהרהור הלב וכל הכוונה שבמוח נמשך מכוונה שבלב ומדות שבלב גם הם כלולים משכל שבמדות ומח' שבמדות (שגבוה ממחשבה שבאותיות כו'), וממילא גם [ה]עונג ורצון וחכמה המורכב באוי\"ר שבלב גם שנקרא רעותא דלבא<sup data-n=\"250\">247</sup> למטה מן העונג וחכמה שבמדות שבשכל שבמוח עצמו שמשם נמשך בצמצום במדות שבלב ע\"י מיצר הגרון כידוע שנק' דו\"ר שכליי' ממש והעונג אלקי שבזה עונג עצמי ורוחני הרבה יותר, וכמו\"כ ממדות שבהשגה דמוח בינה לגבי בחי' המדות דחכ' ומחכ' לרצון ועונג העצמי שזהו בשכל שברצון נק' טעם כמוס שבמדות שבו נק' טורי נהורא<sup data-n=\"251\">248</sup> כו', וכן",[["244","241","<b>אכתי לוי מאבראי</b>: ראה ברכות יח, ב. מאמרי אדה\"ז תקס\"ד ע' קג. מאמרי אדה\"א ויקרא ח\"ב ע' תרעז וע' תרפא. במדבר ח\"ג ע' א'סה. דברים ח\"ג ע' תתקלא. עט\"ר (דרוש לעשי\"ת) ע' נט."],["245","242","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["246","243","<b>(דכתר</b>: גם בכה: לא נסמן סיום החצע\"ג."],["247","244","<b>מל' דא\"ק נעשה כתר דע\"י</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א לקמן פ' בשלח קמב, ג. קפט, ד. ויקהל תג, ד. הנסמן בתו\"ח נח סו, ב הערה 18."],["248","245","<b>ממל' דא\"ס בכתר דא\"ק</b>: ראה לקמן פ' בשלח קמב, ג. מאמרי אדה\"א קונטרסים ע' תכה. וש\"נ."],["249","246","<b>מדו\"מ. . ג' לבושי'</b>: ראה תניא פ\"ד."],["250","247","<b>רעותא דלבא</b>: זהר וירא ק, א."],["251","248","<b>טורי נהורא</b>: נסמן לקמן טז, א הערה 680."]]],[2300540522,"ממדות לשכל בין בלב בין במוח בין ברצון ועונג העצמו' יש מדריגה נבדלת בין זה לזה עד שצריך להיות ע\"י צמצום ודילוג המדריגה, וכן משכל לרצון כו', <span data-k=\"pg\">ז</span> ּ וכן מעונג שבשכל לעונג שברצון שלמעלה מן השכל, וכן מעונג עצמו למקור העונג בבחי' רעדכ\"ר<sup data-n=\"252\">249</sup> ממקור כל התענוגים דרצון ועונג המורגש כו' והוא שנק' עונג הנעלם בעצמות שזהו העדן סתימאה<sup data-n=\"253\">250</sup> וכמ\"ש כי עמך מקור חיים<sup data-n=\"254\">251</sup> כו' וד\"ל (ועד\"ז<sup data-n=\"255\">252</sup> יובן שמטעם זה יש עליות רבות מאד בנשמות במדרג' העונג העליון מתחתון [ל]עליון כמו מגעה\"ת עד געה\"ע למעלה כמו במדות וחו\"ב ורצון דאצי' ולמעלה מעלה בבחי' רצון הקדום עד עצמו' העונג שבחכמה ורצון ומדות דא\"ס עצמו, כי הרי ע\"ד כל חלקי מדרגות הנ\"ל בבי\"ע ובאצי' בנר\"נ ומדו\"מ וברצון ועונג הגלוי ונעלם כו' שעולה מתחתון לעליון במדרג' בערך נבדל כו', כך יובן ג\"כ בכלל בע\"ס הגנוזו' בהעלם העצמו' דא\"ס ממש כמו מל' דא\"ס שנק' שמו הגדול<sup data-n=\"256\">*253</sup> ושמי' רבא כידוע שמדה זו בבחי' א\"ס ממש, ויש בזה ג' מדרגו' דאותיות מדו\"מ ובכל א' מוחי' ומדות ומעשה זו למעלה מזו, וכן במדות דא\"ס שנבדל בערך מבחי' מל' כמ\"ש לך ה' הגדולה כו' ואח\"כ לך ה' הממלכה כו' דמל' דא\"ס זהו ענין ההתנשאו' שמצד עצמו שמתנשא בערך נבדל מכל בחי' מל' שבא בהשתלשלו' דקו\"ח כו', ויש במדה י\"ס עונג ורצון וחכ' ומדות ומח' ודיבור כו', וכן בכל מדה מו' מדות חג\"ת כו' וממדות לחו\"ב שנק' חכים ולא בחכ' כו' עד בחי' הרצון ועונג הפשוט דא\"ס ולמעלה מן העונג כו', שע\"כ א' אין זולתך מלכנו<sup data-n=\"257\">253</sup> גם לחיי העוה\"ב כמ\"ש כי עמך מקור כל התענוגי' כו' דגם עדן הנעלם זהו בחי' צמצום מעצמו' א\"ס ממש שאין לו שיעור בעליו' המדרגו' בשעשועי' העצמי'<sup data-n=\"258\">254</sup> כו' כידוע. ובכל זה יובן יותר ענין מה שאו' משובח ומפואר עדי עד לשון נצחי'<sup data-n=\"259\">255</sup> דא\"ס לפי שאין קץ לעליות המדרגו' בחילוקי ההשתלשלו' דאבי\"ע מתחתון לעליון, ועכ\"ז רק עד ולא עד בכלל<sup data-n=\"260\">256</sup> שהוא שמו הגדול במל' דא\"ס ולא למעלה שנק' נורא תהלות כו' וד\"ל (אך<sup data-n=\"261\">257</sup> האבות ומשה וכה\"ג יהללוך סלה בחכ' ומדות דא\"ס עד אין קץ והוא לפי שהאבות הן המרכבה<sup data-n=\"262\">258</sup> לימי קדם כו' ובמשיח יתגלה ממל' דא\"ס כמו שהוא בבחי' הכתר שהוא עונג הפשוט שנק' כתר מל' וזהו ישכיל עבדי<sup data-n=\"263\">259</sup> כו' וגבה מאד (ועכ\"ז אפס בלתך<sup data-n=\"264\">260</sup> גואלינו לימות המשיח ואין דומה לך כו' לתחה\"מ",[["252","249","<b>רעדכ\"ר</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23."],["253","250","<b>העדן סתימאה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. ש\"א מא, א. תו\"ח נח עח, ד בהערה 30. לקמן לג, א. לה, א. פ' בא צב, ד. בשלח קמט, ב. רכד, א. משפטים רפד, ד. שב, א. תצוה שנד, ג. ויקהל שצח, ד."],["254","251","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה גם מאמרי אדה\"א נ\"ך ע' תסח. וש\"נ. שה\"א סב, א. שעה\"י קכז, א. תו\"ח מקץ רכג, א ובהערה 8. לקמן פ' בשלח רג, א. רה, ב."],["255","252","<b>(ועד\"ז</b>: גם בכה לא נסמן סיום החצע\"ג."],["256","*253","<b>מל' דא\"ס שנק' שמו הגדול</b>: ראה גם לקמן יח, רע\"א. סא, ב. קסז, ג. רכג, א. רפו, א. שכו, א. שפח, ד. תד, ב. תל, ב. ש\"א ח, ב. וש\"נ."],["257","253","<b>אין זולתך מלכנו</b>: ברכת יוצר לשבת [ושם: ואין]."],["258","254","<b>בשעשועי' העצמי'</b>: נסמן לקמן פ' בא צב, ד."],["259","255","<b>עדי עד לשון נצחי'</b>: ראה ישעי' כו, ד. סידור שחרית מד, א. פיה\"מ עח, ב ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' תל. לקו\"ת פקודי ה, א. ז, ב. ש\"ש סז, ג. ש\"א ח, ב. לקמן פ' פקודי תמד, ג. תמז, ג. אוה\"ת נ\"ך (כרך א) ע' רי וע' תח."],["260","256","<b>עד ולא עד בכלל</b>: ברכות כו, ב. ראה לקמן שם. אוה\"ת שם."],["261","257","<b>(אך</b>: גם בכה לא נסמן סיום החצע\"ג."],["262","258","<b>שהאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42."],["263","259","<b>ובמשיח. . ישכיל עבדי</b>: ישעי' נב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["264","260","<b>אפס בלתך</b>: ברכת יוצר לשבת."]]],[2300540540,"שיקומו האבות ומשה כו' שהן ז' רועים<sup data-n=\"265\">261</sup> ששרשם בחכמה ומדות דא\"ס עצמו כי אור א\"ס עצמו לאו מכל אינון מדות כלל כמ\"ש אנת הוא חד<sup data-n=\"266\">262</sup> ולא בחושבן י\"ס כלל אפי' בהעלם וד\"ל).\n[ט] <b>והנה</b> מובן ממילא שלפי הנ\"ל בענין העליות ממדרגה למדרגה העליונה ממנה כמו מגעה\"ת לגעה\"ע וכן מעוה\"ז לגעה\"ת צריך להיות תחלה בחי' ירידה שהוא הבירור והתיקון כדי להיות ראוי לעלי' זאת למקום הגבוה בערך נבדל ממדרג' הראשונה, כמו שבעליות הנשמות מגעה\"ת לגעה\"ע יש נהר דינור<sup data-n=\"267\">263</sup> מפסיק ביניהן שבו טובלים הנשמות שמתבטלי' שם ממציאותם הראשון לגמרי עד שאינם נתפסי' בבחי' יש ודבר מה ממהות ועצם הראשון, וזהו ע\"י בירור וצירוף דוקא שמבררם ומלבנם בליבון <span data-k=\"pg\">16</span> ּ יותר והוא הצער דטבילה זו בנה\"ד של אש רוחני ודק כאש המצרף לכסף שמצרף ומברר הסיגי' הדקים ביותר עד שנהפך למהות אחר נקי וברור ביותר, לפי שכל העונג האלקי וההשגו' שהי' להם בגעה\"ת כגשמיות וגסות יחשב לגבי עונג העליון שבשכל וחכ' דגעה\"ע (דאימא מקננא בכורסייא<sup data-n=\"268\">264</sup> כו' שהוא בינה שבמל'), להיות שאין ערך כלל בין עונג ושכל שבמדות ומעשה לעונג ושכל שבמוחי' ומח' וכנ\"ל (דמסוף מדרג' דמח' נמשך לדבור וכן משכל למדות שבלב כו'), וכמו שאין ערך כלל לעונג ושכל דעשי' בפו\"מ לעונג ושכל שבדיבור כנ\"ל. וכמו\"כ בעליות הנשמות מעוה\"ז לגעה\"ת שכ\"ש הוא שאין ערך כלל לתענוג ושכל ומדות גשמיי' שמורכבי' מד\"י גשמיי' שהנשמה היתה מלובשת בהן כל ימי חיי' אפי' במח' ומדות טובי' כמו באוי\"ר ושכל והשגה ועונג אלקי בתורה ותפלה כו' כאשר יבאו לעלות לגעה\"ת שהעונג וחכ' ומדות דשם נבדל בערך לגמרי בבחי' קדושה האלקי' שמובדל ומופשט מכל רע ופסולת לגמרי בלי שום תערובות כלל, וגם בחי' העונג והשכל דקדושה האלקי' הרי הוא בבחי' אלקו' ממש שאין לעונג ושכל האלקי המצומצם בנשמה בהיותה בלבוש שק דנה\"ט ערך לזה העונג והחכ' כלל וכגשמיות התענוג יחשב כעונג שבמאכל הגשמי וכה\"ג כו', ואפי' עונג שבשכל האנושי וגם מה שבשכל האלקי דנשמה בעוה\"ז במס\"נ בק\"ש וכה\"ג כגשמיות ממש יחשב שם (וכידוע שגם קרקע הג\"ע למעלה מרוחני' דד\"י<sup data-n=\"269\">265</sup> ארמ\"ע<sup data-n=\"270\">266</sup> דעוה\"ז כו'), וע\"כ יש להט החרב המתהפכת<sup data-n=\"271\">267</sup> כו' בגעה\"ת",[["265","261","<b>האבות ומשה. . ז' רועים</b>: ראה מיכה ה, ד. סוכה נב, ב. תו\"ח מקץ ריז ב ובהנסמן במ\"מ לשם."],["266","262","<b>לאו מכל. . אנת הוא חד</b>: ת\"ז בהקדמה יז, ב. א."],["267","263","<b>נהר דינור</b>: ראה זהר מקץ רא, א. ויקהל ריא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתכא-ב. שע\"ת מד, ג. סט, ג. תו\"ח בראשית לג, ד ובהערה 10."],["268","264","<b>דאימא מקננא בכורסיא</b>: ת\"ז ת\"ו (כג, א). ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["269","265","<b>קרקע הג\"ע. . דד\"י</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' עו. וש\"נ. לקמן פ' ויקהל תי, ב. תכח, ב."],["270","266","<b>דד\"י ארמ\"ע</b>: ראה סה\"מ תש\"ח ע' 204 בהערה ו. מכתב [שלהי אדר תש\"כ ] נדפס באג\"ק חי\"ט ע' רלט."],["271","267","<b>להט החרב המתהפכת</b>: בראשית ג, כד. ראה גם לקמן פ' ויקהל תט, ג."]]],[2300540557,"להבדיל בין או[י]ר העוה\"ז לאוירא דג\"ע כו'. ולזה צריך בירור ותיקון לנשמות בצירוף קשה ביסורי הגיהנם קודם עלותם לגעה\"ת והוא ענין המירוק והבירור לצרף ולבער כל סיג ופסולת רע גמור מן העוונו' וגם מן הרהורי' רעים וחטאי' שלא לה' כו' שנק' לבושים צואי' שמתבררי' ונשרפי' וכלים באש הגיהנם שהוא אש [ה]רוחני שמבער ומכלה כל חום תאוה קשה במעשה ובמו\"ד ומדות כידוע, וכמצרף הכור הברזל הגשמי שהאש שורף כל סיג קשה ופסולת גס ביותר והוא שנק' כור הברזל להפריד ולהסיר כל לכלוך ומיאוס דרע מן הטוב שא\"א שתוכל לעלות לגעה\"ת לקבל זיו [ו]עונג האלקי בלבושי' צואי' כאלה (כמ\"ש ביהושע כה\"ג הסירו מעליו בגדי[ם] הצואי' והלבש אותו<sup data-n=\"272\">268</sup> כו') כי לא יגורך רע<sup data-n=\"273\">269</sup> כתיב. ואחר הבירור מן הרע ממש שנדבק בנפש החוטאת צריך שתטבול בנה\"ד גשמי שלפני געה\"ת (כי יש ב' מיני נה\"ד<sup data-n=\"274\">270</sup> א' לפני געה\"ת והב' לפני געה\"ע כו'), וענין מירוק ובירור זה בנה\"ד היינו לברר<sup data-n=\"275\">271</sup> וללבן כל פסולת דק ביותר כתאוות היתר וכל המ\"ז ודב\"ט (שז\"ש בזהר שישכחו על חיזו דהאי עלמא<sup data-n=\"276\">272</sup> כו') שכל רוחני בלתי יאבד, ולזאת כל התענוגי' גשמיי' שהנפש נתמלא מהן אפי' בהיתר ואפי' במו\"ד לבד הולכי' ומלבישי' ונדבקים בנפש, לזאת צריך בחי' ירידה שני' בנה\"ד שיבוער מהן כל סיג ופסולת הדק ביותר והעיקר מה שיבאו לכלל בחי' ביטול במציאות מן הגסות [ו]יש שהוא בחי' נפרד מאלקות להיות בבחי' אין ומ\"ה האלקי' כו' (כמו רקבון הגרעין שיופסד צורתו הראשונה לגמרי ונעשה ביטול מיש לאין ממש כידוע), ועי\"ז נעשה הנשמה בחי' כלי לקבל אור <span data-k=\"pg\">ח</span> ּ העונג הנפלא האלקי' [ו]השגו' אלקו' בגעה\"ת להיות נהנין מזיו השכינה שבגעה\"ת עכ\"פ שהוא בחי' מל' דיצי' או עשי'. ועד\"ז יובן בדרך פרט בכל העליות דנשמו' מתחתון לעליון שא\"א להיות כ\"א ע\"י בירור וצירוף ותיקון וביטול המציאות הראשון לגמרי מכל וכל אז תעלה למקום ומדרגה העליונה כו' וד\"ל.\n[י] <b>והנה</b> בזה יובן מה שא' במדרש שא\"א ע\"ה ביקש<sup data-n=\"277\">273</sup> שישראל יקבלו עול טרדת יסורי שעבוד פרנסה בלחץ ודחק במקום יסורי גיהנם כו', כי הגיהנם אינו אלא לברר וללבן ולבער הרע הגמור שנדבק בנפש החוטאת ואפי' בהרהורי עבירה כו' ככור המצרף כנ\"ל. ואמנם עונש הגיהנם גדול וקשה ביותר שלא כל אדם יכול [להיות] שיתוקן ויצורף כל הרע שנדבק בו כל ימיו בגיהנם, וא\"א ראה גודל עוונות בנ\"י בדורות האחרונים שיגדל למעלה ביותר שלא יועיל להם הצירוף",[["272","268","<b>הסירו. . והלבש אותו</b>: זכרי' ג, ד [ושם: הסירו הבגדים הצואים מעליו. . והלבש אותך]. ראה גם לקמן פ' ויקהל תיט, סע\"ג ואילך."],["273","269","<b>לא יגורך רע</b>: תהלים ה, ה."],["274","270","<b>ב' מיני נה\"ד</b>: ראה בהדרושים שנסמנו לעיל בהערה 263. לקמן פ' ויקהל תט, ב ואילך."],["275","271","<b>לברר</b>: יזיח: לבער."],["276","272","<b>שישכחו על חיזו דהאי עלמא</b>: ראה זהר ויקהל ריא, ב."],["277","273","<b>שא\"א ע\"ה ביקש</b>: ראה ב\"ר פמ\"ד, כא. מאמרי אדה\"א קונטרסים ע' רמח. וש\"נ. במדבר ח\"ד ע' א'תרכח. הנחות תקע\"ז ע' רכ. תו\"ח בראשית מ, ד ובהערה 46."]]],[2300540574,"בגיהנם, ע\"כ ביקש שיטרדו בגלות בלחץ ודחק הפרנסה שיחשב במקום יסורי גיהנם. ולכאורה אין ערך ליסורי' דלחץ ועוני בפרנסה לגבי היסורי' הקשי' דגיהנם באש אוכלת הנפש ומכלה כו'. אך הנה א' בזהר ור\"מ ע\"פ הוציאוה ותשרף<sup data-n=\"278\">274</sup> הוציאוה בגלותא ותשרף בשלהובי טיהרא. פי' כחום הצהרים שהוא חום קשה ומכלה ושורף חום אחר הוא שנק' שלהובי טיהרא כו', כך טרדות הפרנסה בגלות שבנפשו יביא לחמו בזיעת אפו שבא בסיבת פיזור הנפש ברצון וחשק שבוער<sup data-n=\"279\">275</sup> כאש בחום קשה כדי למצוא טרף לנפשו, ואמנם אש זה בא במרירות וצער מגודל הלחץ ודחק שאינו מוצא ריוח והצלה להחיות נפשו נק' אשא אוכמא<sup data-n=\"280\">276</sup> ששורף ומכלה כל חום התאו' הקשות ורעות שעשה בח\"נ כו', וזהו שתישרף בשלהובי טיהרא שיש בזה ב' עניני', א' ענין עונש שתשרף ותכלה בשלהובי דגבו' קשות דחום הצהרים שהוא אש המרירות בלחץ ודחק העוני [שנק' כור העוני] שמצרף יותר מכור הברזל באש הגיהנם, וענין כליון זה היינו מה שהנשמה תכלה כחות שלה בשכל ואוי\"ר והי' כלא הי' (כרקבון הגרעין בביטול המציאו' כו'). והב' ענין תיקון ובירור וליבון, שאחר השריפ' דנשמה בגבו' קשות דק\"נ בשלהובי טיהרא תצא נקי' וברה מכל סיג ותוכל לעלות במדרגה עליונה יותר, והוא להתענג על ה' בתפלה בעונג נפלא ובהשגה עמוקה בעומק הלב אפי' בלב בשר כו' כמו שהנשמו' עולי' להתענג בעונג האלקי בגעה\"ת כנ\"ל. וזהו חסד גדול במה שתפטר הנשמה מגיהנם ביסורי' דעוני ולחץ הפרנסה אע\"פ שנק' יסורי מיתה דעני חשוב כמת<sup data-n=\"281\">277</sup> מ\"מ אין זה רע וקשה כעונש הגיהנם (ולפי שבעוה\"ז מאיר מבחי' החסד<sup data-n=\"282\">278</sup> דמקיף דסובב כ\"ע<sup data-n=\"283\">279</sup> כו' ע\"כ גם יסורי' קלים כעוני הפרנסה יחשב כיסורי' הגדולי' שבגיהנם ששם מאיר מבחי' מדה\"ד<sup data-n=\"284\">280</sup> דגבו' עליונה כו' כמ\"ש במ\"א, וכמו ויצאו וראו בפגרי האנשים הפושעים בי בגופא דמלכא<sup data-n=\"285\">281</sup>, כמו קרקפתא דלא מנח תפילין<sup data-n=\"286\">282</sup> שנק' פ\"י בגופן או מחללי שבת וכה\"ג בגזל ועריות וש\"ד אשם לא תכבה כו', אבל בעוה\"ז יפטרו בעונש יסורים דעוני ולחץ קשה ובתשו' בלב נשבר במרירות אמיתי' ובוידוי וחרטה כידוע, וכה\"ג אף בפסולת דק יותר כהרהורי' רעים ותאוות חומריות יבא בתשו' עילאה במרירות מן הריחוק מאלקות בבכי' ולב נשבר, וגם ביסורים וביטושי' בעוני וכה\"ג זהו במקום טבילה בנה\"ד כו' שזהו שעושה ביטול הגסות והיש בתכלית כידוע וד\"ל).\n<span data-k=\"pg\">18</span> ּ<b>אך</b> הטעם למה שבחר אברהם ביסורי' דלחץ ועוני בדחק הפרנסה דוקא שנק' כור העוני כו', הנה מבואר למעלה",[["278","274","<b>הוציאוה ותשרף</b>: וישב לח, כד. ראה זהר אחרי עב, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתכא. דברים ח\"ג ס\"ע א'פד. וש\"נ. קונטרסים שם. תו\"ח וישלח קצז, א."],["279","275","<b>שבוער</b>: תוקן ע\"פ כה. ובתו\"ח כאן: שכועס."],["280","276","<b>אשא אוכמא</b>: ראה זהר בראשית נא, רע\"א."],["281","277","<b>דעני חשוב כמת</b>: נדרים סד, ב. זהר (רע\"מ) משפטים קיט, א. רש\"י שמות ד, יט."],["282","278","<b>שבעוה\"ז. . החסד. . מבחי' מדה\"ד</b>: ראה סידור שחרית לד, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ריח. וש\"נ."],["283","279","<b>שבעוה\"ז. . דסובב כ\"ע</b>: ראה סידור שם לא, ג ואילך. שע\"ת עט, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רכ."],["284","280","<b>מדה\"ד</b>: תוקן ע\"פ כה. בד: הדין. ובתו\"ח: י\"ה."],["285","281","<b>ויצאו. . הפושעים בי בגופא דמלכא</b>: ישעי' סו, כד. ראה זהר יתרו פה, ב. עט\"ר דרוש לעשי\"ת ע' 132 ואילך."],["286","282","<b>קרקפתא דלא מנח תפילין</b>: ר\"ה יז, א."]]],[2300540590,"דבגלות התורה וגם השכינה בגלות וכנ\"ל [ב]מ\"ש וימררו את חייהם דכנ\"י בעב\"ק כו' שבזה מתברר מתערובו' הפסולת ורע דק\"נ [כ]זורע וחורש כו' שעי\"ז יהי' הצמיחה בריבוי יותר כל שיהי' ביטול הגסות ויש יותר בעני [ב]שפלות רוח עד שחשוב כמת ממש (והרוצה לחיות ימית עצמו<sup data-n=\"287\">283</sup> ), וע\"כ מצד הדחק בעניות ובלחץ הפרנסה שנק' כור העוני יבאו למעלה ומדרגה הגבוה ביותר שהוא ימהמ\"ש והעוה\"ב כמו שזכו לקבלת התורה פב\"פ ע\"י הבירור בגלות מצרים שנק' כור הברזל<sup data-n=\"288\">284</sup> כו'. והענין הוא כידוע [ב]מארז\"ל דג' דברים באים ע\"י יסורים<sup data-n=\"289\">285</sup> תורה וא\"י ועוה\"ב, וג' אלה זה למעלה מזה, ולפ\"ע העילוי במדרגה מזה לזה כן ערך היסורים במדרגה גבוה יותר דלפום צערא אגרא כו', א\"כ לפ\"ע השכר כך ערך הצער, וכמו שמבואר למעלה בעליות הנשמות מעוה\"ז החומרי לגעה\"ת שצריך לבא בגיהנם להסיר הרע הגמור כו' (וכתשו\"ת בסיגופי' ותעני' וביטושי' גשמיי' למרק העון), כך הי' בגלות מצרים בחו\"ל כו' בכור הברזל לצרף הרע גמור דנש\"ט דמצרים שיהיו ראויי' לקבלת התורה הנגלית בקולות וברקי' כו', ואח\"כ שיוכלו לבא לא\"י ארץ טובה ורחבה<sup data-n=\"290\">286</sup> בקיום המצות ביח\"ע שנעשי' בא\"י דוקא שלמעלה מזה (שהוא ריבוי האורות בהרחבת הכלים דבחי' התיקון דשם מ\"ה שמברר לב\"ן שהוא א\"י<sup data-n=\"291\">287</sup> כידוע), היו צריכים לבירור שני בצירוף ומיתוק הגבו' קשות הדק יותר, והוא מה שהלכו במדבר מ' שנה כו' בעינוי רעב וצמא כמ\"ש ויענך וירעיבך כו' לנסותך<sup data-n=\"292\">288</sup> כו', והן לבער לגקה\"ט שבמדבר העמים במ\"ב<sup data-n=\"293\">289</sup> מסעות<sup data-n=\"294\">290</sup> שלהם לדורות הבאים כידוע, ואח\"כ זכו ליכנס לא\"י כו'. ואחר עליה זו יהי' עוד עלי' עליונה יותר והוא ימות המשיח ועוה\"ב והרי לפ\"ע העלי' כן ערך הירידה והצער כנ\"ל ע\"כ הי' גלות בבל, וגלות האחרון הזה שנתארך ביותר והוא רק בלחץ ודחק דכור העוני לצרף וללבן כל הנשמות הישינות כו' שזהו כמו שפוטרי' בזה מגיהנם כדי שיוכלו לבא לגעה\"ת שהוא ימות המשיח שהוא [ממש] במדרגה עליונה האלקי' בעונג ושכל ומדות כו' בערך נבדל מן העוה\"ז בתכלית לפי שיבורר אז עה\"ד טו\"ר לגמרי כמו געה\"ת כו'. ומימות המשיח לעוה\"ב עלי' יותר כמו שעולי' מגעה\"ת לגעה\"ע ע\"י טבילה בנה\"ד הב', שהוא צער רוחני ודק יותר וקשה יותר לפ\"ע השכר (וזהו כיסורי הצדיקים בעוה\"ז שנק' יסורים של אהבה<sup data-n=\"295\">291</sup> ולא למרק עון כלל), וכענין מיכאל מקריב נשמות",[["287","283","<b>והרוצה לחיות ימית עצמו</b>: ראה תמיד לב, א."],["288","284","<b>מצרים שנק' כור הברזל</b>: ואתחנן ד, כ. מלכים-א ח, נא. ירמי' יא, ד. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמ. תו\"א יתרו עד סע\"א ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תשע."],["289","285","<b>דג' דברים באים ע\"י יסורים</b>: ראה ברכות ה, סע\"א. לקמן פ' וארא סג, ד. בשלח קלח, ד. מאמרי אדה\"א שמות ח\"א ס\"ע סה ואילך. במדבר ח\"ב ע' תשסט ואילך."],["290","286","<b>ארץ טובה ורחבה</b>: שמות ג, ח."],["291","287","<b>לב\"ן שהוא א\"י</b>: ראה תו\"ח תולדות קסב, א בשם הזהר. מאמרי אדה\"א שמות ח\"ב ע' שעה. וש\"נ."],["292","288","<b>ויענך וירעיבך כו' לנסותך</b>: עקב ח, ג. ב."],["293","289","<b>לבער לגקה\"ט. . במ\"ב מסעות</b>: ראה דרושי אלה מסעי הב' והג' בלקו\"ת. מאמרי אדה\"א במדבר ח\"א ע' קסז ואילך (ובהנסמן בריש המאמר שם). שם ח\"ה ע' א'תתעב."],["294","290","<b>במ\"ב מסעות</b>: נמנו ר\"פ מסעי."],["295","291","<b>כיסורי הצדיקים. . יסורים של אהבה</b>: ברכות ה, א. ראה מאמרי אדה\"א במדבר ח\"ב ס\"ע א'תשסח ואילך."]]],[2300540605,"דבריאה באצי' שזהו צירוף ובירור עליון ביותר (כקטרת<sup data-n=\"296\">*292</sup> במזבח הפנימי מן הבשמי' כו') כדי שישתאבו בגופא דמלכא במדות דז\"א דאצי'. וכן עד\"ז למעלה יותר מאצי' למאציל עצמו כעליות הנשמות דאבות ומשה מחכ' ומדות [דאצי' לחכ'<sup data-n=\"297\">292</sup> ומדות] דא\"ס עצמו כנ\"ל שזהו ענין יהללוך סלה כנ\"ל (כענין תחה\"מ שיקומו האבות ומשה כו' ויאכלו מסעודת לויתן ושור הבר<sup data-n=\"298\">293</sup> כו' שזהו מדרג' הב' דעוה\"ב כו'). ונמצא מובן מכ\"ז דלפ\"ע העלי' צ\"ל הירידה והשפלות בתחלה להיות בביטול המציאות הראשון לגמרי מכל וכל, אז יוכלו לעלות ולקבל ממדרג' העליונה הנבדל ונפלא ממנו (כר\"ז שהתענה<sup data-n=\"299\">294</sup> לשכוח ת\"ב לגמרי כדי שיוכל <span data-k=\"pg\">ט</span> ּ לקבל ת\"י כו') וכענין העמוד שבגעה\"ת שבו נבלעי' ונכללי' הנשמות בביטול כל מציאו' שלהם הראשון בעלותם לגעה\"ע כמ\"ש בס' הבהיר<sup data-n=\"300\">295</sup>, וכמו\"כ מגעה\"ע לאצי' ולמעלה כו' (כמ\"ש במ\"א) וד\"ל. וא\"כ יובן מזה עכ\"פ בדרך כלל טעם ענין ירידת הנשמות בגופי' גשמיי' בעוה\"ז שזהו כמו מאיגרא רמא כו' כנ\"ל, שירידה גדולה זו היא לצורך העלי' דוקא (כמו שגם מה שהשכינה והתורה ג\"כ בגלות הוא לצורך עלי' דוקא כמ\"ש אנכי ארד עמך מצרימה ואנכי אעלך גם עלה<sup data-n=\"301\">296</sup> לעוה\"ב וימות המשיח כו'), והוא מה שע\"י הבירור דנשמה האלקי' בחומר הגוף בכל ימי חיי' שתתברר מתערובות טו\"ר בתכלית כמו במצרף לכסף כנ\"ל ובכור הברזל וכור העוני כו' כנ\"ל עי\"ז תבא ותגיע לקבל אור העונג העליון דעוה\"ב בערך הפלאה במעלה יתירה שהוא העדן עילאה לחזות בנועם ה' כו', שכדאי הי' בשביל שכר גדול כזה כל יסורי' קשי' דעבודה קשה [ב]חו\"ל כו' בעוה\"ז וכל הצרות ויסורי' בלחץ ודחק כו', וכמו שכדאי כל יסורי גיהנם כדי שיקבל עונג העליון בג\"ע ועוה\"ב וכמ\"ש באחר מוטב [ד]לידייני'<sup data-n=\"302\">297</sup> [בגיהנם] וליתי לעוה\"ב כו' כידוע וד\"ל.\n[יא] <b>אך</b> הנה לפי כל הנ\"ל אין עיקר סיבת השכר הנפלא בג\"ע ועוה\"ב בעונג העצמו' דא\"ס שנק' עדן כו' רק ע\"י עוצם הירידה דנה\"א בגוף בגלות קשה כמו [ב]שעבוד עול פרנסה וכה\"ג, ובאמת הרי מצינו בכתובי' ובכל המקומות בדרז\"ל דעיקר קבלת השכר בג\"ע ועוה\"ב אינו רק בקיום המצות בעוה\"ז דוקא כמו שא' היום לעשותם ולמחר לקבל שכרם<sup data-n=\"303\">298</sup> ואלו דברים שאדם אוכל<sup data-n=\"304\">299</sup> כו' וכמ\"ש כ\"י יש להם חלק לעוה\"ב",[["296","*292","<b>נשמות. . (כקטרת</b>: ראה גם לקמן פ' יתרו רס, ד."],["297","292","<b>מחכ'. . לחכ'</b>: זיח: מחו\"ב. . בחו\"ב."],["298","293","<b>מסעודת לויתן ושור הבר</b>: ראה ב\"ב עד, ב. ויק\"ר פי\"ג, ג. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'קיח. לקמן פ' בשלח קסא, א. ויקהל תכב, סע\"ג ואילך. תכט, ב."],["299","294","<b>כר\"ז שהתענה</b>: בבא מציעא פה, א. ראה גם הנסמן לקמן תט, ב הערה 667."],["300","295","<b>העמוד. . בס' הבהיר</b>: בתו\"א מג\"א ק, ב מציין: ע' זהר ויקהל ריא, א. ויחי ריט, א. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשעג־ מאמרי אדה\"א נ\"ך ע' עו."],["301","296","<b>אנכי ארד. . גם עלה</b>: ויגש מו, ד. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קיג ואילך. שמות ח\"א ע' סו. במדבר ח\"ב ע' תשעב. דברים ח\"ב ע' תרכט. לקמן כא, א. סד, ד."],["302","297","<b>מוטב [ד]לידייני'</b>: ראה חגיגה טו, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב ובהנסמן במ\"מ לשם. תקס\"ז ע' שכ. מאמרי אדה\"א שמות ח\"ב ע' שטז. דברים ח\"א ע' נט."],["303","298","<b>היום לעשותם. . שכרם</b>: ואתחנן ז, יא. ראה עירובין כב, א. וראה גם לקמן פ' בשלח קנט, א. קפד, ד. לקו\"ש ואתחנן (כרך כט) ע' 41 ואילך."],["304","299","<b>ואלו דברים שאדם אוכל</b>: פאה פ\"א, מ\"א."]]],[2300540619,"שנא' ועמך כולם צדיקים<sup data-n=\"305\">300</sup> שזהו בתו\"מ דוקא ע\"כ לעולם ירשו ארץ שהוא ארץ החיים<sup data-n=\"306\">301</sup> דעוה\"ב שיהי' נצחי' והוא ארץ עילאה שנק' עדן כנ\"ל ואפי' פ\"י מלאים מצות<sup data-n=\"307\">302</sup> כו', ולא בעבור היסורי' [ב]לחץ ודחק [לבד] שאין זה רק כמו הכנה לבא לעוה\"ב כו', אבל קבלת השכר אינו רק לעובד אלקי' בתו\"מ לשמן כו', ומי שאין בידו תו\"מ אע\"פ שסבל יסורים הרבה אין לו חלק בעוה\"ב כידוע ששכר העוה\"ב אינו רק מבחי' העונג ורצה\"ע שבמצות<sup data-n=\"308\">303</sup> שיתגלה בעוה\"ב כמו שהן למעלה ממש. אך הענין הוא דבאמת כן הוא דגם אחר שתטהר הנפש החוטאת ביסורי גיהנם או ביסורי מות וכור העוני בגלות [ועוני] בעוה\"ז דיסורי' ממרקי'<sup data-n=\"309\">304</sup> העון בפו\"מ ותהי' נקי' מכל פסולת לגמרי (אפי' מפסולת הדק דתאות היתר וכה\"ג), עכ\"ז לא תוכל לקבל השכר בגילוי אור ה' בנועם ה' העליון הנ\"ל אפי' בג\"ע אם לא ע\"י התו\"מ שמקיימי' הנשמו' בגופי' בעוה\"ז דוקא (ובעוה\"ב אינו מועיל המעשה דמצות ולא התשובה כידוע [ב]מ\"ש במתים חפשי<sup data-n=\"310\">305</sup> כו'), ואמנם בלא נקיון הנפש ביסורי' על העוונו' או בתשובה שלימה לא תוכל לקבל השכר דג\"ע ועוה\"ב אפי' מי שיש בידו תו\"מ הרבה (וכמו אחר שהי' בעל תורה גדול וא' מוטב [ד]לידייני' כו' כיון שעבר על כל התו\"מ<sup data-n=\"311\">306</sup> כו'). והענין הוא דבאמת צריך שניהם לתשו' ומע\"ט בעוה\"ז, ותו\"מ בלא תשובה ותשובה בלא תו\"מ לא יועיל לנשמה לעלות למקומה בג\"ע ועוה\"ב, והטעם הוא לפי שתשו' ומע\"ט נק' טהרה וקדושה, וטהרה מביאה לידי קדושה<sup data-n=\"312\">307</sup> ואין קדושה בלא טהרה מקודם, דהטהרה הוא לנקות ולברר לכל פסולת ולכלוך בתכלית מן הרע הדק ואח\"כ טהרה זו מן העכרורי' כטובל במקוה שהטמא יטהר ואז יעלה <span data-k=\"pg\">20</span> ּ לקבל אור הקדושה שהוא בחי' קדש האלקי בעצם הווייתו כו' (כידוע בענין שהם וישפה, דשהם הוא אבן הבהיר בעצם הווייתו<sup data-n=\"313\">*309</sup> וישפה הוא שנעשה בהיר בהסיר ממנו העכרורי' בתכלית שנק' טהרה כטוהר השמים מן העבי' כו' וזהו לבנת הספיר כו', וזהו צ\"ע וצ\"ת<sup data-n=\"314\">308</sup> דתשו' ומע\"ט טהרה וקדושה כו'), וזהו דיסורי גיהנם קודמין לג\"ע שהוא טהרה שמביא' לקדושה דג\"ע, והעיקר בטבילה בנה\"ד שהיא טהרה גמורה (וכמו טהרת הנפש ביסורי' דפרנסה בכור העוני שזהו כמ[י] המבול שטהרו לארץ<sup data-n=\"315\">309</sup> מטומאתה כמ\"ש במ\"א), וכן טבילה בנה\"ד כו'<sup data-n=\"316\">311</sup> לפני געה\"ע וכה\"ג עד רום המעלות",[["305","300","<b>כ\"י. . ועמך כולם צדיקים</b>: סנהדרין ר\"פ חלק (צ, א). ישעי' ס, כא."],["306","301","<b>ארץ החיים</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קד. דברים ח\"א ע' ה. שמות ח\"א ע' קמ ובהנסמן בהנ\"ל. תו\"ח ח\"ש קלה, א ובהערה 7. לקמן פ' בשלח קעה, ב. רלה, א. תצוה שלא, ד. ויקהל תי, ד. תכב, ד."],["307","302","<b>פ\"י מלאים מצות</b>: עירובין יט, א."],["308","303","<b>ששכר העוה\"ב. . שבמצות</b>: ראה גם מאמרי אדה\"א בראשית ע' שצב. וש\"נ. ש\"א ג, א וש\"נ. תו\"ח לך פג, א ובהערה 11. לקמן לג, ד. סה, ד. קעז, ב. שמא, א. שנד, ג. שצז, ג. תנב, ג."],["309","304","<b>דיסורי' ממרקי'</b>: ברכות ה, א."],["310","305","<b>במתים חפשי</b>: תהלים פח, ו. שבת קנא, ב. ל, ב. ראה סידור שחרית לב, א. לקו\"ת פינחס עה, ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתכג. וש\"נ. במדבר ח\"ג ע' א'עו ואילך. ח\"ה ע' א'תרכד ואילך. דברים ח\"א ע' מו. וש\"נ. הנחות תקע\"ז ע' ריא ואילך וע' רכ. לקמן פ' בשלח קס, א."],["311","306","<b>שעבר על כל התו\"מ</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשצה."],["312","307","<b>וטהרה מביאה לידי קדושה</b>: ראה ירושלמי שבת פ\"א, ה\"ג. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ק."],["313","*309","<b>דשהם. . הבהיר בעצם הווייתו</b>: ראה גם לקמן פ' בשלח ריב, א. תצוה שמו, א. שנ, ד. פקודי תנו, ב. וראה ס' הערכים חב\"ד ח\"א מערכת אבן נג, א הערה *83 [ושם צ\"ל: תקי, א]. סה\"מ תרס\"ח ע' קט."],["314","308","<b>שהם וישפה. . צ\"ע צ\"ת</b>: ראה לקו\"ת ראה כה, ד. כז, ד. מאמרי אדה\"א דברים ח\"ב ס\"ע תמא ואילך וע' תע ואילך."],["315","309","<b>כמ[י] המבול שטהרו לארץ</b>: ראה תו\"א נח ח, סע\"ג ואילך ובהנסמן לשם. תו\"ח נח נח, ג ובהערה 50. לקמן פ' בשלח ריד, ד."],["316","311","<b>כו'</b>: בזיא: ב'. יזיח: ליתא."]]],[2300540633,"(כתחה\"מ לפני עוה\"ב דטל אורות טלך<sup data-n=\"317\">312</sup> זהו דנטיף מגבו' דע\"י בח\"ס ללבן הנשמות בגופים טהורים וקדושים כו' (והוא בשביל עלי' הב' דעוה\"ב<sup data-n=\"318\">313</sup> אחר השכר דמצות כמ\"ש<sup data-n=\"319\">314</sup> במ\"א<sup data-n=\"320\">310</sup>, וזהו ענין ב' הדברים שצריך להיות יחד בתשו' בלב נשבר מח\"נ ועינוי העמל דפרנסה (וכן עמל תפלה במרירות הרוחני' דנשמה כנ\"ל [ב]מ\"ש וימררו את חייהם כו') ובעמל תורה במיצוי הנפש בליבון הלכתא מתערובות רע ושקר כו' כנ\"ל), וכל זה נק' טהרה להסיר כל עכרורי' (כאבן ישפה כנ\"ל שנק' צ\"ת), ואח\"כ בחי' הקדושה האלקי' שבתו\"מ בפ\"מ כמו שאו' אשר קדשנו<sup data-n=\"321\">315</sup> במצותיו, קדשנו ממש בקדש העליון דפנימי' רצה\"ע ועונג העצמי' (שזהו מה שיתגלה בעוה\"ב כנ\"ל), וענין קדושה זו דמצות ותורה שעשה כל ימיו הוא שמתגלה מבחי' העלם דרצה\"ע שלמעלה ונעשה לו שכר קבלת עונג זה עצמו, דשכר מצוה מצוה<sup data-n=\"322\">316</sup> עצמה, דהיינו בג\"ע וכן בעוה\"ב (וכמ\"ש באדה\"ר לעבדה ולשמרה<sup data-n=\"323\">317</sup> כידוע). אך א\"א להיות קדושה בלא טהרה דתשו' ויסורים, אפי' בצדיקי' וכמו יסורים של אהבה וכה\"ג, וזהו פלא לכאו' דאם יש קדושה עליונה העצמי' בעצם מעשה המצות כנ\"ל למה לא יזכה לקבל השכר הזה ממצות גם בלא יסורים כו'.\n<b>אמנם</b> הנה הענין הוא דבאמת לכאורה הנה יש להפל[י]א על ענין הנ\"ל בעליות הנשמות העליונות ממדרגה למדרגה עליונה יותר עד אין שיעור למעלה כו' כמו מגעה\"ת לגעה\"ע ומגעה\"ע לאצי', דלפי הכלל הידוע שאין ערך כלל וכלל לתחתון עם העליון וכ\"ש לנשמות שהוא נברא ב[ע]\"ג ומחודש כו' לגבי בלתי ב[ע]\"ג וא\"כ איך יכול להיות שתעלה ותבא ליכלל במדריג' עונג האלקי הבלתי בע\"ג בגעה\"ת וכ\"ש שתעלה שם ותקבל זיו העונג האלקי ותתקיים במציאותה דוקא, דודאי ראוי שתתבטל שם לגמרי יותר מביטול הנר באבוקה כו', וכמו\"כ בעלי' הב' מגעה\"ת לגעה\"ע שזהו ממל' דיצי' למל' דבריאה שמעלת האור האלקי דבריאה נבדל בערך לגמרי מעונג [ה]אלקי דמל' דיצי' (כערך עונג שבעשי' לדיבור ודיבור לגבי המח' כו' כנ\"ל) וכ\"ש מגעה\"ע לאצי' ומאצי' למעלה במאציל שאין ערך לאור האצי' במאצי' כערך בריאה לאצי' כידוע. אך הנה הענין ידוע שבאמת מטעם זה א\"א להיות עליות הנשמות מתחתון לעליון שהי' מתבטלת שם לגמרי (גם אחר הבירור שלה כנ\"ל) כ\"א ע\"י בחי'",[["317","312","<b>דטל אורות טלך</b>: ישעי' כו, יט. ירושלמי ברכות פ\"ה, ה\"ב. ראה זהר (אד\"ר) נשא קכח, ב. סידור תפלת ר\"ה רלז, ב. מאמרי אדה\"א דברים ח\"ג ע' א'לא. לקמן פ' בשלח קסא, רע\"א."],["318","313","<b>עלי' הב' דעוה\"ב</b>: ראה גם לעיל ו, ד (ובהערה 293)."],["319","314","<b>כמ\"ש במ\"א</b>: ב: (כמ\"ש במ\"א)]. אבל לא נמצאו שני מוסגרים בדרושי אדה\"א (וראה גם לקמן הערה 359). יאטו: (כמ\"ש במ\"א)."],["320","310","<b>וכן. . כמ\"ש במ\"א</b>: טו: ליתא. וכנראה שנשמט מפני תיבות הדומות: כמ\"ש במ\"א). . כמ\"ש במ\"א."],["321","315","<b>שאו' אשר קדשנו</b>: נוסח ברכת המצות."],["322","316","<b>דשכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה לקמן נ, ד. קנח, ד. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכה. מאמרי אדה\"א ויקרא ח\"א ע' נד ואילך. שמות ח\"ב ע' שכ. וש\"נ. דברים ח\"ג ע' תתצט. וש\"נ."],["323","317","<b>לעבדה ולשמרה</b>: בראשית ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א בראשית ע' עג־ קונטרסים ע' שי."]]],[2300540646,"לבוש דוקא, והוא מה שיש לכל נשמה ונשמה בחי' לבוש זך ונקי שנק' לבושא דכיא<sup data-n=\"324\">318</sup> שמלבישי' אותה, שבלבוש זה דוקא תוכל לעלות לעליון ממנה ולהתקיים שם לקבל האור העליון ולא תתבטל כלל וכלל, כי בחי' הלבוש הזה יש בו מבחי' כח המקיף העליון שבכחו להעמיד ולקיים למציאו' דנשמ' <span data-k=\"pg\">י</span> ּ שלא תתבטל ממציאות[ה] בפני זיו השכינה הנעלה ממדרגתה הראשונה (כמו ביהושע כה\"ג שא' הלבש אותו מחלצות<sup data-n=\"325\">319</sup> כו' וכמ\"ש בזהר) (וכמו ואתה משמרה בקרבי<sup data-n=\"326\">320</sup> שיש כח העליון דמקיף לשמור לנשמה בגוף שלא תכלה ותצא במס\"נ כטבע הניצוץ שנמשך לשרשו כנר בפני האבוקה וכענין בע\"כ אתה חי<sup data-n=\"327\">321</sup> כו' וכמ\"ש במ\"א עמ\"ש ואתם בנ\"י לא כליתם<sup data-n=\"328\">322</sup> במס\"נ כו'), ומוכרח שיהי' כח הזה מבחי' ומדרגה העליונה יותר משרש הנשמה, מאחר שיש בכחה להפוך אותה מטבעה שלא תצא ותכלה בבחי' רץ לבך<sup data-n=\"329\">323</sup> באה\"ר בתענוגי' עד כלותה כו'. וזהו מה שיש בכח כל א' מישראל הרצון והתשוקה שיומשך בנשמתו גילוי אלקות ע\"י תו\"מ וצדקה ותפלה וכה\"ג שהוא בחי' השוב להמשיך גילוי אורו' העליוני' בכלים מכלים שונים דוקא, כענין שמבקשי' והאר עינינו בתורתך<sup data-n=\"330\">324</sup> ודבק לבנו במצותיך דגם שלא יעלה למעלה בהתלהבות דרץ לבך כלל אלא ישאר למטה יחפוץ בזה יותר דהיינו מה שיתגלה בנשמתו למטה מטה כמו שהוא בחומר גופו מאור האלקי הפנימי' שזהו קדושה האלקי' דמצות ותורה אור כמו שבאו למטה בגשמיות דוקא כדי שיהי' גילוי אלקו' למטה דוקא כמו בדברים גשמיי' דמעשה המצות שיהי' כלי לאור ה' או בנשמתו בגופו ולא יחפוץ לעלות וליכלל למעלה כו', וכח בחי' השוב הזה גובר על בחי' הרצוא דמס\"נ שמזה מוכרח שיש לו שרש גבוה יותר והוא בבחי' המקיפי' דנר\"נ שהוא למעלה מגילוי אור האלקי שבנר\"נ הבא באו\"פ<sup data-n=\"331\">325</sup> ), ולבושי' הללו נעשי' ממעשה המצות בעוה\"ז דוקא שנעשי' בדברים גשמיי' דק\"נ וכן מתורה שלמד בעוה\"ז דוקא. וזהו שא' והלך לפניך צדקך<sup data-n=\"332\">326</sup> דמעשה המצות כבוד ה' דתורה יאספך, שתוכל לעלות בעילוי אחר עילוי מדרגא לדרגא עד רום המעלות ולא תתבטל במציאות כלל וכלל כנ\"ל וד\"ל.\n[יב] <b>אך</b> הנה יש להבין מאין יש כח בלבושי' דנשמה מן מעשה המצות ומד\"ת בעוה\"ז שיהי' מעלה לנשמה בעליות",[["324","318","<b>לבושא דכיא</b>: זהר שלח קסט, ב. ראה גם לקמן פ' וארא סב, ג ובהערה 133. בשלח קצג, ג."],["325","319","<b>הלבש אותו מחלצות</b>: זכרי' ג, ד [ושם: והלבש אותך — ראה לקמן פ' ויקהל תכ, ד. תלא, ג. מאמרי אדה\"א בראשית ע' תנ. וש\"נ]. ראה זהר שם."],["326","320","<b>ואתה משמרה בקרבי</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה מאמרי אדה\"א נ\"ך ע' תסו. וש\"נ. תו\"ח נח עז, א ובהערה 4. לקמן פ' וארא סב, ג. ויקהל שצד, ג. תיד, א."],["327","321","<b>בע\"כ אתה חי</b>: אבות ספ\"ד. תניא ספ\"נ. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שסו. תקע\"א ע' קפא. לקמן פ' ויקהל שפט, ד. תיד, א."],["328","322","<b>ואתם בנ\"י לא כליתם</b>: מלאכי ג, ו [בנ\"י ( בני יעקב) — תוקן ע\"פ כה. ובתו\"ח כאן: בני ישראל!]. ראה גם מאמרי אדה\"ז תקס\"ז ע' קמח. תו\"א יתרו סז, א. לקו\"ת ר\"ה סא,ד. מאמרי אדה\"א במדבר ח\"ב ע' תרכט. נ\"ך ע' תפד. לקמן פ' יתרו רנג, א. שצד, סע\"ג. תיד, א."],["329","323","<b>רץ לבך</b>: נסמן לקמן פ' בשלח קסד, ג."],["330","324","<b>והאר עינינו בתורתך</b>: ברכת ק\"ש (שחרית). ראה גם לקמן פ' ויקהל שפט, ד. מאמרי אדה\"א קונטרסים ע' שעה."],["331","325","<b>באו\"פ)</b>: ב: באו\"פ. כה: כבפנים ולא נסמן התחלת החצע\"ג. ואולי התחלתה הוא בתיבת והוא בשורה שלפנ\"ז."],["332","326","<b>והלך לפניך צדקך. . כבוד ה'. . יאספך</b>: ישעי' נח, ח."]]],[2300540658,"המדריגות כ\"כ ולא תתבטל כלל מאחר שאין ערך לבע\"ג לבלתי בע\"ג ואיך יוכל להיות שכלי המוגבל מאין ליש כנשמו' דעשי' יקבלו עונג האלקי דזיו השכינה בגעה\"ת שהוא בלתי גבול ונבדל בערך לגמרי ומה יועיל לה הלבוש, וכן בענין העליות מגעה\"ת לגעה\"ע שאין ערך ביניהם כלל כנ\"ל. אמנם הענין הוא שיש בזה ב' טעמי', א' מצד בחי' קדושה העליונה דפנימי' הכתר ופנימי' החכ' שבתו\"מ, שהמצות הן פנימי' רצונו ית' כמו שהוא בפנימי' התענוג בעצמו' ממש (שזהו העוה\"ב כנ\"ל) והתורה אור פנימי' אור חכמתו העצמי', וגם מה שבאי' בבחי' התלבשו' למטה בדברים גשמיי', לא נסתר עצם האור שלהם כמו שהן למעלה ממש, וכמו שאנו או' שקדשנו במצותיו ממש בטו\"ת שלמעלה שמתעטף בטלית<sup data-n=\"333\">327</sup> ומניח תפילין<sup data-n=\"334\">328</sup> ועושה צדקה ומשפט<sup data-n=\"335\">329</sup> כו' ונק' מצותי ותורתי<sup data-n=\"336\">330</sup> כו', והוא מה שהתורה נק' אור בב' מדרגו' דאו\"פ ואו\"מ (וכן המצות), באו\"פ זהו מה שבאה באותיות המוגבלות בקלף ודיו בתשב\"כ בג\"ן סדרי' דאוריי' ששרשם למעלה באותיות דקדש העליון כמו ואתא מרבבות קדש כו' ומאיר בכל אות ואות מאור קדושת העצמו' דא\"ס ב\"ה והיינו ממקור כל התענוגי' העצמי' כמ\"ש ואהי' אצלו שעשועי'<sup data-n=\"337\">331</sup> כו', וזהו בחי' טנת\"א שבתורה אור וע\"ז א' ונהר יוצא מעדן<sup data-n=\"338\">332</sup> להשקות את הגן גן זה הוא ג\"ן סדרי' דאוריי' שמקבלים מנהר דבינה ש\"מ <span data-k=\"pg\">22</span> ּ שיוצא מעדן דחש\"מ ממקור התענוג הפשוט כו' וזהו בחי' כלי לאור א\"ס ממש, שזהו מה שהנשמה תוכל להשיג ממהו\"ע אור התענוג העליון דזיו השכינה בג\"ע ועוה\"ב ולא תתבטל במציאו' כלל, לפי שאותיות התורה שבאים בנשמה להאיר אור [יש] בכחם לקבל אור הגדול הזה, לפי שמלובש בהן אא\"ס ממש כידוע דאין התלבשות אור א\"ס אלא בחכ'<sup data-n=\"339\">333</sup> הפנימי' דתורה בחי' מ\"ה דח\"ע כמו מה שמו<sup data-n=\"340\">334</sup> כו' שהוא בבחי' אין העצמי כמו ונחנו מה<sup data-n=\"341\">335</sup> דמשה בביטול פנימי' ועצמי' כידוע. ולכך יש ביכולת אור דתורה שבא בנשמה להאיר ממה שקרא בעוה\"ז כל ימיו להעלות אותה עדי עד שמו הגדול כנ\"ל (לפי<sup data-n=\"342\">336</sup> שכל אותיות התו' הם נק' שמותיו העצמיים וכמו שא' כל הקורא בתורה קורא בשמותיו<sup data-n=\"343\">337</sup> כו'. וכמו שנהר דעדן בא בג\"ן סדרי' באו\"פ בכלים, כך יש בחי' או\"מ דתורה שזהו מ\"ש עוטה אור כשלמה<sup data-n=\"344\">338</sup> ממש שמקיף לראש ורגל כא' והוא מקיף דח\"ע דתורה אור שבלתי מוגבל באותיות (כטעמים ונגינות כו'), וע\"י",[["333","327","<b>שמתעטף בטלית</b>: ראה ר\"ה יז, ב. מאמרי אדה\"א שמות ח\"ב ע' שסו. וש\"נ."],["334","328","<b>ומניח תפילין</b>: ברכות ו, א."],["335","329","<b>ועושה צדקה ומשפט</b>: ירמי' ט, כג."],["336","330","<b>מצותי ותורתי</b>: תולדות כו, ה."],["337","331","<b>ואהי' אצלו שעשועי'</b>: משלי ח, ל [בדילוג]."],["338","332","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רג. תו\"ח נח סב, ג. לעיל ה, רע\"א."],["339","333","<b>התלבשות אור א\"ס אלא בחכ'</b>: ראה תניא פי\"ח (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה. לקמן פ' תצוה שנז, ב. ויקהל שפט, ד. שצב, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תרכא. שע\"ת עג, ג בהערה 62."],["340","334","<b>מה שמו</b>: שמות ג, יג. משלי ל, ד."],["341","335","<b>ונחנו מה</b>: נסמן לקמן מג, א."],["342","336","<b>(לפי</b>: יאיזיח: לפי. ואולי סיום החצע\"ג הוא אחרי תיבת כו' בשורה המתחלת בתורה."],["343","337","<b>כל הקורא בתורה קורא בשמותיו</b>: ראה פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלט. תו\"ח ח\"ש קלד, ב ובהערה 10."],["344","338","<b>עוטה אור כשלמה</b>: תהלים קד, ב."]]],[2300540670,"התלבשות הנשמה באו\"מ דתורה תעלה למעלה יותר עד אין שיעור כמ\"ש בהתהלכך תנחה אותך<sup data-n=\"345\">339</sup> כו', וכנ\"ל במ\"ש כבוד ה' יאספך שהוא כבוד דחכ' דתו' בבחי' מקיף דאו\"פ המוגבל באותיות התורה וד\"ל (ולכך יאספך שתוכל להתקיים ולקבל אור וזיו השכינה כי זהו למעלה מאו\"פ המאיר לכל נשמה כפי כלי שלה, וזהו בחי' השוב דתורה אור שחפץ בחיים דאור תו\"מ ולא יכלה במס\"נ לשרשו בתפלה כנ\"ל וד\"ל).\n<b>וכמו\"כ</b> יובן בענין המצות שיש בהן ב' מדרגות דאו\"פ ואו\"מ, באו\"פ זהו מה שהמשכת רצה\"ע מלובש בכלי דמעשה המצות ממש ומוגבל בה האור לפי אופן הכלי דוקא בד' בתי' דתפילין ול\"ב חוטי' דציצית כו' וכה\"ג בצדקה מוגבל בה אור פנימי' דחסד עליון כו', וזהו שנק' רמ\"ח מ\"ע רמ\"ח אברי'<sup data-n=\"346\">340</sup> כו' כאבר שמגביל לאור וחיות שבו כידוע, ומדרגה הב' זהו או\"מ דמקיף זה היינו כמו שהמצות למעלה ברצה\"ע וח\"ע, דגם שרצה\"ע וח\"ע זו יש בכל מצוה בפרט באופן מיוחד, מ\"מ נק' בחי' מקיף שבכתר שהן תר\"ך עמודי'<sup data-n=\"347\">341</sup> או תרי\"ג ארחין דגלגלתא<sup data-n=\"348\">342</sup> כו' וכמו כצנה רצון תעטרנו<sup data-n=\"349\">343</sup> בעטרה ומקיף, והוא שנק' המצות בבחי' לבושי' דוקא שמלביש לראש ורגל כו' כנ\"ל [ב]מ\"ש והלך לפניך צדקך כו', שבחי' לבושי' אלה בהן שורה המקיפי' דמצות שעי\"ז תעלה הנשמה בעילוי אחר עילוי בלי שיעור כלל לפי שמקיף דרצה\"ע שבמצות אין להם שיעור כלל למעלה. וזהו הטעם שע\"י המצות בלא כוונה בגעה\"ת וע\"י כוונה בגעה\"ע שיעלו הנשמות בלבושים הללו ומתקיימי' גם במדרג' העליונה למעלה מאצי' כעליות הנשמות דאבות ומשה כו' כנ\"ל לפי שקיימו המצות בעוה\"ז דוקא, והטעם הוא לפי שבירידת אור הרצה\"ע והתענוג וח\"ע בתומ\"צ שלמטה שנתב\"ס<sup data-n=\"350\">344</sup> דוקא לפי שמלובש בזה מבחי' החשמל העליון דחשך סתרו שנהפך החשך לאור ע\"י בירור דחשמ\"ל דנוגה שנעשה בו המצוה ותורה אור בעוה\"ז דוקא (וכענין לעבדה ולשמרה בג\"ע ברוחניות כידוע). וזהו כמו לבושי' דקדושה עליונה שנעשה מדבר גשמי שהוא כלי המעשה דמצות שקדשנו כו' ותורה הנגלית לנו באותיות כנ\"ל, ועכ\"ז נק' אור קדוש בעצם הוייתו כמו או\"מ דתורה א' עוטה אור כשלמה וכן בלבוש דמצות נק' לבושי' דקדושה כמו בגדי קדש<sup data-n=\"351\">345</sup> כו' כענין הלבש אותו מחלצות כו' שמלביש לנש\"י להעלותם <span data-k=\"pg\">יא</span> ּ עד אין שיעור כמ\"ש צרורה בצרור החיים<sup data-n=\"352\">346</sup> את ה' כו' (כמ\"ש במ\"א). ובזה יתורץ הקושיא הנ\"ל איך יהי' ביכולת הנשמה לעלות כו', דודאי ע\"י לבושי' דתו\"מ מבירורי' דנוגה בגשמיות תתעלם<sup data-n=\"353\">*347</sup> ותעלה",[["345","339","<b>בהתהלכך תנחה אותך</b>: משלי ו, כב."],["346","340","<b>רמ\"ח מ\"ע רמ\"ח אברי'</b>: נסמן לקמן מו, ב."],["347","341","<b>שבכתר שהן תר\"ך עמודי'</b>: ראה פרדס (שער מהות והנהגה) ש\"ח, פ\"ג. לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."],["348","342","<b>תרי\"ג ארחין דגלגלתא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א."],["349","343","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שכז. ש\"א נז, א."],["350","344","<b>שנתב\"ס</b>: נסמן לקמן מד, ג."],["351","345","<b>בגדי קדש</b>: תצוה כח, ב."],["352","346","<b>צרורה בצרור החיים</b>: שמואל-א כה, כט. ראה אגה\"ק סכ\"ט. לקו\"ת שלח נא, ד. מאמרי אדה\"ז נביאים ע' טו ואילך. מאמרי אדה\"א בראשית ע' תמט."],["353","*347","<b>תתעלם</b>: כ\"ה גם בהכת\"י."]]],[2300540682,"ולא תתבטל לפי שיש בהן כח גדול יותר מאור המאיר לנשמה (והוא השוב שאחר הרצוא כנ\"ל).\n[יג] <b>אך</b> הנה מבואר למעלה בענין תושבע\"פ מל' קרינן לה<sup data-n=\"354\">347</sup> שז\"[ש] וימררו את חייהם בעב\"ק כו' שהתורה חוגרת שק דנוגה בזמן הגלות והוא שנק' עמל תורה בפלפול בקושיות ותירוצים כו' עד שמברר הדין והלכה מכל סיג ופסולת שנק' ליבון הלכתא כו', והוא בירור דאו\"ח שמהפך חשך הגס דק\"נ שנק' חשמ\"ל התחתון לאור כשמברר הטוב מן הרע והאמת מן השקר כו' בפלפול אמיתי שז\"ש עובד אדמתו ישבע לחם דתורה כו'. ואע\"פ שנק' עב\"ק בקושיא וקו\"ח כו' אבל אחר הבירור שנהפך מחושך לאור האמת זהו כזריעה שנרקבה לגמרי וצומח עי\"ז מחדש בריבוי לאין שיעור מאין ממש בחידוש גמור שעולה למעלה משרש הח\"ע דתורה אור במקורה הראשון שנאמר בה עוטה אור כשלמה כו' כנ\"ל, הגם שהוא נמשך בבחי' קדש העליון (שהוא כאבן השהם בחי' צ\"ע כנ\"ל) בבחי' או\"י מלמעלה למטה ולא נחשך אורו אף בהתלבשו' באותיות שבכתב כנ\"ל מ\"מ אין בו חידוש גמור רק כמו שהוא במקורו נמשך למטה, ואע\"פ שנהפך מהעלם דחושך העליון לאור ע\"י ההתלבשו' באותיות ובדברים גשמי', אינו בחי' חידוש גמור למטה ואין בו שינוי כלל ונק' לבוש אור [ו]זך בעצם הווייתו (כיריעות שבמשכן וכיריעות שלמה שע\"ז א' עוטה אור כו' ואף שנק' משל הקדמוני<sup data-n=\"355\">348</sup> כשבא למטה בלבוש דעה\"ד טו\"ר כו'). אבל בחידושי ההלכות שמתבררי' בפלפול דתושבע\"פ בתלמוד וכה\"ג זהו חידוש גמור שנעשה מחושך גמור אור שזהו בירור דחשמ\"ל דלבוש שק דנוגה מלמטה למעלה כאשר הוברר ממנו כל סיג ופסולת קשה וכל עכרורי' דקושיות המסתיר לאור האמת אז נק' לבוש טהור וזך (כאבן ישפה ) שנטהר מכל רע ונעשה טוב מבירור הפסולת שזהו שנק' לבוש[י'] דכיא, שאין טהרה אלא מכלל טומאה כנ\"ל בענין טהרה וקדושה בתשו' ומע\"ט כו' ששרשם עולה למעלה יותר מלבוש דאור ח\"ע שנק' קדש בעצם. וכמו שא' שבתורתו של ר\"מ הי' כתוב כתנות [א]ו\"ר<sup data-n=\"356\">349</sup> באלף, שמרמז בזה על בירור דב\"ע<sup data-n=\"357\">350</sup> החמודות שנפלו בתערובות רע קשה ונק' כתנות עור [כ]עורות עבודי', שאחר הזיכוך ובירור שלהם בתכלית נק' כתנות [א]ו\"ר באלף כאור בהיר יותר מלבוש דחשמל העליון שא' עוטה אור כשלמה (וזהו כאהלי קדר<sup data-n=\"358\">351</sup> כיריעות שלמה שחשך דקדרות כשנהפך לאור יאיר יותר מאור בעצם כו') שהוא זיהרא עילאה<sup data-n=\"359\">352</sup>. וזהו וירח ריח בגדיו<sup data-n=\"360\">353</sup> דכתנות עור הנ\"ל ויברכהו כו' כמ\"ש במ\"א",[["354","347","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["355","348","<b>משל הקדמוני</b>: שמואל-א כד, יג וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג."],["356","349","<b>שבתורתו. ֿ. כתנות [א]ו\"ר</b>: בראשית ג, כא. ראה ב\"ר פ\"כ, יב. מאמרי אדה\"א ויקרא ח\"ב ע' תצג. וש\"נ. שעה\"י קמ, א ואילך ובהערה 10."],["357","350","<b>דב\"ע</b>: יח: דבגדי עשו."],["358","351","<b>כאהלי קדר</b>: שה\"ש א, ה. ראה גם מאמרי אדה\"א ויקרא ח\"א ס\"ע קח ואילך. במדבר ח\"ב ע' תקנה. לקמן טז, ג."],["359","352","<b>זיהרא עילאה</b>: ראה זהר בראשית לו, ב. שעה\"י קמ, א. קמא, ב. מאמרי אדה\"א ויקרא ח\"א ע' קעז. לקמן פ' בא צט, ב. בשלח קצא, א. קצב, ד. משפטים שב, ב. תרומה שיא, א."],["360","353","<b>וירח ריח בגדיו</b>: תולדות כז, כז [בדילוג — ראה לקמן פ' תרומה שיא, א. ויקהל תה, ד. תו\"ח תולדות קמט, א בהערה 9]. ראה ד\"ה באתי לגני תקס\"ד בסידור שער התפלה כז, ב. כח, ד. לקו\"ת שה\"ש לב, ב."]]],[2300540694,"(והוא<sup data-n=\"361\">354</sup> עורות<sup data-n=\"362\">356</sup> תחשים<sup data-n=\"363\">355</sup> מלמעלה על יריעות עזים (שכיסו<sup data-n=\"364\">357</sup> בהן הכלים אחר שפר[ש]ו בגד תכלת כו' לבלי יוכל ליקרב זר כו' ותחש זה ששש בגוונין<sup data-n=\"365\">358</sup> שהוא בירור המדות גם במעשה ע\"י ו\"ס משנה דוקא (כמשי\"ת)<sup data-n=\"366\">359</sup>. וזהו בחי' עמל תורה שהתורה בגלות בלבוש שק ומתברר בליבון הלכתא שזהו או\"ח שלמטה מאו\"י דתושב\"כ וכמ\"ש א\"ח עט\"ב<sup data-n=\"367\">360</sup> כו' דרשה צמר ופשתים כו' עד עוז והדר לבושה<sup data-n=\"368\">361</sup> ותשחק ליום אחרון בעוה\"ב שיעלה למעלה מעונג העליון דשכר המצות כו' וכמ\"ש בזהר גבי עדן למחכה לו למאן דדייק<sup data-n=\"369\">362</sup> מילי' דחכ' בגירסא <span data-k=\"pg\">24</span> ּ ועיון כבד בעמל תורה הנ\"ל דוקא<sup data-n=\"370\">363</sup> ), וזהו ותחת רגליו כו' כלבנת הספיר<sup data-n=\"371\">364</sup> שזהו בירור וליבון הלכות מחושך שלמטה לאור, וכמו ותהי להם הלבינה לאבן כו' (כמ\"ש במ\"א). וזהו ג\"כ ענין התשובה שמהפך חושך לאור ממש ([ו]כקטרת מי\"א ארורי' נעשה ברוך<sup data-n=\"372\">365</sup> כו'), שמות עצמו נעשה חיים שנק' טוב מאד<sup data-n=\"373\">366</sup> וכמ\"ש ה' ממית ומחי'<sup data-n=\"374\">367</sup> כו' בתחה\"מ [ד]לע\"ל. וזהו עמל תורה שבנפשו ממש יביא לחמו עד שממית עצמו עליה כמ\"ש אדם כי ימות באהל<sup data-n=\"375\">368</sup> דתו' כו' שלמעלה מאור החיים דח\"ע דתוה\"ק מטעם הנ\"ל, וכמ\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"376\">369</sup> כו' שהוא בירור הלכות מן הפלפול הקשה כמים שמוציאי' מסלע קשה אל הי\"ק<sup data-n=\"377\">370</sup> דתוה\"ק כו' מטעם הנ\"ל וד\"ל (שכ\"ז אינו רק כמשל הצמיחה שאחר הזריעה כנ\"ל), כמ\"ש זרעו לכם לצדקה<sup data-n=\"378\">371</sup> שהן תו\"מ מרוחניות לגשמיות באו\"י במקיף ופנימי או\"כ כנ\"ל וקצרו בתושבע\"פ בחידושי הלכות מן הבירור דפלפול כו' בריבוי גדול מאד.\n<b>וזהו</b> שמרומז הכל [ב]מ\"ש א\"ח עט\"ב דתושבע\"פ נק' א\"ח שמקבל מבעלה ח\"ע דתושב\"כ אך כא\"ח שמרווחת בבית ובשדה יותר הרבה מעצם הון ביתו בתחלה, וז\"ש בטח בה<sup data-n=\"379\">372</sup> כו' שא\"ח הנ\"ל ממרחק דוקא תביא לחמה ותתן טרף<sup data-n=\"380\">373</sup> רפ\"ח ע\"ה<sup data-n=\"381\">374</sup> שזהו הכל בירור דחשמ\"ל דק\"נ כנ\"ל, וכמ\"ש דאזלת לטורי חשוכא<sup data-n=\"382\">375</sup> ומשם ארחת מזונא דחכ' כלחם מן הארץ הנ\"ל. וז\"ש דרשה צו\"פ, דצו\"פ זה יש באו\"י דח\"ע בתושב\"כ כמו בחוטי",[["361","354","<b>(והוא</b>: טו: והוא. כה: כבפנים."],["362","356","<b>עורות תחשים. . שכיסו בהם הכלים</b>: ראה במדבר ד, ה ואילך."],["363","355","<b>עורות תחשים. . עזים</b>: ראה תרומה כו, יד וברש\"י. שבת כח, א וברש\"י."],["364","357","<b>(שכיסו</b>: ב: שכיסו. כה: כבפנים. ואולי סיום החצע\"ג הוא בשורה שלאח\"ז אחרי התיבות זר כו'."],["365","358","<b>ותחש זה ששש בגוונין</b>: שבת שם. ראה גם לקמן פ' תרומה שיא, ב."],["366","359","<b>(כמשי\"ת)</b>: ב: (כמשי\"ת)] — ראה גם לעיל הערה 314. ז: כמשי\"ת). כה: כבפנים."],["367","360","<b>א\"ח עט\"ב</b>: משלי יב, ד. ראה גם בסמוך בפנים (ומצרף פסוק זה (יב, ד) לפרק לא)."],["368","361","<b>דרשה צמר ופשתים. . עוז והדר לבושה</b>: משלי לא, יג. כה."],["369","362","<b>למחכה לו למאן דדייק</b>: ישעי' סד, ג. ראה זהר ח\"ש קל, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקעט. וש\"נ. תו\"ח בראשית לה, ג ובהערה 49."],["370","363","<b>דוקא)</b>: ביא: דוקא. כה: כבפנים. ואולי התחלת החצע\"ג הוא בתיבת וכמ\"ש בשו\"ה שיעלה."],["371","364","<b>ותחת רגליו. . הספיר</b>: משפטים כד, י. וראה גם לעיל הערה 190."],["372","365","<b>מי\"א ארורי' נעשה ברוך</b>: תבוא כז, טו ואילך. ראה ע\"ח (שער המלכים) שי\"א, פ\"י. מאמרי אדה\"ז תקס\"ז ע' שלד. הנסמן במאמרי אדה\"א קונטרסים ע' שמב."],["373","366","<b>מות. . שנק' טוב מאד</b>: ראה גם בראשית א, לא. ב\"ר פ\"ט, י."],["374","367","<b>ה' ממית ומחי'</b>: שמואל-א ב, ו. ראה גם מאמרי אדה\"א שמות ח\"א ע' ד. וש\"נ."],["375","368","<b>אדם כי ימות באהל</b>: חוקת יט, יד. ראה הנסמן לעיל בהערה 176."],["376","369","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["377","370","<b>הי\"ק</b>: יזיח: הים הקדמוני:"],["378","371","<b>זרעו לכם לצדקה</b>: הושע י, יב."],["379","372","<b>בטח בה</b>: משלי לא, יא."],["380","373","<b>ממרחק תביא לחמה ותתן טרף</b>: משלי שם, יד. טו."],["381","374","<b>טרף רפ\"ח ע\"ה</b>: נסמן לקמן לט, א."],["382","375","<b>דאזלת לטורי חשוכא</b>: ראה זהר פינחס רמט, ריש ע\"ב."]]],[2300540706,"לבן דפשתן<sup data-n=\"383\">377</sup> שבציצית שהן רמ\"ח מ\"ע וחוטי דתכלת עמרא<sup data-n=\"384\">378</sup> בשס\"ה<sup data-n=\"385\">376</sup> ל\"ת, אבל מלמטה למעלה באו\"ח דתושבע\"פ דרשה צו\"פ זה עצמו בריבוי וחידוש לאין שיעור כנ\"ל, וזהו ותעש בחפץ העליון [כ]פי'<sup data-n=\"386\">379</sup> שנק' ארץ חפץ לעוה\"ב (כמשי\"ת). ועד\"ז יובן כל הפסוקי' עד שש וארגמן לבושה<sup data-n=\"387\">380</sup>, שש כיתנא<sup data-n=\"388\">381</sup> בגד התחתון מרמ\"ח מ\"ע שבפרטי' הבירורי' דתו' שבע\"פ, וארגמן בגד העליון מלבוש דכיא באו\"ח דסומ\"ר בל\"ת שכללותם הוא בחי' טהרה שעולה למעלה מקדושה דאו\"י דח\"ע דתו\"מ שנמשך בתושב\"כ הנ\"ל. וזהו תנו לה מפרי ידיה<sup data-n=\"389\">382</sup> כו' דקאי לע\"ל בעוה\"ב דוקא שאז דוקא תהי' עט\"ב כו'. ואע\"פ שעכשיו מ\"ה דח\"ע מברר לב\"ן וע\"ז א' ואל אישך<sup data-n=\"390\">383</sup> כו' והוא ימשל בך, דזהו תושב\"כ שנק' משפיע לתושבע\"פ בחי' מקבל נוק' כידוע. והענין הוא כמבואר במ\"א במ\"ש כי על כל כבוד חופה<sup data-n=\"391\">384</sup> דיש ב' מיני כבוד כבוד עליון דמשפיע באו\"י דח\"ע דאצי' בתושב\"כ וחופה דאו\"מ כמו עוטה אור כשלמה כנ\"ל, וכבוד הב' דמקבל באו\"ח שהוא ח\"ת דתשבע\"פ ואו\"מ שלה בבחי' מקיף דאו\"ח מלמטה למעלה, ואמנם מקיף זה דאו\"ח שבא מבירור דחשמ\"ל התחתון ממש כנ\"ל עולה ומתרחב למעלה עד אין שיעור משא\"כ מקיף דאו\"י שנמשך למטה רק כפי ערך המקבלי' כו'. וזהו ענין עלי' הב' דאו\"ח דעמל תורה במדרגה הב' דעוה\"ב שיעשה למחכה לו דוקא כנ\"ל שאחר הקדושה דשכר התו\"מ בעוה\"ז, וכמו שדקדק לומר ת\"ח דוקא אין להם מנוחה אפי' בעוה\"ב אחר השכר<sup data-n=\"392\">385</sup> שנא' ילכו מחיל אל חיל כו', לפי שעליות שלהם ע\"י לבוש דחשמ\"ל דכתנות עור שנהפך לאור יעלה אותם למעלה יותר מעונג העליון<sup data-n=\"393\">386</sup> שבתו\"מ הנמשך באו\"י מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> ענין תחה\"מ שנק' טהרה שלמעלה מקדושה דעוה\"ב בשכר המצות כידוע בבחי' טהרה דטה\"ע ש[ז]הו כעצם השמים לטוהר<sup data-n=\"394\">387</sup> בהבהקת האור בעצם כמו ביו\"כ שא' לפני ה' תטהרו בטה\"ע<sup data-n=\"395\">388</sup> שלמעלה מן הקדושה דאו\"י הנ\"ל, וזהו מעלת התשו' על הצ\"ג כו'. והוא מדרגה הב' דעוה\"ב בחצי העליון",[["383","377","<b>בחוטי לבן דפשתן</b>: ראה שו\"ע אדה\"ז הל' ציצית ס\"ט, ס\"ד."],["384","378","<b>דתכלת עמרא</b>: יבמות ד, ב."],["385","376","<b>בחוטי לבן. . רמ\"ח. . דתכלת. . בשס\"ה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רכה. אמ\"ב שער הציצית צו, ב. מאמרי אדה\"א שמות ח\"ב ע' תרטו. במדבר ח\"ג ע' א'שיג. א'שלג ואילך. א'עדר."],["386","379","<b>ותעש בחפץ. . [כ]פי'</b>: סיום הכתוב דדרשה צמר ופשתים."],["387","380","<b>שש וארגמן לבושה</b>: משלי לא, כב."],["388","381","<b>שש כיתנא</b>: יומא עא, ב."],["389","382","<b>תנו לה מפרי ידיה</b>: משלי לא, לא."],["390","383","<b>ואל אישך</b>: בראשית ג, טז."],["391","384","<b>כי על כל כבוד חופה</b>: ישעי' ד, ה. ראה סידור דרושים לחתונה קכח, ד. לקו\"ת שה\"ש מז, ב. מאמרי אדה\"ז תקס\"ז ס\"ע רפג ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' א. וש\"נ."],["392","385","<b>השכר</b>: תוקן ע\"פ יזיח. ובתו\"ח: השבח."],["393","386","<b>העליון</b>: יזיח: דעדן."],["394","387","<b>כעצם השמים לטוהר</b>: נסמן לקמן פ' בא קכג, ג."],["395","388","<b>לפני ה' תטהרו בטה\"ע</b>: נסמן לקמן שם."]]],[2300540718,"דכתר (דב\"פ<sup data-n=\"396\">389</sup> ש\"י תר\"ך<sup data-n=\"397\">390</sup>, <span data-k=\"pg\">יב</span> ּ ולהנחיל אוהבי יש<sup data-n=\"398\">391</sup> הראשון בשכר המצות זהו חצי התחתון דתר\"ך כו' כמ\"ש במ\"א) והיינו למחכה לו בעמל תורה דוקא, וכן בעמל תפלה בצעקה במרירות כבע\"ת כו' כנ\"ל, ובעמל פרנסה בצעקה מעב\"ק בחו\"ל בנפשו יביא לחמו כו'. וזהו ואביוני אדם<sup data-n=\"399\">392</sup> בקדוש ישראל יגילו דקאי בבע\"ת שנק' אביוני' ברוחניות דאדם ואביון ממש, וכן בעמל תורה שבנפשו יביא לחמו<sup data-n=\"400\">393</sup> דתורה כו' וכמו\"כ בעול מצות. דבמצות יש ג\"כ ב' מדרגות דא\"י ואו\"ח דכמו שהמצות נמשכים מרצה\"ע למטה בכלי' נק' או\"[י] ויש בזה<sup data-n=\"401\">394</sup> מקיף ופנימי כנ\"ל, אך מה שמבטל הרצון רק לקיים רצונו במצות בעול ממש<sup data-n=\"402\">395</sup> כמא' בטל רצונך מפני רצונו<sup data-n=\"403\">396</sup> כעבד בעול בע\"כ רק מצד גזירת מלך כו' זהו בחי' או\"ח להפוך חושך לאור ממש כעמל ועול תורה הנ\"ל. וז\"ש הקים [עול]<sup data-n=\"404\">397</sup> עולה דתומ\"צ דוקא כו', שעולה למעלה משרש המצות במקורן במקיף דרצה\"ע כי הרי מבטל עצמו לבעל הרצון כו' כידוע. וזהו שא' תחלה עשה רצונו כרצונך<sup data-n=\"405\">398</sup> בהמשכת גילוי רצה\"ע מלמעלה למטה באו\"י (שמזה יקבל שכר [ב]עוה\"ב שהוא גילוי זה העונג ורצה\"ע שיתגלה מן הלבוש הגשמי כידוע וכנ\"ל), ואח\"כ א' בטל רצונך כו' כדי שיבטל רצון אחרי' דק\"נ להפוך חשך לאור, דמאן דלא מהפך<sup data-n=\"406\">399</sup> חשך לאור למטה לית לי' חולקא בההוא עלמא, כי כל מה שיתגלה מן ההעלם דחשמ\"ל העליון בעוה\"ב אינו בא רק ע\"י היפוך חשמ\"ל דנוגה שלמטה כמו ע\"י תשובה וביטול רצון במצות ועמל תורה ותפלה כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן מארז\"ל דיפה שעה א'<sup data-n=\"407\">400</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב, ולכאורה הלא<sup data-n=\"408\">401</sup> עיקר השכר ממעשה המצות ותשו' הוא בעוה\"ב ואיך יגדל מעלת מעשה המצות ותשו' בעוה\"ז יותר מן השכר שלהם בעוה\"ב כו', והרי א' היום לעשותם ולמחר לקבל שכרם. אך הענין הוא דעוה\"ב הוא שנק' עולם ברור<sup data-n=\"409\">402</sup> שהוברר מכבר ונמשך האור בכלי דוקא בבחי' או\"פ, כמו שצדיקים יושבים ונהנין מזיו<sup data-n=\"410\">403</sup> כו' שהוא קבלת שכר לנשמות שיקבלו מעונג העליון כל א' כפי מדריגתו וכפי מעשיו בעוה\"ז בתו\"מ כנ\"ל, והיינו מה שיתגלה מן ההעלם דעונג העליון שבתו\"מ למעלה גם למטה לנשמות שבא במדה ושיעור כשפע",[["396","389","<b>(דב\"פ. . במ\"א)</b>: בדיאיגטו: דב\"פ. . כו' (וכמ\"ש במ\"א). זיזיח: כבפנים."],["397","390","<b>דב\"פ ש\"י תר\"ך</b>: ראה גם ע\"ח (שער ז\"א) שי\"ז, ספ\"א. שער מאמרי רשב\"י לתרומה קסו, א (קרוב לסופו). לקו\"ת שלח מח, סע\"א. ש\"א ק, ב. לקמן לג, רע\"ד."],["398","391","<b>ולהנחיל אוהבי יש</b>: משלי ח, כא. סוף עוקצי'. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקיט. במדבר ח\"ב ע' תקמב. תו\"ח מקץ רכא, ב."],["399","392","<b>ואביוני אדם</b>: ישעי' כט, יט. ראה לקמן פ' בשלח קעח, א. רטז, ג. תצוה שכד, ד. מאמרי אדה\"א נ\"ך ע' נא ואילך (ובהנסמן שם ע' כז). בראשית ע' קכב. וש\"נ."],["400","393","<b>כו'. . לחמו</b>: יח: ליתא וכנראה נשמט מפני תיבות הדומות לחמו. . לחמו."],["401","394","<b>בזה</b>: יאיזיח: בהן."],["402","395","<b>ממש</b>: יאטויזיח: מ\"ש מלכות שמים."],["403","396","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."],["404","397","<b>הקים [עול]</b>: שמואל-ב כג, א. ראה במדב\"ר פי\"ח, כא. מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."],["405","398","<b>עשה רצונו כרצונך</b>: אבות שם."],["406","399","<b>דמאן דלא מהפך</b>: ראה זהר בהקדמה ד, א. מאמרי אדה\"א בראשית ע' קפ. דברים ח\"ג ע' א'ס ובהנסמן בהנ\"ל. שער האמונה מא, ב ואילך. לקמן פ' פקודי תנה, ב."],["407","400","<b>דיפה שעה א'</b>: אבות פ\"ד, מי\"ז [בהוספת אות ד דיפה — ראה לקמן פ' בשלח קנט, ד. קסח, ב. רמה, א. יתרו רסח, א. תצוה שמג, ג [ושם הוגה מגוכתי\"ק]. פקודי תנב, ג. הנסמן במאמרי אדה\"א בראשית ע' קנה. ש\"א יא, ב. שה\"א סד, ב. תו\"ח בראשית ה, ג בהערה 25]."],["408","401","<b>הלא</b>: טזיז: הרי. יאטו: כבפנים."],["409","402","<b>דעוה\"ב. . עולם ברור</b>: ראה פסחים נ, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתכג. דברים ח\"א ע' מו."],["410","403","<b>שצדיקים יושבים ונהנין מזיו</b>: ראה ברכות יז, א."]]],[2300540730,"ההולך באו\"י, וגם זהו רק גילוי ההעלם העליון בסוד וטעם הכמוס לרצה\"ע שבמצות כו'. אבל תשו' ומע\"ט בעוה\"ז שמתברר החושך הגס דק\"נ שהוא הסתר גמור כחופר בעומק הארץ שמגלה העלם דעפר כו' בעמ\"ת שמגיע זה למעלה מעמ\"ר כו', והוא דאו\"ח<sup data-n=\"411\">404</sup> [ש]עולה בבחי' מקיף דאו\"ח דתענוג הנעלם שבלתי יבא במדה ובגילוי למטה כלל אלא עולה למעלה בלי שיעור (כסמ\"ך עגול<sup data-n=\"412\">405</sup> היפוך המ\"ם המרובע), וזהו בעוה\"ז דוקא שהוא עומד בתערובות רע ומתברר באו\"ח דתשו' בביטול היש לאין כו' עד שהתחתון יכול לעלות למעלה יותר כו' (וזהו<sup data-n=\"413\">406</sup> בבחי' מקיף דסובב הכללי שעליון נעשה תחתון ותחתון עליון, כמו שהבע\"ת יכול לעלות משאול תחתית למעלה מצ\"ג וצדיקים יכולים ליפול למטה (כמו שא' עולם הפוך ראיתי<sup data-n=\"414\">407</sup> עליונים למטה ותחתונים למעלה (כמצרף לכסף שמתבלבל ועולה התחתון ועליון יורד למטה), משא\"כ בעוה\"ב שאין תשו' מועיל ולא מצות שהוא באו\"פ בכלי כו' (וז\"ש אלה לחיי עולם<sup data-n=\"415\">408</sup> כו') ע\"כ א' דיפה שעה א' בתשומע\"ט באו\"ח בעוה\"ז מכל חיי העוה\"ב הנמשך לצדיקים באו\"פ כו' (וזהו עליות דנשמות [ת\"ח] אחר תחה\"מ ועוה\"ב שעולי' עד אין שיעור באו\"ח דוקא כנ\"ל וד\"ל).\n[יד] <b>והנה</b> להבין כל הנ\"ל בתוס' ביאור במה שעמל תורה דתושב\"פ דוקא עולה למעלה מתושב\"כ כנ\"ל, הנה יש להקדים [ב]מ\"ש ששים המה מלכות ושמונים פלגשים ועלמות אין מספר כו' אחת היא יונתי<sup data-n=\"416\">409</sup> כו', להיות ידוע בדרז\"ל דס' מלכות הן ס' מסכתות ושמונים פלגשים אלו הברייתות<sup data-n=\"417\">410</sup> <span data-k=\"pg\">26</span> ּ ועלמות אין מספר אלו ההלכות<sup data-n=\"418\">*411</sup> כו', וזהו פלא איך יתכן לקרו[ת] שם למסכתות בשם מלכות וכמו שא' מתניתין מלכתא וברייתות פלגשים כו' והלכות בשם עלמות דמשמע דמסכתות דמשניות הן כמו אשה [ש]נשאת לאיש וכמלכתא כו' וכן פלגשי' ביחוד לפרקי' והלכות הן כמו עלמות ובתולות בלתי נשואות ולא ידעו איש כו'. אך הנה ידוע במ\"ש שמע בני מוסר אביך<sup data-n=\"419\">411</sup> שזהו תושב\"כ ואל תטוש תורת אמך זהו תשבע\"פ שנק' אם, וכמו שתושב\"כ נק' אביך מקור המוליד לנש\"י וכך תשבע\"פ נק' אם לבנים (שנש\"י הן בבחי' הריון ועיבור במעי אימא עילאה דבינה<sup data-n=\"420\">412</sup> שהוא תושבע\"פ או אימא תתאה מל'<sup data-n=\"421\">413</sup> קרינן לה וכמ\"ש",[["411","404","<b>דאו\"ח</b>: יאטויזיח: ליתא. וכנראה נשתרבב מבסמוך בפנים."],["412","405","<b>כסמ\"ך עגול</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רכח. וש\"נ."],["413","406","<b>(וזהו</b>: ביאטויז: וזהו."],["414","407","<b>עולם הפוך ראיתי</b>: פסחים נ, א."],["415","408","<b>אלה לחיי עולם</b>: דניאל יב, ב."],["416","409","<b>אחת היא יונתי</b>: שה\"ש ו, ט."],["417","410","<b>ושמונים פלגשים אלו הברייתות</b>: בתו\"א שמות נא, ב בשם הזהר. ובאוה\"ת כאן ע' יב: ברבות שם [שהש\"ר פ\"ו ט, יב] אלו פ' פרשיות שבתו\"כ וזהו כעין ברייתא. ובגמ' פ\"ק דברכות די\"א ב דתו\"כ נק' מדרש."],["418","*411","<b>ועלמות אין מספר אלו ההלכות</b>: ראה גם לקמן פ' ויקהל שצ, ב. וש\"נ."],["419","411","<b>שמע בני מוסר אביך</b>: משלי א, ח. ראה מדרש משלי שם. אגה\"ק סכ\"ט (קנא, א) בשם הזהר. אוה\"ח לזהר ר\"פ פינחס. כנפי יונה ח\"א, פ\"ד. מאמרי אדה\"א דברים ח\"ד ע' א'תנ. וש\"נ."],["420","412","<b>אימא עילאה דבינה</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"ח."],["421","413","<b>אימא תתאה מל'</b>: ראה תניא רפנ\"ב. אגה\"ק סכ\"ה (קלט, א). הנסמן במ\"מ ללקו\"ת שה\"ש יח, ב."]]],[2300540742,"עד שהביאותיו אל בית אמי כו' ולחדר<sup data-n=\"422\">414</sup> הורתי כו' וכה\"ג), (והוא לפי דס\"ר נש\"י מתקשרי' בס\"ר אותיות דתשב\"כ שנק' ספר והוא מוסר אביך כח המקור שממנו שרש נש\"י בעצם והמשכת מ\"ד זה נמשך לנוק' שנק' אם שהיא תושבע\"פ והן ס' מסכתות כו' שנקרא סיפור<sup data-n=\"423\">415</sup> כמשי\"ת<sup data-n=\"424\">416</sup>. והענין הוא כידוע דתשב\"כ הוא בבחי' איש משפיע, דחכ' שבאותיות דתשב\"כ נמשך בדרך אור ושפע למקבלי' להיות נדרש מהן כל דין והלכה בתושבע\"פ ותושבע\"פ נק' אשה שהוא בחי' מקבל השפע מתושב\"כ, וכמו שאנו רואים על<sup data-n=\"425\">417</sup> דין והלכה שדורשי' בתושבע\"פ למדי' הכל מתושב\"כ כמו מנלן א' קרא<sup data-n=\"426\">418</sup> כו', וכל שאין לו ראי' מן המקרא אינו נפסק להלכה למעשה כידוע. אך [הנה] עכ\"ז הרי אנו רואים שכל עיקר פרטי של מעשה<sup data-n=\"427\">419</sup> המצות איך לעשותם בפו\"מ אין זה בא בפירוש כ\"א בתושבע\"פ דוקא ולא בתושב\"כ, כמו במצות ציצית שא' ועשו להם ציצית<sup data-n=\"428\">420</sup> על כנפי כו' לא נתפרש כלל איך ומה אופן פרטיות מעשה המצוה הזאת בל\"ב חוטין דלבן ותכלת רק בדינין המפורשי' בה' ציצית, וכן בתפילין וסוכה ולולב ושופר ובדיני שבת ויו\"ט וקרבנות וכה\"ג הכל נתפרש בכל פרטי אופני הלכה למעשה רק בתושבע\"פ בו\"ס משנה שכוללי' ס' מסכתות (וגם במשנה לא ידעו כל דין והלכה על בוריה רק בפלפול דת\"ח [כ]חכמי ישראל בתלמוד שמחדשי' ומבררים הכל להורות הלכה למעשה שהרי אין מורין מתוך המשנה<sup data-n=\"429\">421</sup> שמבלי עולם לפי שבמחלוקת שנוי' ובקיצור כו', וזהו שנק' עמל תורה כמשי\"ת<sup data-n=\"430\">422</sup>, ולכאורה איך ימצא במקבל הרבה יותר מן המשפיע שהוא תשב\"כ כנ\"ל.\n<b>אך</b> הענין ידוע שזהו כמשל היחוד דאיש ואשה שמולידי' ולד דידוע דעיקר מהות הולד נעשה מן האשה כמ\"ש אשה כי תזריע<sup data-n=\"431\">423</sup> וילדה זכר הרי מזרע מ\"ן דאשה נולד הולד כמ\"ש כי תזריע וילדה כו', אך א\"כ היתה האשה מולדת בלא זכר והאמת הוא דעיקר התולדה דולד בא מן האיש שמזריע טפה במעי הנוק' ומצטייר שם ע\"י המ\"ן דנוק' כמו הזריעה בארץ שבלא זריעה לא תצמ[י]ח כלום<sup data-n=\"432\">424</sup> ואיך א' אשה כי תזריע וילדה דמשמע הל' דזרע האשה הוא העיקר שמוליד הולד. אך הנה ידוע דשניהם אמת וכמו שא' אשה מזרעת תחלה<sup data-n=\"433\">425</sup> יולדת זכר כו', דהנה חומר הולד נעשה מזרע האשה דוקא וכמו שא' דאודם<sup data-n=\"434\">426</sup> דנוק' (שנק' מ\"ן שהוא כמים אדומי'<sup data-n=\"435\">427</sup> ) שממנו בשר<sup data-n=\"436\">428</sup> וגידים<sup data-n=\"437\">429</sup> כו', הרי עו\"ב<sup data-n=\"438\">430</sup> הולד שהוא הגשם והחומר נעשה",[["422","414","<b>עד שהביאותיו. . כו' ולחדר</b>: שה\"ש ג, ד [ושם: אמי ואל חדר]."],["423","415","<b>דתשב\"כ שנק' ספר. . תושבע\"פ. . סיפור</b>: ראה ס\"י בתחלתו. מאמרי אדה\"א בראשית ע' יז. וש\"נ. שמות ח\"א ע' עג. תו\"ח ויצא קסה, א ובהערה 12. לקמן יב, ד. פ' וארא ע, ב בשם הזהר. בא צה, ד. קכח, ג. תצוה שסז ד."],["424","416","<b>כמשי\"ת</b>: יא: כמשי\"ת). יזיח: (כמשי\"ת)."],["425","417","<b>על</b>: יאיזיח: שכל."],["426","418","<b>מנלן א' קרא</b>: ראה פסחים סא, סע\"א. סה, רע\"א. ועוד."],["427","419","<b>של מעשה</b>: שם: המעשה של."],["428","420","<b>ועשו להם ציצית</b>: שלח טו, לח."],["429","421","<b>אין מורין מתוך המשנה</b>: ראה סוטה כב, א."],["430","422","<b>כמשי\"ת</b>: כה: ליתא. ז: כמשי\"ת). יח: (וכמשי\"ת)."],["431","423","<b>אשה כי תזריע</b>: תזריע יב, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תר. וש\"נ. תו\"ח נח עב, א ובהערה 2. לקמן פ' תשא שפד, א. ויקהל תכד, ג."],["432","424","<b>כמו הזריעה. . כלום</b>: ב: (כמו הזריעה. . כלום)."],["433","425","<b>אשה מזרעת תחלה</b>: נדה לא, א."],["434","426","<b>דאודם. . שממנו בשר</b>: ראה נדה שם."],["435","427","<b>כמים אדומי'</b>: בדיאיבטז: כמו אדמומית. זיח: כבפנים."],["436","428","<b>בשר</b>: דיא: עור ובשר."],["437","429","<b>וגידים</b>: יא: (גידי'). ראה לקמן ט, ד. שפד, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רכ. מאמרי אדה\"א ויקרא ח\"א ע' שנו. בראשית ע' תעה ובהנסמן בהנ\"ל. שער האמונה פא, ב ובהערה 10."],["438","430","<b>עו\"ב</b>: עור ובשר."]]],[2300540754,"מזרע האודם שלה וזהו כי תזריע וילדה כו' אשה מזרעת תחלה כו', ואמנם בלא זרע הזכר לא תוליד מזרעה כלום כי עיקר כח המוליד שיש במ\"ן שלה אינו רק מכח טפת הזכר שהוא עצם הזריעה כזריעה בארץ ממש רק שהטפה דדכר תסרח ותקלט והי' כלא הי' כחטה שתרקב ותוקלט בארץ כו', ועכ\"ז בקליטה זו דמ\"ד עושה כח המוליד במ\"ן ומברר היטב למ\"ן והוא שנותן במ\"ן כח הבירור שיוברר בין טוב ורע והיינו שנברר מן המ\"ן הטוב ומובחר ע\"י המ\"ד שמזה עיקר פנימי' הצורה של הולד וגם החומר מן האודם שהוא מ\"ש עו\"ב תלבישני וכגבינה תקפיאני<sup data-n=\"439\">431</sup> <span data-k=\"pg\">יג</span> ּ שזהו כמו המחבץ כידוע שהוא מה שמחבץ ומברר בחלב ונתקבץ המובחר שבה והשאר הן פסולת ונק' נסיובי דחלבא<sup data-n=\"440\">432</sup> מי חלב, וזהו כגבינה תקפיאני שנקפה המ\"ן ונוצר בו הולד בצורה וחומר מעצמו' ובשר וגידי' כו'. ואך הגם שכח הבירור וגם כח התולדה בא רק מן המ\"ד שזהו מן הברור שבטפת דכר כו', מ\"מ מה שמתפשט הולד ומתגדל ברמ\"ח אברי' ומצטייר בצורה וחומר עד שיגדל גם בחיצוני' כשערות וצפרניי' הכל הוא מבחי' המ\"ן דוקא שמגדל ומצמיח הולד ועושה בו התפשטו' בכל אבר ואבר בפרט והוא האודם דנוק' שממנו בשר וגידים כו'. וזהו אשה דוקא כי תזריע כו' ע\"י כח המשכת מ\"ד וילדה שלידה זו הוא בגמר צמיחת הולד בט\"ח שיוצא לאויר העולם במהות ברי' בפ\"ע, משא\"כ בבטן אמו לא נק' ברי'<sup data-n=\"441\">433</sup> בפ\"ע, אבל עיקר מציאות תולדתו בבטן הוא בא מכח מ\"ד שנמשך במ\"ן (ולכך הבן נק' ע\"ש האב דוקא שהולידו לעצם כח הולד וזהו לבית אבותם<sup data-n=\"442\">434</sup>, ובמ\"ן הוא שנצמח ונגדל מאין ליש מהעלם לגילוי כמו מציאות חדש ממש כחטה הזרוע בארץ שתורקב לגמרי ותצמיח הארץ מחדש וכמ\"ש והולידה<sup data-n=\"443\">435</sup> כו'). ונמצא דשניהם אמת דמהשפעת טפת הדכר יבא עיקר ראשית הסיבה להתהוות הולד (כי רוח יזרעו<sup data-n=\"444\">436</sup> ) וכולל בהעלם ותמצית כל מה שיבא בבחי' התפשטו' בגילוי [בצורה וחומר] בפרטות, וגם זהו כמחבץ שמברר במ\"ן שממנו הבשר כו' עד שפסולת המ\"ן ממנו השליא<sup data-n=\"445\">437</sup>, אך עכ\"ז מקום הבירור והגידול והצמיחה דולד מאין הרוחני לגשם בהתפשטו' בחידוש גמור זהו במ\"ן דנוק' בט\"ח שמתגדל ומתפשט [ל]היות במציאות בריה בציור אדם כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן במה שנק' תשב\"כ ושבע\"פ בשם אב ואם כנ\"ל, דהנה ידוע שבאותיות דתושב\"כ מאיר מאור",[["439","431","<b>עו\"ב תלבישני וכגבינה תקפיאני</b>: חיבור שני כתובים איוב י, יא. י. ראה מאמרי אדה\"א ויקרא שם. תו\"ח תולדות קמח, ג ובהערה 48."],["440","432","<b>נסיובי דחלבא</b>: פסחים מב, א."],["441","433","<b>בבטן אמו לא נק' ברי'</b>: ראה גיטין כג, ב."],["442","434","<b>לבית אבותם</b>: במדבר א, ב. ועוד."],["443","435","<b>והולידה</b>: ישעי' נה, י."],["444","436","<b>כי רוח יזרעו</b>: הושע ח, ז. ראה גם ביאוה\"ז נח ה, ד."],["445","437","<b>שפסולת המ\"ן ממנו השליא</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תפד. וש\"נ. שה\"א פא, ב ובהערה 12. לקמן פ' תצוה שסו, א. תשא שפד, א."]]],[2300540766,"דח\"ע דעצמו' אוא\"ס שנק' חכים<sup data-n=\"446\">438</sup> כו' והארה והמשכה זו באה בהעלם מעצמו' דח\"ע שגם החכ' מאין תמצא<sup data-n=\"447\">439</sup> והן האותיות כו' שהן עצמיי' ממש, ואמנם זהו כמשל ודמיון השפע מ\"ד דאיש שהוא כח ההעלם ועצמי דולד ולא בגילוי וממנו נמשך כח הבירור במקבל שהוא מ\"ן דאשה כנ\"ל. כך הוא עד\"מ זה בח\"ע דתושב\"כ שנמשך לח\"ת דתושבע\"פ דכל מה שיש כח במקבלי' שהן חכמי תושבע\"פ לדרוש בדיני התורה בפרטו' בכל המדות הידועי' ובאותיות וגם בתגין כמו ר\"ע הי' דורש<sup data-n=\"448\">440</sup> על כל קוץ תלי תלים של הלכות וכה\"ג הכל בא מכח דח\"ע שנמשך בח\"ת, כמ\"ש בזהר ע\"פ חכמות בחוץ<sup data-n=\"449\">441</sup> דח\"ע אתמשך בח\"ת שהוא חכ' שבדיבור שנק' חכ' בסוף שמקבל מחכ' בראש<sup data-n=\"450\">442</sup> כו', וכמ\"ש תנו עוז לאלקי'<sup data-n=\"451\">443</sup> שהוא שם ב\"ן<sup data-n=\"452\">*444</sup> דח\"ת שנק' תושבע\"פ אימא תתאה או בבינה אימא עילאה כידוע, וכמ\"ש חגרה בעוז מתני'<sup data-n=\"453\">444</sup> בעוז דתושב\"כ שנק' ח\"ע דאור אבא וח\"ס וכה\"ג והיינו מבחי' מ\"ה דח\"ע דמשה כמ\"ש מה שמו מה שם בנו כו', וראי' לזה ממ\"ש תורה צוה לנו משה דוקא, דגם מה שנמסר הלכו' בע\"פ שלא נכתב בתושב\"כ ציוה לנו משה בע\"פ בהל\"מ וכה\"ג גם בכל מה שתלמיד ותיק עתיד לחדש דין והלכה במשנה ותלמוד ניתן למשה בסיני ומשה ציוה לנו כו', לפי שכח מה דח\"ע דמשה שגנוז בתושב\"כ הוא שנמשך גם בדיבור בע\"פ בח\"ת דתושבע\"פ מטעם הנ\"ל, וזהו כמו שבחי' מ\"ד נמשך למ\"ן ליתן בו כח הבירור שמקום הבירור בגילוי וכח הגידול ותולדה וההתפשטו' הרי הוא מה שבחכ' שבתו' שבע\"פ מתפשט לפרטי דינים בגילוי גמור בכל פרטי מעשה המצות שנזכרים בתושב\"כ בקיצור ובהעלם ותמצית שגנוז בצירופי אותיות המועטו' שבכל מצוה ומצוה והיינו כמו <span data-k=\"pg\">28</span> ּ בחי' המ\"ן דנוק' שמגדל הולד ברמ\"ח אברים ונתהוה ברי' מאין ליש בצו\"ח שלא הי' ניכר כלל [ב]מ\"ד רק בהעלם גדול כו'. וזהו שנק' חדר הורתי שהוא כהריון הולד בבטן האם שמתגדל ומתפשט ומתברר בין פנימי' לחיצוני' כנ\"ל, כך בו\"ס משנה מתברר כל פרטי הדינים להבדיל ולהורות בין טמא לטהור ובין אסור ומותר וכשר או פסול בכל פרטי פרטיות דוקא שבאופן זה יהי' טמא או טהור כהלכות נגעים ואהלות בפרטו' שלא נודע בתושב\"כ כלל, אע\"פ שנז' כללותו כשאת וספחת<sup data-n=\"454\">445</sup> כו' לא ידע הכהן לטהר או לטמא בפרטו' איך ומה רק בדיני הנגעים ואהלות וכל ס' טהרות שמפורש במשניות הערוכות לפנינו שיש מהן בקבלה איש מפי איש עד משה שציוה",[["446","438","<b>חכים</b>: נסמן לקמן יא, ג הערה 505."],["447","439","<b>החכ' מאין תמצא</b>: איוב כח, יב."],["448","440","<b>ר\"ע הי' דורש</b>: מנחות כט, ב. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תע. וש\"נ."],["449","441","<b>חכמות בחוץ</b>: משלי א, כ. ראה זהר תולדות קמא, ב. מאמרי אדה\"א בראשית ע' קכג. וש\"נ."],["450","442","<b>חכ' בסוף. . בראש</b>: נסמן לקמן פ' בא צח, ד."],["451","443","<b>תנו עוז לאלקי'</b>: תהלים סח, לה. ראה פע\"ח (שער התפלה) ש\"א, פ\"ז. (שער הק\"ש) ש\"ח, פי\"ב. מאמרי אדה\"א בראשית ע' קלח. וש\"נ. דרושי חתונה ח\"א ע' קנג."],["452","*444","<b>לאלקי' שהוא שם ב\"ן</b>: נסמן לקמן יט, ג."],["453","444","<b>חגרה בעוז מתני'</b>: משלי לא, יז."],["454","445","<b>כשאת וספחת</b>: תזריע יג, ב ואילך."]]],[2300540778,"לנו ויש שנדרשי' ממקראות וע\"פ המדו' בק\"ו וגז\"ש כו', ועכ\"פ הרי נתחדשו הלכות אלו מן ההעלם לגילוי בחידוש גמור כמו מאין ליש ממש כולד שנצמח ונגדל בט\"ח ממ\"ן דנוק' כנ\"ל, וכן בסדר קדשים בקרבנות הכתובי' בפ'<sup data-n=\"455\">446</sup> מתבאר כל פרטי הדינין שבהן איך שיבאו למעלה<sup data-n=\"456\">447</sup> כמו במס' זבחים ומנחות כו', והעיקר מה שנבררו ונתלבנו ההלכות דמשנה וברייתא ע\"י הפלפול בתלמוד שזהו מקום הבירור כמו מצרף לכסף שמצרף ומלבן כו', כך בחכמה שבתושבע\"פ מתברר ומתלבן כל הלכה שנק' ליבון הלכתא (כמו ליבון וצירוף הולד בבטן שנבדל החיצוני' מן הפנימי' (ואוכל מה שאמו אוכלת<sup data-n=\"457\">448</sup> כו' שזהו המ\"ן דנוק' כו' (אך זהו בקטנות דעיבור כמו שמלמדי' לולד כל התורה כולה<sup data-n=\"458\">449</sup> כמ\"ש מי יתנני כירחי קדם<sup data-n=\"459\">450</sup> כו', ואח\"כ נולד כברי' בפ\"ע בגידול ימי היניקה כמ\"ש מי יתנך כו' יונק שדי אמו<sup data-n=\"460\">451</sup> וזהו פנימי' התורה שיתגלה במשיח כמ\"ש במ\"א) (וזהו שא' בכמה דוכתי משה שפיר קאמרת<sup data-n=\"461\">452</sup> שמבורר [הדבר] הלכה זו כאלו אמרה משה בע\"פ כמו תורה ציוה לנו שנמשך מכח הח\"ע (ששרשו ממ\"ע<sup data-n=\"462\">453</sup> וא' בו וגם דלה דלה לנו<sup data-n=\"463\">454</sup> ממ\"ח שבעומק הבאר שהוא תושבע\"פ כו') (ובזה יובן מארז\"ל [ב]מה שא' שעלה משה למרום<sup data-n=\"464\">455</sup> וראה שהקב\"ה קושר כתרים (שהן תגין<sup data-n=\"465\">456</sup> ) לאותיות א\"ל עתיד תלמיד תלמידך לדרוש כו' וחזר לאחוריו וראה ר\"ע דורש על כל קוץ כו' והרי נעלם ממשה כל מה שדרש ר\"ע בתושבע\"פ (דכולהו סתימא' דמתני' אליבא דר\"ע<sup data-n=\"466\">457</sup> וכל המשנה מיוסדת מתלמידיו ר\"מ ור\"י ור\"ש כו'), והיינו לפי שבתושבע\"פ בחי' מל' מתחדש ומתרבה לאין שיעור יותר מעצם ההשפעה דמ\"ד דאותיות דתושב\"כ, רק עכ\"ז כח הבירור והגידול הזה בא מבחי' ח\"ע דמשה ולכך נתקררה דעתו כששמע שאומ' הל\"מ כו' (ולפי שבינה יתירה ניתנה באשה<sup data-n=\"467\">458</sup> יותר מבאיש כו' (וכנ\"ל בענין א\"ח עט\"ב כו') דאו\"ח עולה למעלה מאו\"י כו' (וזהו<sup data-n=\"468\">459</sup> שא' וכי זו<sup data-n=\"469\">460</sup> תורה כו' א\"ל שתוק כך עלה במח'<sup data-n=\"470\">461</sup> לפני, משום דעמל תורה בא מביטול היש לאין במס\"נ בגוף דוקא כמ\"ש אדם כי ימות באהל תורה שזהו כמו ר\"ע וחביריו, וה' ממית ומחיה שחיות זה בתחה\"מ שיעלו למעלה מעוה\"ב כנ\"ל וד\"ל).\n<b>ונמצא</b> מובן מכ\"ז בעיקר ההפרש בין תושב\"כ שנק' איש לתושבע\"פ שנק' אשה דכח הבירור בעצם וכח המוליד",[["455","446","<b>בפ'</b>: יא: בפרשה."],["456","447","<b>למעלה</b>: יזיח: למעשה."],["457","448","<b>ואוכל מה שאמו אוכלת</b>: נדה ל, ב."],["458","449","<b>שמלמדי'. . התורה כולה</b>: נדה שם."],["459","450","<b>מי יתנני כירחי קדם</b>: איוב כט, ב."],["460","451","<b>מי יתנך. . אמו</b>: שה\"ש ח, א [ושם: אמי]. ראה גם לקמן פ' בשלח רלו, ד."],["461","452","<b>משה שפיר קאמרת</b>: שבת קא, ב. וש\"נ. ראה גם לקמן פ' יתרו רנג, ד. מאמרי אדה\"א בראשית ע' קלט. שע\"ת קה, א ובהערה 8."],["462","453","<b>משה. . ששרשו ממ\"ע</b>: נסמן לקמן מג, א."],["463","454","<b>וגם דלה דלה לנו</b>: שמות ב, יט. ראה גם תו\"ח ח\"ש קלז, ג."],["464","455","<b>שעלה משה למרום</b>: ראה מנחות כט, ב. מאמרי אדה\"א במדבר ח\"ב ע' תקמא."],["465","456","<b>שהן תגין</b>: ראה רש\"י שם ובשבת פט, א."],["466","457","<b>דכולהו. . אליבא דר\"ע</b>: ראה סנהדרין פו, א. רש\"י מכות יז, א (ד\"ה זו דברי ר\"ע). בכורות ל, סע\"א (ד\"ה תיתי לי — יש מפרשים). מאמרי אדה\"ז תקס\"ה ח\"א ע' צא (נוסחא שני'). תו\"ח בראשית יג, ג. וישלח קצד, ד."],["467","458","<b>שבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. מאמרי אדה\"א שמות ח\"א ע' סה. וש\"נ (ובהנסמן בריש המאמר שם). תו\"ח לך פב, ג ובהערה 21. לקמן פ' ויקהל תיח, ב. תכד, ג."],["468","459","<b>כו' (וזהו</b>: אוצ\"ל: כו') וזהו."],["469","460","<b>וכי זו</b>: ראה מנחות שם. תיבת ”וכי\" מובא גם לקמן פ' בשלח ר, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תתטז. במדבר ח\"ב ע' תקלז וע' תקמא. תו\"ח וירא קב, א בהערה 4."],["470","461","<b>וכי זו. . כך עלה במח'</b>: ראה ביאוה\"ז בשלח מז, א. מאמרי אדה\"א במדבר שם."]]],[2300540789,"בעצם זהו במ\"ד (שהוא [ב]טפת יסוד אבא) ומקום המתברר בגילוי ומקום הצמיחה וריבוי ותולדת המציאו' בגילוי מן ההעלם והכח העצמי זהו במ\"ן דנוק', שז\"ש אשה כי תזריע (דאשדי מיין<sup data-n=\"471\">462</sup> לקיבלי' דמ\"ד וקולטת ומבררת כו'). <span data-k=\"pg\">יד</span> ּ והיינו ההפרש בין תושב\"כ שהוא כח עצם הדבר שבו כח הבירור בעצם, ובתושבע\"פ הוא מקום שבו מתברר ומתגלה מאין ליש בתוס' וריבוי בבירורי' שונים ומחולקי' כמו מן הכלל לפרט וגילוי כל דבר במהות ומציאות או\"כ צו\"ח כו' בהגדלה וריבוי גדול, אך כ\"ז בא מכח ח\"ע דתשב\"כ בתחלה כנ\"ל וד\"ל.\n[טו] <b>(ושרש</b> הענין הוא כמ\"ש במ\"א בענין אמר עם הספר<sup data-n=\"472\">463</sup> כו' דהחכ' נק' אמת כמו תתן אמת ליעקב<sup data-n=\"473\">464</sup> שהיא התו' שנק' אמת, לפי שהחכמה דתורה חכ' ברורה בעצם שאין בה נטי' לימין ושמאל כלל והוא קו היושר וכמ\"ש כי ישרים דרכי ה'<sup data-n=\"474\">465</sup> (ולכך נק' ס' הישר<sup data-n=\"475\">466</sup> ) דכח מ\"ה דחכ'<sup data-n=\"476\">467</sup> הוא בחי' נקודה שהוא נקודת האמת כמו שהוא בעצם הדבר ומהותו בפנימי' ותמצי' ומובחר דוקא, ולכך א' בכל מקום בזהר דבחכ' דוקא אתברירו<sup data-n=\"477\">468</sup> לפי שכל דבר הצריך בירור בין טו\"ר שמעורב שקר ואמת כפסולת בנקי אין בירור זה אלא בחכמה דוקא לפי שהוא בירור בעצם ע\"כ יש בו כח המברר לברר כל תערובות טו\"ר והוא בחי' האמת דחכ' שבכחו לברר בכל תערובו' טו\"ר כו' כיעקב איש תם<sup data-n=\"478\">469</sup> ואמת הי' מברר לרמאו' דלבן כמו אני חכמה שכנתי ערמה<sup data-n=\"479\">470</sup> כידוע. אבל מקום המתברר הוא בבינה<sup data-n=\"480\">471</sup> שהוא ההסבר והטעם לדבר חכ' באופני' שונים כמו מ\"ט דר\"פ כו' ונק' פנים מסבירות<sup data-n=\"481\">472</sup> לכאן ולכאן כו', זהו מקום וכלי שבו מתברר האמת מתוך השקר וטעות, כי יעיין בעיון השכל וסברא בהסבר הדבר יראה ויבין מה שהוא אמת ומה שיוצא מדרך האמת לטעות ושקר, וזהו כמו המצרף לכסף שבו מתברר הכסף ויוצא ונבדל ממנו כל סיג ופסולת בפ\"ע כך בשכל וטעם דבינה בפנימית שבה שהוא הנק' עיון יבורר השכל לאמיתתו ממש וכל זמן שלא יבורר יתבלבל הטוב ברע כו', כי יש פנים לומר טעם לאיסור וטעם להיפוך להתיר האסור. וזהו הפלפול בעיון שמקשה בסברות להפוך מאיסור להיתר ומטמא לטהור ומראה לו פנים וטעם או לטהר הטמא ולהתיר האסור בטוב טעם שלא כדין האמת כמו מט\"פ טמא ומט\"פ טהור<sup data-n=\"482\">473</sup> שבמ\"ט שע\"ב<sup data-n=\"483\">474</sup> עד שיברר היטב",[["471","462","<b>דאשדי מיין</b>: ראה זהר נח ס, ב. ביאוה\"ז שם ו, ב."],["472","463","<b>אמר עם הספר</b>: אסתר ט, כה. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תח. תו\"א מג\"א צו, ב. מאמרי אדה\"א נ\"ך ע' תק."],["473","464","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["474","465","<b>כי ישרים דרכי ה'</b>: הושע יד, י."],["475","466","<b>ס' הישר</b>: ראה יהושע י, יג ובתרגום ומפרשים שם. לקמן פ' בשלח קעג, ב. תרומה שיז, א. תצוה שלא, ג. תו\"ח בראשית מב, רע\"א. ח\"ש קלג, ד. מאמרי אדה\"א במדבר ח\"ג ס\"ע א'קיז ואילך."],["476","467","<b>דכח מ\"ה דחכמה</b>: ראה זהר (רע\"מ) צו כח, א. לד, א."],["477","468","<b>דבחכ'. . אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה־ שמות ח\"ב ע' שכא. לקמן פ' תשא שפד, ד."],["478","469","<b>כיעקב איש תם</b>: תולדות כה, כז."],["479","470","<b>אני חכמה שכנתי ערמה</b>: משלי ח, יב. ראה מאמרי אדה\"א דברים ח\"ב ע' תקלב. וש\"נ. תו\"ח נח עט, א ובהערה 1. לקמן פ' יתרו עדר, ב."],["480","471","<b>מקום המתברר הוא בבינה</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תח ואילך. תו\"ח נח מו, ד ובהערה 33."],["481","472","<b>בבינה. . ונק' פנים מסבירות</b>: ראה גם תו\"ח בראשית יד, ד ובהערה 43. לקמן פ' תצוה שסז, ג."],["482","473","<b>מט\"פ טמא ומט\"פ טהור</b>: ראה ירושלמי סנהדרין פ\"ד, ה\"ב. פס\"ר [פ' דעשה\"ד] פכ\"א, ו. הנסמן במאמרי אדה\"א במדבר ח\"א ע' רנ. תו\"ח בראשית יד, ג ובהערה 40."],["483","474","<b>שבמ\"ט שערי בינה</b>: ראה ר\"ה כא, ב."]]],[2300540800,"בטעמי' שבבינה להעמיד הדבר על אמיתתו בין טו\"ט ואו\"ה בלי נטי' כלל מן האמת, וזהו שנק' מקום המתברר שבו יעמוד על הבירור של אור האמת, אבל אור החכ' כמו שהיא נק' אמת מצד עצמו וא\"צ בירור כלל כמו שמכוין לאמיתי' הסברא והדין בלי עיון ופלפול כלל (כאשכולת שהן זוגו' הראשוני'<sup data-n=\"484\">475</sup> שהיו בבחי' או\"י דקו האמצעי שמבריח גם בחו\"ג דבינה בקו המשקולת בלי נטי' כלל וכלל מימין לשמאל [מ]טהור טמא כו' (וזהו אלו ואלו דא\"ח<sup data-n=\"485\">476</sup> כמו שהן בקו המשקולת דחכמה ודעת עצמו דמשה שמט\"פ טו\"ט נשקלי' גם הן מקו היושר. וזהו ג\"כ ענין הפלפול שבתלמוד שהוא ג\"כ ברור בלתי יוצא מקו היושר ואמת בהויו' דאו\"ר, רק שכל מה שהי' בברור בעצם [ב]זוגו' וכה\"ג מוציאי' זה בבירור דפלפול זה, שבפלפול זה דוקא הוא שיוצא אור האמת כמצרף לחכ' וכמו מים מסלע קשה כו' (ולכך כל התלמוד שלנו כסולת נקי' אף בקושיות המנגדי' יבאו לברר האמת (כי אלו ואלו כו') משא\"כ בפלפול אחר זולתו שיהפוך האמת לשקר והטוב לרע כנ\"ל). וכדוגמא דאין חכם כבעל הנסיון<sup data-n=\"486\">477</sup> בפו\"מ, דאין כל חדש בנסיון זה אחר שכבר הוברר השכל הזה רק שבנסיון הוברר אמיתתו ומ\"מ נודע בנסיון זה בגילוי ובבירור יותר אמיתי ובכל פרטי <span data-k=\"pg\">30</span> ּ חלקיו כמחודש מעיקרו וגם בתוס' גדול כצמיחה בארץ וכולד בבטן כנ\"ל (וכמו בנסיונות לאיש נאמן שיעמוד באמונתו בפו\"מ כאברהם שנמצא לבבו נאמן בנסיון כו' שמראה בירור אמיתתו יותר (וכן מס\"נ דר\"ע וחביריו על התורה כנ\"ל). וזהו איהו אמת בחכ' עילאה דתושב\"כ שמפני אמיתתו בעצם יש בו כח המברר לזולתו כמשה שבא לברר לישראל, ואיהי אמונה<sup data-n=\"487\">478</sup> תושבע\"פ שהוא מקום המתברר בגילוי ובתוס' מרובה ורק להוציא לאור האמת דח\"ע בדרשות שלהם דוקא באותיות ותגין, ונק' אמונה כאיש נאמן רוח שלא יטה מקו האמת בבירור שלו. וזהו לא תסור כו' אפי' על ימין שמאל<sup data-n=\"488\">479</sup> כמו בכל ביתי נאמן הוא<sup data-n=\"489\">480</sup> שזהו בתושבע\"פ כמ\"ש תורה צוה לנו כמו בעוה\"ב עצמו וכמו שרי מלוכה<sup data-n=\"490\">481</sup> כידוע וד\"ל).\n[טז] <b>וזהו</b> ששים המה מלכות ושמונים פלגשים כו', דהנה מבואר למעלה שבדרך כלל נמשך מח\"ע דתשב\"כ לח\"ת דתשבע\"פ (כמו שמחכ' בראש נמשך לח\"ת שהוא חכ' שבדיבור בפה) שזהו כיחוד איש ואשה משפיע ומקבל דוקא (וזה",[["484","475","<b>כאשכולת שהן זוגו' הראשוני'</b>: סוטה מז, א (במשנה)."],["485","476","<b>אלו ואלו דא\"ח</b>: עירובין יג, ב. ראה מאמרי אדה\"א נ\"ך ע' שלט."],["486","477","<b>דאין חכם כבעל הנסיון</b>: ראה עקידה פ' נח שער י\"ד ד\"ה [הקדמה] השלישית. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שעט. תו\"ח בראשית ג, א בהערה 1. לקמן פ' בא קיט, ב. בשלח קע, ד. קעג, ג."],["487","478","<b>איהו אמת. . ואיהי אמונה</b>: ראה זהר (רע\"מ) פינחס רל, א. בלק קצח, ב. לקו\"ת ואתחנן ה, רע\"ג. מאמרי אדה\"א ויקרא ח\"א ס\"ע צג ואילך."],["488","479","<b>לא תסור. . שמאל</b>: פ' שופטים יז, יא. ראה ספרי שם."],["489","480","<b>בכל ביתי נאמן הוא</b>: בהעלותך יב, ז. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תנט. וש\"נ. תו\"ח וישב רב, ב ובהערה 26. לקמן פ' וארא פא, א. בשלח קלז, ד. קצב, ב."],["490","481","<b>שרי מלוכה</b>: ראה גם לקמן פ' וארא פ, ד, בשלח קלז, ד. מאמרי אדה\"א שמות ח\"א ע' קע. וש\"נ."]]],[2300540810,"הי' ענין ב' הכרובים שבמקדש אצל הארון וכפורת שא' ופניהם איש אל אחיו דוקא כמ\"ש במ\"א בפ' תרומה<sup data-n=\"491\">482</sup> ). אך בדרך פרט נמשך מבחי' ו' מדות דח\"ע (שנק' ו\"ק דאבא<sup data-n=\"492\">483</sup> ) מכל מדה בפרט לו' מדות דמל' שנק' ח\"ת שהן ס' מלכות בו\"ס משנה, שבפרט יש י\"ס בכל מדה ע\"כ הן ששים מס' והן ס' מלכות דמתני' מלכתא שמקבל ממלכא עילאה שנק' מלך הכבוד העליון שהוא אור אבא (דכבוד גימ' ל\"ב<sup data-n=\"493\">484</sup> נ\"ח<sup data-n=\"494\">485</sup> שזהו כמו שהח\"ע מאין תמצא ממזל ונוצר דהכל תלוי במזל<sup data-n=\"495\">486</sup> אפי' ס\"ת בהיכל דבינה כו'). וכמ\"ש כי על כל כבוד חופה כנ\"ל. וכידוע דגם ששרש התורה אינו רק בחכמה כמ\"ש דאוריי' מח\"ע נפקת<sup data-n=\"496\">487</sup>, אבל לשון נפקת<sup data-n=\"497\">488</sup> הרי זה שיצאה בגילוי מהעלם דח\"ע והן בחי' המדות דח\"ע עצמו שמפני זה נק' תורה לשון הוראה<sup data-n=\"498\">489</sup> שמורה ומבדיל במדות דחו\"ג שלה לטמא ולטהר בכלל כמ\"ש להבדיל ולהורות<sup data-n=\"499\">490</sup> כו' (רק שהוראה זו בלי בירור כמצרף הנ\"ל בעיון דבינה דתשבע\"פ שמצד השכל מתברר האמת, אלא מצד בחי' הראי' דעין השכל שרואה את האמת כמו שאדם רואה לאור הנר (בל\"א ער זעט דעם אמת) כמו בעין הרואה (ובעיון השכל נק' ער פאר שטייט דעם אמת) (כמ\"ש במ\"א בענין איזהו חכם הרואה את הנולד<sup data-n=\"500\">491</sup> מה שעתיד להיות כרואה לאור, וכמו הערמומית של הערום ביותר כלבן הארמי שלא יכיר ויבחין בעומק המרמה שבהעלם גדול אף מי שיעמיק שכלו ודעתו לפקח בעיון היטב, רק ע\"פ ראיי' עין השכל שרואה גם בהעלם וחשך כאור שמאיר בחשך והוא רק נקוד' אור האמת שנגלה לגביו כל ערמה ושקר וכמו שחכם דמ\"ה<sup data-n=\"501\">492</sup> בראיי' עין השכל שנק' אור, רואה את הנולד להיות שנעלם מכל כך בבחי' האמת נדחה ממילא כל שקר וטעות, וזהו ותורה אור<sup data-n=\"502\">493</sup> בבירור דאמת וזה עצמו נמשך בעיון השכל במדות דתושבע\"פ לברר האמת כנ\"ל). והיינו שנק' ששים מלכות בו\"ס דמשנה דוקא משום דמתני' מלכתא שגוזר ואו' בעיון השכל שמברר לאמת שזה כשר וזה פסול זה אסור וזה מותר, כלומר דבר זה יוכל להיות תיקון והעלא' שיעלה למעלה ואינו אסור וקשור בק\"נ כמאכל היתר וכבהמה שטהורה וכשרה לקרבן שיעלה <span data-k=\"pg\">טו</span> ּ לריח כו', וזה אסור וקשור ביד החיצוני' ולא יוכל לעלות בקדושה האלקי' וכן זה כשר או פסול כדבר מלך שלטון שגוזר וכן יקום, שבתשב\"כ לא בא כל זה בגילוי בדיבור בדרך פרט לגזור אומר על אופן של הבירורי' דרפ\"ח כו'",[["491","482","<b>ופניהם איש אל אחיו. . בפ' תרומה</b>: תרומה כה, כ. ראה לקמן שטז, ב ואילך."],["492","483","<b>ו\"ק דאבא</b>: ראה גם לקמן פ' בשלח קצט, א. ריד, א. תצוה שנד, ב. ויקהל תלד, א. שעה\"י קכח, א ובהערה 22."],["493","484","<b>דכבוד גימ' ל\"ב</b>: זהר (רע\"מ) צו לג, א."],["494","485","<b>דכבוד. . ל\"ב נ\"ח</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["495","486","<b>דהכל תלוי במזל</b>: ראה זהר (אד\"ר) נשא קלד, א. דברים נחמדים ממהר\"ם שיף [בסוף מס' חולין] בתחלתן. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' קכז. שעה\"י קכז, ב. לקמן פ' בא פט, ב. קלא, א. בשלח רא, ב. ויקהל שצח, ד."],["496","487","<b>דאוריי' מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["497","488","<b>לשון נפקת</b>: ראה גם מאמרי אדה\"א בראשית ע' נב. וש\"נ. תו\"ח בראשית יד, ד."],["498","489","<b>תורה לשון הוראה</b>: ראה זהר מצורע נג, ב. חזקוני תולדות כו, ה. פרדס (שער אבי\"ע) שט\"ז, פ\"ג. מאמרי אדה\"ז תקס\"ד ע' סג. ש\"א צח, ב. מאמרי אדה\"א בראשית שם. וש\"נ. תו\"ח שם. לקמן פ' בשלח קעג, א. פקודי תנה, ג."],["499","490","<b>להבדיל ולהורות</b>: שמיני י, י [ושם: ולהבדיל]. יא."],["500","491","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. ראה תו\"ח נח מח, א. וירא קיד, ג. וראה גם ש\"א מ, א."],["501","492","<b>שחכם דמ\"ה</b>: בדיאיב: שחכ' דמ\"ה. זיז: שחכם ידמה."],["502","493","<b>ותורה אור</b>: משלי ו, כג."]]],[2300540819,"מק\"נ רק במדות דח\"ת דתושבע\"פ דוקא בא בגילוי בדיבור בפה לברר ולהבדיל בפרטו' בין טו\"ט ואו\"ה כו' (ויש בזה בחי' או\"פ ומקיף בלבוש ומקיף למקיף כמו בבית (כאו\"ה במאכל שהמאכל נהפך לדם וחיות בלב ומוח שזהו בחי' נר\"נ וחלק הטוב וכשר שבמאכלי' יעלה לקדושה שבכח המאכל הכשר ישבע לבו ויחזק דעתו ושכלו באוי\"ר בתפלה לעלות במס\"נ בכל לבו ונפשו בק\"ש ומצות ותורה, אבל במאכל אסור אף שיהפך לדם וחיות בלב ומוח יסתיר אור הנשמה אלקי' ולא יוכל לעלות בתו\"מ ותפלה כלל, וכן גזל במו\"מ לא יעלה למעלה שכל יגיע כפיו צ\"ל בנקיון מן הרע וגם תפלתו תועבה כמ\"ש ידיכם דמים מלאו<sup data-n=\"503\">494</sup> וגם לולב הגזול פסול<sup data-n=\"504\">495</sup> כו' וכך בלבוש כשעטנז וכה\"ג וכן בבית בלא מזוזה או בית גזול כו'). וכל בירור זה בפו\"מ הוא בא מבחי' ההעלם לגילוי כמו שבא הגזר ופס\"ד משרי המלוכה למעשה, שמפי המלך בעצמו לא יצא הרע והטוב רק ישלח לעיין במשפט בב\"ד וכאשר יגזרו כן יקום דבר מלך. וזהו ת\"ח<sup data-n=\"505\">496</sup> שנק' שרי מלוכה כמ\"ש ריב\"ז אני כשר לפני המלך<sup data-n=\"506\">497</sup>, וכן נק' למודי הוי' כמ\"ש וכל בניך למודי הוי'<sup data-n=\"507\">498</sup> שמקבלים משם הוי' שבתושב\"כ ועל ידם נחתך<sup data-n=\"508\">499</sup> כל דבר מל' למעשה, וכל זמן שלא יצא בדיבור בתושבע\"פ ע\"י המשנה דמתני' מלכתא (בחי' עקרת הבית [ו]א\"ח עט\"ב כנ\"ל) לא נעשה למעשה כלום וד\"ל. ונמצא מובן עכ\"פ מזה דעיקר הבירור שבחכ' [הוא בחכמה] עילא' דתושב\"כ מצד שתו' אור מבורר בעצם כנ\"ל, אך צריך שיומשך כח ועוז מאור דח\"ע בח\"ת שבדיבור בתושבע\"פ שהן בו\"ס משנה בטעמי' שבעיון השכל שגם בזה דוקא יבא הבירור של האמת בדרך פרט בכל הו' מדות דמל' שהן ס' מסכתות שנק' ס' מלכות ושמונים פלגשי' הן הברייתות (כמשי\"ת), כמו שהמלך ידור ויתייחד ביחוד תמידי במלכה כך נמשך מח\"ע לח\"ת בתמידות (שזהו בחי' פנים מאירות דתושב\"כ שנמשך תמיד לתשבע\"פ שנק' בחי' פנים מסבירות<sup data-n=\"509\">500</sup> כידוע<sup data-n=\"510\">501</sup>, שהרי א\"א לשום חכם מחכמי תושבע\"פ לחדש דין והלכה שלא יהי' לו ראי' מן המקרא או בקבלה מהל\"מ או בדרש שבמדות (רק עלמות אלו ההלכות שבאים בחידוש גמור שלא ע\"י משפיע כמשי\"ת<sup data-n=\"511\">502</sup>. ועכ\"ז ניתן הכח ורשות לחכמי תושבע\"פ לדרוש כרצונם ודעתם וכן יקום כמ\"ש לא תסור מן הדבר כו' אפי' מוטעי' ושוגגי'<sup data-n=\"512\">503</sup> כו' כידוע (וכנ\"ל דבינה יתירה ניתנה באשה כו' דא\"ח עט\"ב).",[["503","494","<b>ידיכם דמים מלאו</b>: ישעי' א, טו."],["504","495","<b>לולב הגזול פסול</b>: סוכה כט, ב. ראה גם תו\"ח מקץ רטז, ב."],["505","496","<b>ת\"ח</b>: זיח: ב\"ד."],["506","497","<b>אני כשר לפני המלך</b>: ראה ברכות לד, סע\"ב. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשטו ואילך. תקס\"ה ח\"א ע' קלא. מאמרי אדה\"א בראשית ע' לד וע' שנד. שמות ח\"ב ע' שלב. תו\"ח וישב רב, ב. לקמן פ' וארא פא, א. משפטים רצב, ג."],["507","498","<b>וכל בניך למודי הוי'</b>: ישעי' נד, יג. ראה גם לקמן יב, ב."],["508","499","<b>נחתך</b>: יאיח: נחתם."],["509","500","<b>פנים מאירות דתושב\"כ. . לתשבע\"פ. . פנים מסבירות</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' סה. דברים ח\"ד ע' א'רד ובהנסמן בהנ\"ל. לקמן פ' תרומה שיז, א. תצוה שסז, ד. ויקהל תכד, א. תמא, א."],["510","501","<b>כידוע</b>: אוצ\"ל: כידוע)."],["511","502","<b>כמשי\"ת</b>: דזיא: כמשי\"ת). טזיז: (כמשי\"ת)."],["512","503","<b>אפי' מוטעי' ושוגגי'</b>: ראה ר\"ה כה, א."]]],[2300540828,"[יז]<sup data-n=\"513\">504</sup> <b>אך</b> הנה באמת יש להבין איך יוכל להיות המשכה וירידה גדולה כזו מבחי' אור דח\"ע שבאותיות דתשב\"כ שהוא בפנימי' דחכ' דא\"ס עצמו שנק' חכים ולא בחכ' ידיעא<sup data-n=\"514\">505</sup> כלל (שכבר הוברר בחש\"מ הקדומה כמ\"ש ואהי' אצלו<sup data-n=\"515\">506</sup> כו') למקום נמוך כזה שהוא בבירור דח\"ת שבא בעיון ופלפול בטעמי' וסברות לדון הלכה למעשה בין טו\"ר בפו\"מ כנ\"ל (כמו חכם גדול שהוברר אצלו חכ' עמוקה לעצמו, איך ישפיל חכ' כזו במעשה מלאכה גשמי' שאינו אלא שכל שבעשי' גשמי' לעבוד עבודה גשמי' כעובד אדמה ומתקן בכלי אומנות כמו לארוג וכה\"ג). ואמנם הנה ידוע דגם מה שירד אור דתוה\"ק מעצמו' ופנימי' חכמתו ית' שזהו כמו בחי' עה\"ח שכולו טוב וחיים (כעדן דעוה\"ב) למטה באותיות דתושב\"כ כמו <span data-k=\"pg\">32</span> ּ ואתא מרבבות קדש במ\"ת שהאיר פניו בא' אנכי<sup data-n=\"516\">507</sup> כו' בקול ודיבור ממש ובא בהתלבשו' בעה\"ד טו\"ר לברר ולהבדיל ולהורות בין טו\"ט כו', שזהו שפלות וירידה עצומה כמו מאיגרא רמה כו'. אך בהכרח לומר בכל סיבת הירידה מעליון לתחתון מגבוה גבוה לנמוך ביותר שהוא ע\"י בחי' ממוצע<sup data-n=\"517\">508</sup> דייקא שנחשב מבחי' האחרונה שבעליון ונעשה<sup data-n=\"518\">*509</sup> ראש בתחתון כו' (כמו הכתר שנק' ממוצע<sup data-n=\"519\">509</sup> בין עצמות המאציל לנאצלים שנחשב מבחי' האחרונה שבעצמו' וראש ומקור לנאצלים כידוע). וכך הוא בבחי' הח\"ע שרש נשמת משה דבמשה א' כי טוב הוא בטי\"ת רבתי מעה\"ח שכולו טוב כו', וממ\"ע משיתיהו שזהו מ\"ע דחכמה עילאה הקדומה הנ\"ל, ולכך נק' שוש' דמלכא<sup data-n=\"520\">510</sup> שהי' ממוצע להביא ולחבר העליון בתחתון שהוא להיות גילוי אוא\"ס בח\"ע דתורה אור (כמו שלמעלה גם בתוה\"ק מתחבר מעצמו' השעשועי' בחש\"מ כמ\"ש ואהי' אצלו כו') למטה בעה\"ד טו\"ר בי' הדברות שהן כללות דתושב\"כ<sup data-n=\"521\">511</sup>, וכמו משה<sup data-n=\"522\">512</sup> ידבר<sup data-n=\"523\">*512</sup> והאלקים יעננו בקולו של משה כו', עד שמאיר ונמשך בכאו\"א מישראל בקראו באותיות דתושב\"כ כקורא בשמותיו ממש, שז\"ש שיקראוהו באמת דתורה<sup data-n=\"524\">513</sup> כידוע. וכך הוא עד\"ז יש בחי' ממוצע להביא ולהמשיך מח\"ע דתושב\"כ לח\"ת [ד]תשבע\"פ בו' מדות דמל' שהן ו\"ס משנה<sup data-n=\"525\">514</sup> בכלל כנ\"ל, והן הנה נשמות התנאי' חכמי המשנה בכלל ובפרט כר\"ע ותלמידיו וחביריו שקיבלו מריב\"ז<sup data-n=\"526\">515</sup> ע[ד] הלל ושמאי שנחלקו לב' כיתות<sup data-n=\"527\">516</sup>, שנכללי' כולן בבחי'",[["513","504","<b>[יז]</b>: ב: לא רשם כאן פרק."],["514","505","<b>חכים ולא בחכ' ידיעא</b>: ראה ת\"ז בהקדמה (יז, ב). לקמן פ' יתרו רסז, רע\"א."],["515","506","<b>ואהי' אצלו</b>: משלי ח, ל."],["516","507","<b>אנכי</b>: יתרו כ, ב."],["517","508","<b>הירידה מעליון לתחתון. . ממוצע</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' רלג. ח\"ב ע' תמד וע' תקפה. וש\"נ."],["518","*509","<b>ונעשה</b>: יאיזיח: ונק'."],["519","509","<b>הכתר שנק' ממוצע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תס. בראשית ע' שפא. ש\"א ע, ב. לקמן פ' בא פט, ג."],["520","510","<b>משה. . שוש' דמלכא</b>: ראה זהר (רע\"מ) ויקרא כ, א. מצורע נג, ב. (רע\"מ) שופטים ערה, ב. מאמרי אדה\"ז תקס\"ז (ע' סו). ע' עא. ע' עז. תו\"א תצוה קיא, א. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שכז. לקמן פ' וארא עב, ג. בשלח קנה, ג. יתרו רסג, ב."],["521","511","<b>בי' הדברות. . דתושב\"כ</b>: ראה תניא פל\"ו. פנ\"ג. לקמן פ' יתרו רנג, ד ובהנסמן שם. וראה גם רש\"י משפטים כד, יב. ירושלמי שקלים פ\"ו, סה\"א. זהר יתרו צ, ב."],["522","512","<b>משה ידבר</b>: יתרו יט, יט. ברכות מה, א."],["523","*512","<b>ממוצע. . משה ידבר</b>: ראה גם לקמן פ' תצוה שכג, ג. וש\"נ."],["524","513","<b>שיקראוהו באמת דתורה</b>: תהלים קמה, יח. ראה ירושלמי ר\"ה פ\"ג, ה\"ח. סידור שחרית נו, א. מאמרי אדה\"א דברים ח\"א ע' קכג. וש\"נ. תו\"ח נח מט, ד ובהערה 41. וישב רא, ב. לקמן פ' בשלח קסח, ב. תרומה שיג, א. תצוה שמא, ב. שע, ד."],["525","514","<b>בו' מדות דמל' שהן ו\"ס משנה</b>: ראה פרע\"ח שער הנהגת הלימוד (שנט, א). טעמי המצות להאריז\"ל ואתחנן ד\"ה בענין מקרא משנה תלמוד. לקמן טז, ד. פ' משפטים רצב, ג."],["526","515","<b>כר\"ע ותלמידיו וחביריו שקיבלו מריב\"ז</b>: כ\"ה גם בהכת\"י. וראה אבות פ\"ב, מ\"ח (ובמפרשים). ובסמוך בפנים."],["527","516","<b>הלל ושמאי שנחלקו לב' כתות</b>: כנראה כוונתו כמ\"ש לקמן טו, רע\"ג: ”שמאי והלל שהיו מחולקים בקצת דברים ותלמידיהם אחריהם שנחלקו ברוב דברים\" אלא שקיצר בלשונו."]]],[2300540837,"הממוצעי' להמשיך אור דח\"ע דמשה שבתושב\"כ להיות נדרש על כל קוץ כו' שזהו במדו' דח\"ת דהיינו או\"ה כשר ופסול חייב זכאי טו\"ט שהן כללו' דו\"ס משנה שפוסקי' ההלכות בפרטו' כל דיני המצות הכתובי' בתושב\"כ כנ\"ל. וזה הכח ועוז מה שיש ביכולתם לדרוש על כל אות ואות ותגי' דתושב\"כ ולכוין לאמיתי' הבירור בפרטות בתערובות הקשה דטו\"ר בכל דיני או\"ה וטו\"ט כנ\"ל, זהו בהכרח בא מבחי' כח העליון מחכ' שבמל' שנקרא חכ' שבדבור מצד ששרשן למעלה בח\"ע דמ\"ה דמשה שנמשך מאורו בנשמו' התנאי' האלה בעלי המשנה כר\"ע ותלמידיו עד רבינו הקדוש, שכל מה ששנו חכמים אלה במשנתם קב ונקי כסולת ברורה אף שחלוקי' בדיעו' לטמא ולטהר כמו ר\"מ מטמא<sup data-n=\"528\">517</sup> וחכמים כו' ובין יחיד ליחיד אלו ואלו דא\"ח כו' שניתן מרועה א'<sup data-n=\"529\">518</sup> זה משה, שנמשך מח\"ע לח\"ת שזה יטמא וזה יטהר ככף המאזנים שמעמידי' בשיקול א' ע\"י קו המשקולת וקו המשקולת סובלם ומכריע לימין או לשמאל כו', כך מט\"פ טו\"ט וכה\"ג שנשקלים ע\"פ חכמי התנאים המוזכרים בו\"ס משנה ע\"י קו המשקולת דדעת עליון דמשה שמאיר ונמשך בהן<sup data-n=\"530\">519</sup>, ומשם ימצא בהן כח הבירור שלהם להורות בפרטו' בכל דין והלכה לפי שהן הממשיכי' מח\"ע לח\"ת בדרשו' שלהם דוקא כנ\"ל וד\"ל (ואין זה פלא כ\"כ כי כבר הי' לעולמי' שנאצל מרוחו של משה על ע' הזקנים כמ\"ש ויאצל כו' עד ותנח עליהם<sup data-n=\"531\">520</sup> הרוח ויתנבאו כו', הרי הי' אור [נשמתם] נאצל מאור נשמת משה ממש והן ע' סנהדרין ב\"ד של משה (כמו ב\"ד של מעלה דכתי' וה' הוא וב\"ד<sup data-n=\"532\">521</sup> כו'). והרי א' משה קיבל תורה<sup data-n=\"533\">522</sup> מסיני ומסרה ליהושע ויהושע לזקנים וזקנים לשופטי'<sup data-n=\"534\">523</sup> ושופטי' לנביאי' כו' עד שמעון הצדיק הי' משירי אכה\"ג מסר לזוגות עד הלל ושמאי ותלמידיהם כמו ר\"ע ותלמידיו<sup data-n=\"535\">524</sup> עד רבי הוא שסידר המשנה<sup data-n=\"536\">525</sup> מפי כל התנאי', שאין בכל הילוך האור ושפע החכ' דתורה אור האלקי' ממשה עד רבי שום שינוי המהות כלל כמו בע' הזקנים שקיבלו מרוחו של משה ממש מאחר <span data-k=\"pg\">טז</span> ּ שזהו כמו שנמסר מיד ליד שאין בזה שינוי כלל, וראי' לזה ממה שגזר או' שכל ב\"ד וב\"ד חשוב כב\"ד של משה, כמו גבי עובדא דר\"ג<sup data-n=\"537\">526</sup> שגזר על ריב\"ח שיבא אליו במקלו ביו\"כ שחל להיות בחשבונו וקיבלו עליו לפני רדב\"ה וא\"ל אם אתה בא להרהר אחר כל ב\"ד כו' עד",[["528","517","<b>ר\"מ מטמא</b>: כלים פי\"ט, ט. אהלות פ\"ו, ג. ועוד."],["529","518","<b>שניתן מרועה א'</b>: קהלת יב, יא ובתרגום ורש\"י שם."],["530","519","<b>דדעת עליון דמשה. . בהן</b>: ראה תניא פמ\"ב."],["531","520","<b>ויאצל. . ותנח עליהם</b>: בהעלותך יא, כה. כו [בדילוג]."],["532","521","<b>וה' הוא וב\"ד</b>: וירא יט, כד. ב\"ר פנ\"א, ב. ירושלמי ברכות פ\"ט, ה\"ה."],["533","522","<b>משה קיבל תורה</b>: אבות בתחלתה."],["534","523","<b>וזקנים לשופטי'</b>: ראה אבות דר\"נ פ\"א, ג ובמפרשים שם. רש\"י ומחזור ויטרי לאבות (ד\"ה ויהושע לזקנים)."],["535","524","<b>הלל ושמאי. . ר\"ע ותלמידיו</b>: ראה גם לעיל הערה 515."],["536","525","<b>רבי הוא שסידר המשנה</b>: רמב\"ם בהקדמתו ליד החזקה. ראה לקו\"ש אחרי (כרך יב) ע' 89 בהערה 35."],["537","526","<b>עובדא דר\"ג</b>: ראה ר\"ה כה, א."]]],[2300540846,"שא\"ל ר\"ע אלה מועדי הוי'<sup data-n=\"538\">527</sup> אשר תקראו אותם אתם כתיב אפי' מוטעי' כו', (ולכך גם מה שתלמיד ותיק כו', וכמ\"ש משה שפיר קאמרת כמשה ממש דאתפשטותי' דמשה מה שמו<sup data-n=\"539\">528</sup> בכל א' מן התנאי' וגם האמוראי' (וגם ברבנן סבוראי והגאוני' והראשוני' מפרשי הש\"ס עד האחרוני' שניתן להורות מחיבוריהם ונתפשט בישראל כש\"ע ואחרוני'). וכל זה מטעם הנ\"ל דכל התנאי' נק' בחי' ממוצעי' לחבר ולהמשיך מח\"ע דמשה בכל אשר ידרשו ויחדשו ההלכות בתושבע\"פ).\n[יח] <b>והנה</b> לפי שהנשמות של התנאי' והזוגות וכה\"ג הן בחי' ממוצעי' להמשיך מח\"ע לח\"ת כנ\"ל במשניות האלו בו\"ס זרעים מועד כו' זרעים בחסד שבמל' כו', ולכך נקראו התנאי' בעלי המשנה בשם תנאי' דוקא (ע\"ש המשנה שנק' מתניתן ותנא זהו ששונה המשנה כידוע) כמו שא' והאיתני' מוסדי ארץ<sup data-n=\"540\">529</sup>, אתנים אותיות תנאים<sup data-n=\"541\">530</sup> כידוע שהמה דוקא המייסדי' את הארץ שהוא תושבע\"פ מל' קרינן לה שנק' ארץ עילאה<sup data-n=\"542\">531</sup> למעלה, דתשב\"כ מן השמים ניתנה<sup data-n=\"543\">532</sup> בארץ וכמ\"ש ותשמע הארץ אמרי פי<sup data-n=\"544\">533</sup>, והארץ האירה מכבודו<sup data-n=\"545\">534</sup> מכבוד עליון דח\"ע דחכ' אדם תאיר פניו<sup data-n=\"546\">535</sup> במ\"ת שנמשך יסוד וחיזוק לארץ בחכ' שבדיבור שהוא תושבע\"פ דוקא (דאבא יסד ברתא<sup data-n=\"547\">536</sup> כמ\"ש ה' בחכ' יסד ארץ<sup data-n=\"548\">537</sup> כו', כמו שאנו רואים שצירופי אותיות הדבור נעשי' מאליהם<sup data-n=\"549\">538</sup> מאור החכ' הנעלמה שבראש שנק' קדמות השכל טרם שבא לגילוי אור התחכמות במוח, שהרי מיד ש[ה]חכ' שבראש מאין תמצא, ימצא בה ג\"כ אופן הגילוי שלה באותיות השכל שהוא מלובש במח' דבינה, והוא שרש התהוות הצירופי' שבדיבור ממילא לפי הנהגת מקור של גילוי אור החכמה שבראש דוקא. וזהו מצרף לחכמה<sup data-n=\"550\">539</sup>, דמצרף לצירופי אותיות שבדיבור שמחלק ומברר בפרטו' אינו רק ממקור דחכ' דאבא יסד ברתא שמצרף זה עצמו הוא לחכ' שבראש כמו לחכ' שבסוף כו', וזהו מגיד מראשית דחכ' אחרית<sup data-n=\"551\">540</sup> דחכ' ביחד כמ\"ש במ\"א). וזהו פיה פתחה בחכ'<sup data-n=\"552\">541</sup> שהוא ח\"ת דתשבע\"פ בדיבור (דמשנה שהוא ביצי'<sup data-n=\"553\">542</sup> כמתני' מלכתא שגוזר בדיבור כשגורס בגירסא בשיניו שמבדיל ומורה או\"ה כו\"פ כנ\"ל) ותורת",[["538","527","<b>אלה מועדי הוי'</b>: אמור כג, ד."],["539","528","<b>דמשה מה שמו</b>: נסמן לקמן מג, ג."],["540","529","<b>והאיתני' מוסדי ארץ</b>: מיכה ו, ב."],["541","530","<b>אתנים אותיות תנאים</b>: זהר (סבא) משפטים קי, ב. (רע\"מ) תצא רעח, ב. ת\"ז תכ\"א (מג, סע\"ב)."],["542","531","<b>מל'. . ארץ עילאה</b>: ראה זהר בראשית לט, ב."],["543","532","<b>דתושב\"כ מן השמים ניתנה</b>: ראה גם בבא מציעא נט, ב. תו\"ח לך צג, ג ובהערה 15."],["544","533","<b>ותשמע הארץ אמרי פי</b>: האזינו לב, א."],["545","534","<b>והארץ האירה מכבודו</b>: יחזקאל מג, ב."],["546","535","<b>דחכ' אדם תאיר פניו</b>: קהלת ח, א."],["547","536","<b>דאבא יסד ברתא</b>: נסמן לקמן מז, ב."],["548","537","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["549","538","<b>שצירופי אותיות הדיבור נעשי' מאליהם</b>: ראה אגה\"ק ס\"ה. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכב ואילך."],["550","539","<b>מצרף לחכמה</b>: נסמן לקמן מז, ב."],["551","540","<b>מגיד מראשית. . אחרית</b>: ישעי' מו, י."],["552","541","<b>פיה פתחה בחכ'</b>: משלי לא, כו."],["553","542","<b>דמשנה שהוא ביצי'</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"א בראשית ע' קפב־ שמות ח\"א ע' סד־ ויקרא ח\"ב ע' תתמב־ נ\"ך ע' קלט ובהנסמן בהנ\"ל. וראה גם מאמרי אדה\"א קונטרסים ע' תקלז ואילך."]]],[2300540855,"חסד על לשונה לפי שתורה של חסד דח\"ע דתושב\"כ על לשונה למעלה מלשונה, בהעלם במקיף דצרופי' שבהעלם בא בדיבור, דגם דפתיחה זו באותיות הדבור בתושבע\"פ הוא בא מאין ליש להביא דוקא במעשה בפו\"מ (ולא כאותיות דתושב\"כ שהן בהעלם דח\"ע כנ\"ל) בגילוי במא' פתוח<sup data-n=\"554\">543</sup> לגמרי בגזירת מלך, אבל שרש פתיחה זו הוא מן ההעלם דח\"ע שבראש שפותח הצנור דמקור החכ' שבראש במזל ונוצר אותיות צנור<sup data-n=\"555\">544</sup> (כמו פתח ר\"פ כו' שפתח הצנור<sup data-n=\"556\">545</sup> הנעלם דתעלומות ח\"ע שבתושב\"כ דהא בהא תליא מטעם הנ\"ל וכמשי\"ת (ומשה הי' כבד פה וכבד לשון<sup data-n=\"557\">546</sup> וא' בר\"מ כבד פה בתושבע\"פ וכבד לשון בתושב\"כ משום דהא בהא תליא דמקור הח\"ע שבראש הוא מקור דח\"ת שבדיבור, ולפי ששרש משה ממ\"ה דח\"ע<sup data-n=\"558\">547</sup> כמו שהיא בבחי' אין דכתר ממש דאפי' אור צח כו' אוכם הוא<sup data-n=\"559\">548</sup> ממש לגבי עה\"ע ונק' ירא בושת<sup data-n=\"560\">549</sup> כמ\"ש במ\"א וע\"כ הי' עניו מכל האדם<sup data-n=\"561\">550</sup> כו', לכך הי' ירידה <span data-k=\"pg\">34</span> ּ אצלו להיות בהמשכה מאין דח\"ע לגילוי בתושב\"כ ושבע\"פ, ומטעם זה עצמו א\"ל מי שם פה לאדם<sup data-n=\"562\">551</sup> כו' כמ\"ש במ\"א), וזהו וכל בניך למודי הוי' ורב שלום בניך שהן ת\"ח שעוסקי' בבנינו ש\"ע כידוע, והיינו כמו התנאי' בעלי המשנה שנק' מוסדי ארץ בחכ' שבדבור דתו' שבע\"פ להיות פיה פתחה בחכ' כו' שהן ראשי המדברי' בדיבור זה דח\"ת דמשנה לפי שממשיכי' מכח ועוז דח\"ע דתושב\"כ להיותם בחי' ממוצעי' כנ\"ל ע\"כ נק' למודי הוי' ל' נפעל שמקבלי' ונלמדי' משם הוי' שהוא שם מ\"ה דח\"ע שבראש. והיינו לפי שנק' בניך דהיינו כמו בן חכם שמקבל משרשו בח\"ע כמו כי אתה אבינו<sup data-n=\"563\">552</sup> ע\"כ הן למודי הוי' (ופי' הב' שמלמדי' וממשיכי' לשם הוי'<sup data-n=\"564\">553</sup> בח\"ע וח\"ת לפי ששרשם למעלה מח\"ע וח\"ת (כמשי\"ת). וזהו ורב שלום בניך<sup data-n=\"565\">554</sup> שמרבים שלום בפמשמ\"ע ובפמשמ\"ט<sup data-n=\"566\">555</sup>, דהיינו בחו\"ב דאצי' שנק' פמשמ\"ע ובפשמ\"ט בזו\"נ מדות ודיבור, לפי שכל ממוצע עושה שלום ומחבר מעליון לתחתון, כמו משה שהי' בחי' ממוצע להביא ולחבר לגילוי אא\"ס בח\"ע דתושב\"כ וכן מתושב\"כ לתושבע\"פ כמ\"ש תורה ציוה לנו כו' וכתי' בי' בכל ביתי נאמן הוא כנ\"ל. והארה זו דמ\"ה דמשה מתפשט בכל התנאים שממשיכים מח\"ע בדרשות שלהם בחכ' שבדיבור בתושבע\"פ",[["554","543","<b>במא' פתוח</b>: שבת קד, א. ראה גם לקמן פ' וארא פא, ג. בא צא, א. קכח, ב. בשלח קמג, ד. יתרו רסה, א. תצוה שמב, א. מאמרי אדה\"א שמות ח\"א ע' ריג. וש\"נ."],["555","544","<b>במזל ונוצר אותיות צנור</b>: תשא לד, ז [ושם נצר]. ראה מאמרי אדה\"א שמות ח\"א ע' קעב־ ויקרא ח\"א ע' רמג־ ח\"ב ע' תשעט־ דברים ח\"ג תשפח ובהנסמן בהנ\"ל."],["556","545","<b>פתח. . שפתח הצנור</b>: ראה הדרת מלך לזהר בתחלתו בשם הרח\"ו. אוה\"ח שם (א, ד) ד\"ה והרא\"ג כתב. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרנז נוסח א' [ושם: שפתח ציור בחכמ' סתימ']. לקמן פ' בא קלג, ב. מאמרי אדה\"א במדבר ח\"ה ע' א'תתסה [וראה הנרשם בריש המאמר שם ע' א'תתמג בהערה להבין — ד\"ה בסה\"מ תר\"ן]. בראשית ע' ה. דרושי חתונה ח\"ב ע' תקסד. דברים ח\"ד ע' א'תנו. וש\"נ."],["557","546","<b>ומשה הי' כבד פה וכבד לשון</b>: נסמן לקמן מז, ד."],["558","547","<b>ששרש משה ממ\"ה דח\"ע</b>: ראה גם לקמן יט, ב. מג, א הערה 5."],["559","548","<b>אור צח כו' אוכם הוא</b>: ראה ת\"ז ת\"ע (קלה, ב). מאמרי אדה\"א דברים ח\"ג ע' תתיא. וש\"נ. ח\"ד ע' א'תה. וש\"נ. ש\"א נז, ב. לקמן פ' בשלח קפח, ג. רכג, ד. ויקהל שפז, ד. פקודי תנד, א."],["560","549","<b>ירא בושת</b>: ראה ת\"ז בהקדמה (ה, ב). תכ\"ח. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע ל. וע' לא. ח\"ב ע' תקמט. לקו\"ת בלק סט, א. מאמרי אדה\"א בראשית ס\"ע לה ואילך. לקמן פ' בשלח קמב, א. קנד, ג. תצוה שכג, ג. שלב, ב."],["561","550","<b>עניו מכל האדם</b>: בהעלותך יב, ג."],["562","551","<b>מי שם פה לאדם</b>: שמות ד, יא. ראה גם לקמן מד, ב. מז, ד ואילך."],["563","552","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["564","553","<b>שמלמדי' וממשיכי' לשם הוי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רכ."],["565","554","<b>ורב שלום בניך</b>: המשך הכתוב וכל בניך (ישעי' נד, יג)."],["566","555","<b>שלום בפמשמ\"ע ובפמשמ\"ט</b>: סנהדרין צט, ב."]]],[2300540864,"ולכך נק' גם הם איתנים מוסדי ארץ עילאה דתושבע\"פ (כמו שא' אתם אפי' שוגגי' כו' כנ\"ל), כי פי' איתנים לשון כח וחוזק כמו איתן מושבך<sup data-n=\"567\">556</sup> כו' וכמו הראשי' בתושבי הארץ נק' איתני הארץ כמו משכיל לאיתן האזרחי<sup data-n=\"568\">557</sup> כו'. ופי' משכיל לאיתן דבבחי' איתן זה יש מבחי' כח המשכיל דח\"ע מקור הח\"ע וח\"ת כנ\"ל, כמו משכיל על דבר כו' שמפקח ומשכיל להתחכם לתקן כמו משכיל אל דל<sup data-n=\"569\">558</sup> כו' שהוא לתקן לשם ב\"ן שהוא מל'<sup data-n=\"570\">559</sup> בתיקון ובירור דעה\"ד טו\"ר ע\"י המשנה שמבדלת ומתקנת היטב לזרוק כל פסולת שיובדל הטמא ופסול וחייב כנ\"ל זהו נק' מוסדי ארץ שתצליח ותצמיח לכל פרי טוב הארץ להשביע [ל]כל חי מלחם הארץ כו' וכעובד אדמתו ישבע לחם כנ\"ל, כך ע\"י התנאי' בעלי המשנה בהלכות ברורות שמוציאי' מן הארץ שהוא תושבע\"פ בחכ' שבדיבור דוקא. וזהו משכיל לאיתן אותיות תניא<sup data-n=\"571\">560</sup> בהיפוך אותיות, שהן הברייתות שנק' פלגשים שנק' תניא, כמו תניא נמי הכי<sup data-n=\"572\">561</sup>, תניא דמסייע לך<sup data-n=\"573\">562</sup>, תלי תניא<sup data-n=\"574\">563</sup> כו', והענין הוא דלפי הנ\"ל בח\"ע וח\"ת דדיבור זהו יחוד משפיע ומקבל ממש שהדבור מקבל מח\"ע שבראש תמיד והיחוד תמידי כיחוד דמלך עם המלכה וזהו דמתני' מלכתא כנ\"ל, והתנאי' הן בחי' ממוצעי' לחבר ולייחד יחוד זה מח\"ע לח\"ת בכחם החזק שנק' איתני' מוסדי ארץ כמו בחכ' יסד ארץ בגירסא בדיבור במשנה ששוני' כמו שא' שנו חכמים בלשון המשנה<sup data-n=\"575\">564</sup> ברוך שבחר בהם ובמשנתם. אבל הבריי' ל' בראי בחוץ<sup data-n=\"576\">565</sup>, כמו בשדה חוץ לעיר רק לפרקי' יהי' בהן יחוד והמשכה דח\"ע [כ]פלגשי' שאין היחוד בהן רק לפרקי' ולא בתמידות לפי שהן בלא חופה וקידושין<sup data-n=\"577\">566</sup> כו', וזהו ששים המה מלכות ס' מסכתות דמשניות שמאיר ומתייחד [בהן] מאור א\"ס דח\"ע תמיד כמ\"ש ע\"כ יעזוב איש<sup data-n=\"578\">567</sup> כו' כי מאיש לוקחה זאת מתושב\"כ ונק' עצם מעצמי<sup data-n=\"579\">568</sup> כו', אבל פ' פלגשי' הן הברייתות שהן לבר מגופא כו' שאין המשכות דח\"ע בהן רק לפרקי' לבד כו' וד\"ל.\n[יט] <b>ולהבין</b> ביאור זה. הנה יש להקדים ענין א' הידוע ומבואר במ\"א במ\"ש לבך יהגה אימה<sup data-n=\"580\">569</sup> איה סופר איה שוקל כו', וא' איה סופר שסופרי' כל אותיות שבתורה<sup data-n=\"581\">570</sup> ושוקל ששוקלי' ומודדי' כו', והן הנק' סופרים כמו דקדוקי סופרים<sup data-n=\"582\">571</sup> ומצות שהן מד\"ס כזמד\"ר<sup data-n=\"583\">572</sup> שהוסיפו חכמים על <span data-k=\"pg\">יז</span> ּ מצות דאוריי'",[["567","556","<b>איתן מושביך</b>: בלק כד, כא ובת\"א. ר\"ה יא, א."],["568","557","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א. ראה מאמרי אדה\"א דברים ח\"ב ע' שסט וע' שעא."],["569","558","<b>משכיל אל דל</b>: תהלים מא, ב."],["570","559","<b>ב\"ן שהוא מל'</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ג. הנסמן בשער היחוד קמה, א הערה 14."],["571","560","<b>לאיתן אותיות תניא</b>: ראה זהר (רע\"מ) תצא רעח, ב. (רע\"מ) פינחס רלח, ב. ת\"ז תכ\"א (מד, רע\"א). ת\"ע (קכ, ב). (סבא) משפטים קי, ב. מאמרי אדה\"א דברים ח\"ב ע' שפו."],["572","561","<b>תניא נמי הכי</b>: ברכות ז, ב. ועוד."],["573","562","<b>תניא דמסייע לך</b>: שבת קמו, ב. ועוד."],["574","563","<b>תלי תניא</b>: שבת כב, א. כתובות ב, א. בבא בתרא קלד, ב."],["575","564","<b>שנו חכמים בלשון המשנה</b>: אבות רפ\"ו."],["576","565","<b>הברייתא ל' בראי בחוץ</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קיד. וש\"נ."],["577","566","<b>[כ]פלגשי'. . בלא חופה וקידושין</b>: ראה גם לקמן טו, א. מאמרי אדה\"א ויקרא שם ע' קטו ובהנסמן לשם."],["578","567","<b>ע\"כ יעזוב איש</b>: בראשית ב, כד."],["579","568","<b>כי מאיש. . עצם מעצמי</b>: בראשית שם, כג."],["580","569","<b>לבך יהגה אימה</b>: ישעי' לג, יח. ראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' נה ואילך."],["581","570","<b>שסופרי' כל אותיות שבתורה</b>: קידושין ל, א."],["582","571","<b>דקדוקי סופרים</b>: סוכה כח, א."],["583","572","<b>כזמד\"ר</b>: כז' מצות דרבנן. ראה אגה\"ק סכ\"ט. ד\"ח פנ\"ו. פס\"ד. לקו\"ש יתרו (כרך כא) ע' 401. שופטים (כרך כט) ע' 104 ואילך."]]],[2300540873,"שבתושב\"כ כעירובין ונט\"י כו' וכה\"ג, וא' עריבים עלי ד\"ס<sup data-n=\"584\">573</sup> יותר מיינה של תורה כמ\"ש כי טובים דודיך מיין<sup data-n=\"585\">574</sup> כו' וכמו ברכות המצות שהן מד\"ס<sup data-n=\"586\">575</sup> וכה\"ג שעריבים יותר מיינה ש\"ת, וזה פלאי לכאורה הלא הסופרי' הללו עיקר למודם באותיות דתושב\"כ שדורשי' וסופרי' כל אות ואות כו' וא\"כ איך יוכל לומר [ש]ד\"ס יותר נעלי' וטובי' מעצם אור דתורה אפי' מיינה ש\"ת (שה[ו]א הסוד גימ' יין<sup data-n=\"587\">576</sup> בפנימי' הח\"ע דתורה כו'). אך הנה ידוע ומבואר במ\"א במ\"ש בס\"י בג' דברים<sup data-n=\"588\">577</sup> ברא העולם בסופר וספר וסיפור (או בספר וסופר וסיפור) וענין ספר וסיפור ידוע שזהו תושב\"כ שנק' ספר, ספר התורה<sup data-n=\"589\">578</sup> כו', ונק' ספר החיים<sup data-n=\"590\">579</sup>, ותושבע\"פ נק' סיפור שמדברי' בדברים בע\"פ כתורה צוה לנו בע\"פ ודברי' שבע\"פ אי אתה<sup data-n=\"591\">580</sup> כו', וכידוע בשרש תושב\"כ ושבע\"פ הן בב' מדרגות בחו\"ב שנק' מוסר אביך ותורת אמך כנ\"ל ובזו\"נ שהן מדות ודבור כו', ושניהם נק' ספר וסיפור ונכלל באותיות דשם הוי' בי\"ה בחו\"ב<sup data-n=\"592\">581</sup> ובו\"ה במדות ודבור כידוע. ולפ\"ז הרי בחי' סופר שסופר כל אותיות שבתו' כסופר ממש שכותב כל סדר האותיות שבתורה ה\"ז בחי' ממוצע בין ספר לסיפור, דמה שמשיג ומבין באותיות הכתובי' שבתושב[\"כ] הוא עצמו המספר בסיפור בדברים בע\"פ בתושבע\"פ שהוא לפרש ולבאר בדרך פרט כל מצוה הכתובה בתושב\"כ בקיצור ורמז ותמצית כו'. והן שנק' סופרי' שהן ת\"ח דח\"ת דתושבע\"פ שדורשי' ומלמדי' מן המקרא כל ההלכות ודינין בפרטו' כנ\"ל, והן המכווני' ומדקדקי' לאמיתי' הרצון והחכ' הגנוז ונעלם באותיות דתושב\"כ בדרך פרטי פרטיות להלכה למעשה בלי תוס' ובלי גרעון כלל בלי נטי' לימין ושמאל כלל ובריבוי ותוספת גדול על הכתוב בתושב\"כ (ולא חכמים אחרים זולתם כלל<sup data-n=\"593\">582</sup> כנ\"ל שהן הנק' תנאי' ואתנים שנק' ממוצעי' בין המלך [וה]מלכה שהוא מח\"ע לח\"ת כו').\n<b>ושרש</b> טעם הדבר הנה ידוע דבחי' סופר יש לו שרש גבוה יותר<sup data-n=\"594\">583</sup> מגופו של החכמה שכתוב בספר באותיות מצומצמי' במדה וגבול כו', וכמו שידוע דגם משה רבע\"ה נק' מחוקק וסופר<sup data-n=\"595\">584</sup> כו', לפי שהביא לאור הח\"ע דעצמו' א\"ס שלתבונתו אין מספר ונק' חכים ולא בחכמה ידיעא כלל, באותיות וצירופי' הללו בתושב\"כ, שמוכרח לומר שיש בנשמתו",[["584","573","<b>עריבים עלי ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם."],["585","574","<b>כי טובים דודיך מיין</b>: שה\"ש א, ב."],["586","575","<b>ברכות המצות שהן מד\"ס</b>: נסמן לקמן מח, ד."],["587","576","<b>הסוד גימ' יין</b>: ראה עירובין סה, סע\"א."],["588","577","<b>בס\"י בג' דברים</b>: ראה שם פ\"א, מ\"א. לקמן פ' בא צה, ד הערה 435."],["589","578","<b>תושב\"כ. . ספר התורה</b>: וילך לא, כו. תבוא כח, סא. נצבים כט, כ. ל, י."],["590","579","<b>תושב\"כ. . ספר החיים</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' עט וע' קנח. ח\"ב ע' תקלא. דברים ח\"א ע' עה וע' שלא. נ\"ך ע' תק. תו\"ח מקץ רכד, א. לקמן פ' תרומה שיג, א."],["591","580","<b>ודברי' שבע\"פ אי אתה</b>: גיטין ס, ב."],["592","581","<b>דשם הוי' בי\"ה בחו\"ב</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["593","582","<b>כלל</b>: יאיזיח: ליתא."],["594","583","<b>סופר. . שרש גבוה יותר</b>: ראה גם מאמרי אדה\"א נ\"ך ע' נו. וש\"נ. תו\"ח מקץ רכד, ב."],["595","584","<b>משה. . מחוקק וסופר</b>: ברכה לג, כא ובתרגום שם. ראה גם לקמן פ' ויקהל שצח, ד. מאמרי אדה\"א דברים ח\"א ס\"ע קצג ואילך. וש\"נ. נ\"ך ס\"ע סה."]]],[2300540882,"שרש גבוה מגופה של ח\"ע זו שגנז והמשיך באותיות הללו (ולכך הי' כבד פה ולשון כנ\"ל). וכמו עד\"מ הסופר שכותב את הספר בדיו שצריך לידע ולעיין היטב בעצמו' כח חכמתו היטב הדק איך להביא כל עומק השכל וסברא כמו שהיא לאמיתתה ועומקה ורוחבה רק בצרופי' דאותיות הללו כסדר שכותבו בספר ולא באופן צירופי' אחרים שיטה בזה מנקוד' אור עצם השכל וחכ' ההיא, וא\"כ מוכרח לומר שישכיל סופר זה במקור ומקיף דגילוי אור השכל וחכ' זו כמו שבאה מהעלם כח השופע כל שכל שיכול להיות גם בחי' הנביעה מן ההעלם כמו בצנור בדרך עקלתון לחוץ מן הנקוד' [ה]אמת דחכ' זו בעצם מקורה, והוא מה שצריך לפתוח הצנור לגילוי חכמה זו להביאה באותיות כאלה דוקא באופן שיתלבש בהן כל עומק ותמצי' אמיתי' החכ' כמו שהיא בלי נטי' לצדדי' כלל ולא יחסר בה אפי' כקש\"י והכל יהי' גנוז ונעלם באופן המשכת האותיות וצירופי' כאלה דוקא ולא בצירופי' אחרים אפי' בשינוי כ\"ש ממש כו'. ונמצא דכל בחי' ההעלם האמיתי דמקור חכ' ושכל זה העלים והמשיך בציור אותיות אלה הכתובי' <span data-k=\"pg\">36</span> ּ בספר הזה, ואע\"פ שאינו מובן מחיצוני' האותיות והצירופי' רק דברים כפשוטן כמו בשכל וסברא פשוטה, אבל הסופר שכתב הספר יודע היטב מכל תעלומות עומק החכ' שמלובש בצירופי' הללו, וא\"כ שרש חכמתו גבוה מחכ' זו שכתב בספר וד\"ל. וכך יובן במה שמשה נק' מחוקק וסופר שכתב לספר דתושב\"כ, שבהכרח לומר מאחר שגנז והעלים בהמשכות האותיות הללו מעומק דח\"ע העצמי' בלי נטי' כלל אפי' כקש\"י (ולכך יש קרי וכתיב חסר ויתיר וגם קוצי' ותגין כו'), ודאי שהי' שרשו במקיף ומקור העצמי דח\"ע זו שהביא בספר, וזהו כי מן המ\"ע משיתיהו שלמעלה מחכ' שמאין תמצא כו'). וזהו בחי' סופר שלמעלה מספר דחכ' בשרשה (במזל ונוצר כו'), כענין הבן בחכמה וחכם בבינה<sup data-n=\"596\">585</sup> כו' דהבן בחכמה זהו שיכול להביא נקוד' דחכ' באותיות בספר ששרשו למעלה מן החכ' כנ\"ל וד\"ל.\n<b>ועד\"ז</b> יובן ג\"כ בענין הסופרי' שהן ת\"ח שסופרי' כל אותיות שבתורה כמ\"ש איה סופר כו' כנ\"ל, דהנה כמו שבחי' סופר הנ\"ל למעלה מחכ' שבאותיות הספר כך הן ממש מדרג' דאותן הסופרי' שהן ת\"ח<sup data-n=\"597\">586</sup> שסופרי' כל אותיות כו', דהנה זהו שא' וחכם בבינה דהיינו כמו שהבן בחכ' הוא להביא מנקוד' ההעלם דחכ' לגילוי בצמצום דאותיות דוקא כנ\"ל, כך הוא במה שיכול להביא ולגלות כל מה שגנוז בהעלם דח\"ע שבאותיות דתושב\"כ לבחי' אותיות הדיבור בפה, דאע\"פ שזהו היפך הכח דס[ו]פר הנ\"ל שמביא ומצמצם לכל העומק וההעלם באותיות מצומצמי', אבל מאותו הכח עצמו שהוא לפי ששרשו במקיף ומקור העצמי דהעלם החכ' (קודם שתבא אף בנביע' בהעלם מצומצם ב[צינ]ור כנ\"ל) הוא הנמשך בכח הסופר הזה עצמו להביא בגילוי בדיבור בפה כל מה שגנ[ו]ז והעלים באותיות הללו",[["596","585","<b>הבן בחכמה וחכם בבינה</b>: ס\"י פ\"א, מ\"ד. ראה לקמן פ' בשלח קצב, ב. קצח, א. מאמרי אדה\"א דברים ח\"ד ע' א'שמו. תו\"ח בראשית מו, א ובהערה 6."],["597","586","<b>שהן ת\"ח</b>: יאטזיז: ליתא. וכנראה נשתרבב מלעיל שו\"ה ועד\"ז."]]]]});
